/*
 * kt_filter_v8.cu - k-Tuplet GPU filter (Phase v8-S0: v7 baseline promotion).
 *
 * LINEAGE
 *   v8 = v7 baseline promotion. No kernel change. Identical filter logic,
 *   identical wheel geometry, identical validate-known and bench paths.
 *   v7 lineage: wheel-offset-iter 2-D launch (G11 insight), cooperative L2/
 *   ext-L2 residues in shared memory, per-thread line-sieve. ~4.42e9
 *   useful-cand/s on RTX 5090 vs v5's 131 Gcand/s raw (940x TTR lift).
 *
 * S0 PURPOSE
 *   Establish kt_filter_v8 as the clean production baseline for the v8
 *   optimization phases (S1 metric cleanup, S2a observability, S2.5 KPI
 *   harness, S5 line-sieve probe, S4 CRT-pair probe).
 *   No metrics, observability, or kernel changes in S0.
 *
 * Build: see src/cuda/Makefile (nvcc -O3 -std=c++17 -lineinfo -arch=sm_120).
 */

