/* Phase 9 T2.1: g_primorial_n_primes is the index of the largest prime in
 * the wheel (zero-indexed in kt_first_primes[]).  Default 11 means the
 * 12-prime 37# wheel — the v8 production baseline.  --primorial 12/13/14
 * lifts to 41#/43#/47# via streaming CRT-join in kt_wheel_crt_join_streaming. */
int g_primorial_n_primes = 11;
const char* g_wheel_expr = NULL;   /* --wheel-expr X#[/Y...], overrides --primorial */
int g_threads = 1;             /* host prove threads, post-GPU */

/* Phase 9 T2.1: catalog of primes used to build wheels.  Index N selects
 * the (N+1)-prime wheel.  kt_first_primes[11] = 37 (production); index
 * 14 = 47 (the deepest T2.1 lifts to).  W20-DEC Phase 2 Step 5: extern
 * in kt_cli.c so --primorial clamp warnings can name the actual prime. */
extern "C" {
const uint32_t kt_first_primes[15] = {
    2u, 3u, 5u, 7u, 11u, 13u, 17u, 19u, 23u, 29u, 31u, 37u, 41u, 43u, 47u
};
}
/* KT_PRIMORIAL_{MIN,MAX,DEFAULT}_IDX now live in kt_cli.h. */

static uint32_t g_active_wheel_primes[KT_WHEEL_EXPR_MAX_PRIMES];
static int      g_active_wheel_n_primes = 0;
static int      g_active_wheel_ceiling_idx = KT_PRIMORIAL_DEFAULT;
static char     g_active_wheel_expr[KT_WHEEL_EXPR_CANON_LEN] = "";
static int      g_active_wheel_from_expr = 0;

static int kt_prepare_active_wheel_config(void) {
    if (g_wheel_expr && *g_wheel_expr) {
        char err[160];
        int n = 0;
        int ceiling_idx = -1;
        char canon[KT_WHEEL_EXPR_CANON_LEN];
        if (kt_wheel_parse_expr(g_wheel_expr,
                                kt_first_primes,
                                (int)(sizeof kt_first_primes / sizeof kt_first_primes[0]),
                                g_active_wheel_primes,
                                &n,
                                &ceiling_idx,
                                canon, sizeof canon,
                                err, sizeof err) != 0) {
            fprintf(stderr, "ERROR: bad --wheel-expr '%s': %s\n",
                    g_wheel_expr, err[0] ? err : "invalid expression");
            return 1;
        }
        g_active_wheel_n_primes = n;
        g_active_wheel_ceiling_idx = ceiling_idx;
        g_active_wheel_from_expr = 1;
        snprintf(g_active_wheel_expr, sizeof g_active_wheel_expr, "%s", canon);
        /* Keep legacy primorial_n identity aligned to the expression's X# ceiling.
         * Checkpoint safety comes from the separate wheel_expr identity field. */
        g_primorial_n_primes = ceiling_idx;
        return 0;
    }

    if (g_primorial_n_primes < 0 ||
        g_primorial_n_primes >= (int)(sizeof kt_first_primes / sizeof kt_first_primes[0])) {
        fprintf(stderr, "ERROR: primorial index %d outside supported catalog\n",
                g_primorial_n_primes);
        return 1;
    }
    g_active_wheel_n_primes = g_primorial_n_primes + 1;
    for (int i = 0; i < g_active_wheel_n_primes; i++) {
        g_active_wheel_primes[i] = kt_first_primes[i];
    }
    g_active_wheel_ceiling_idx = g_primorial_n_primes;
    g_active_wheel_from_expr = 0;
    snprintf(g_active_wheel_expr, sizeof g_active_wheel_expr, "%u#",
             kt_first_primes[g_primorial_n_primes]);
    return 0;
}

static const char *kt_checkpoint_wheel_expr_identity(void) {
    return g_active_wheel_from_expr ? g_active_wheel_expr : "none";
}

