/* =============================================================================
 * Phase 3c: three-stage filter prime bands (k-tuplet baseline; 37# wheel
 * already covers all primes up to 37, so L2 starts at 41).
 *
 *   L2:     {41, 43, 47, 53, 59, 61}      (6 primes; q < 64; one u64 mask)
 *   ext-L2: {67, 71, 73, 79, 83, 89, 97}  (7 primes; q < 128; lo/hi u64 pair)
 *   line:   primes 101..863               (125 primes; packed bitvec, 14 u64s)
 *
 * Mirrors the sister Cunningham-chain GPU filter structure with chain-element
 * math replaced by additive k-tuplet offsets.
 * Forbidden-residue source: F_q = { (q - (b_i%q))%q : i in 0..k-1 }, deduped.
 * ========================================================================== */
#define KT_L2_COUNT      6
#define KT_EXT_L2_COUNT  7
#define KT_LINE_COUNT    125
#define KT_LINE_KILL_WORDS 14   /* 14 * 64 = 896 > 863 (largest line prime) */

/* KT_STAGE_L2 / EXT_L2 / LINE / FERMAT now live in kt_cli.h (consumed by
 * parse_argv's --no-stage-* flags).  KT_STAGES_ALL stays here — engine-only. */
#define KT_STAGES_ALL   (KT_STAGE_L2 | KT_STAGE_EXT_L2 | KT_STAGE_LINE | KT_STAGE_FERMAT)

#define KT_MAX_SURVIVORS_PER_BATCH (1u << 20)   /* same as v15 */

static const uint32_t kt_l2_primes_h[KT_L2_COUNT] =
    { 41, 43, 47, 53, 59, 61 };
static const uint32_t kt_ext_l2_primes_h[KT_EXT_L2_COUNT] =
    { 67, 71, 73, 79, 83, 89, 97 };
static const uint32_t kt_line_primes_h[KT_LINE_COUNT] = {
    101, 103, 107, 109, 113, 127, 131, 137, 139, 149,
    151, 157, 163, 167, 173, 179, 181, 191, 193, 197,
    199, 211, 223, 227, 229, 233, 239, 241, 251, 257,
    263, 269, 271, 277, 281, 283, 293, 307, 311, 313,
    317, 331, 337, 347, 349, 353, 359, 367, 373, 379,
    383, 389, 397, 401, 409, 419, 421, 431, 433, 439,
    443, 449, 457, 461, 463, 467, 479, 487, 491, 499,
    503, 509, 521, 523, 541, 547, 557, 563, 569, 571,
    577, 587, 593, 599, 601, 607, 613, 617, 619, 631,
    641, 643, 647, 653, 659, 661, 673, 677, 683, 691,
    701, 709, 719, 727, 733, 739, 743, 751, 757, 761,
    769, 773, 787, 797, 809, 811, 821, 823, 827, 829,
    839, 853, 857, 859, 863
};

/* Survivor record (Phase 3d). 16-byte cand (u128) + pattern_idx slot for
 * future multi-pattern launches. The legacy u64 paths (T8/T11/T12) write
 * the low limb only; cand_hi is zero for those. */
typedef struct __align__(16) {
    uint64_t cand_lo;
    uint64_t cand_hi;
    uint32_t pattern_idx;
    uint32_t _pad;
} KtSurvivor;

/* Constant-memory mirrors of the prime tables and L2 / ext-L2 masks. */
__constant__ uint32_t d_kt_l2_primes[KT_L2_COUNT];
__constant__ uint32_t d_kt_ext_l2_primes[KT_EXT_L2_COUNT];
__constant__ uint32_t d_kt_line_primes[KT_LINE_COUNT];
__constant__ uint64_t d_kt_l2_mask[KT_L2_COUNT];
__constant__ uint64_t d_kt_ext_l2_mask_lo[KT_EXT_L2_COUNT];
__constant__ uint64_t d_kt_ext_l2_mask_hi[KT_EXT_L2_COUNT];

/* S2b-F2: RCU dual-bank mirror of L2 / ext-L2 mask tables (default OFF).
 * Hot-path kernels read the single-bank symbols above; these dual-bank symbols
 * are populated by build_and_upload_filter_tables() when --enable-f2-rcu is set
 * and are exercised only by kt_f2_probe_kernel. At flag-OFF, no device code
 * references these symbols, so PTX/SASS for the hot path is byte-identical to
 * the v8 baseline (any diff is limited to constant-mem layout, per F22/F23
 * precedent). Infrastructure for T2.x live wheel-rotation / longevity runs. */
__constant__ uint64_t d_kt_l2_mask_rcu[2][KT_L2_COUNT];
__constant__ uint64_t d_kt_ext_l2_mask_lo_rcu[2][KT_EXT_L2_COUNT];
__constant__ uint64_t d_kt_ext_l2_mask_hi_rcu[2][KT_EXT_L2_COUNT];
__device__   uint32_t d_kt_filter_version = 0;

/* Pattern offsets for the Fermat-2 stage (Phase 3d). Loaded once at startup
 * for the active pattern; KT_MAX_K=32 is the catalog cap (KT_MAX_K from
 * ktuplet_pattern.h). */
__constant__ uint32_t d_kt_pattern_offsets[KT_MAX_K];
__constant__ int      d_kt_pattern_k = 0;

/* Phase 4a-3: Barrett reciprocal mu = floor(2^128 / d_primorial), uploaded
 * once per launch by build_and_upload_stage0_wheel(). The hot kernel reads
 * this from __constant__ mem to replace the 64-iter shift-and-add loop in
 * kt_u128_mod_u64 with a single 128x128 multiply (kt_u128_mod_u64_barrett). */
__constant__ kt_u128 d_primorial_mu = {0, 0};

/* S2a F18: per-(line_prime, residue) yield counters at Fermat-stage entry.
 * d_f18_yield_enabled is __constant__ so the branch is warp-uniform.
 * KT_F18_MAX_RES covers the largest line-sieve prime (863). */
#define KT_F18_MAX_RES 1024
__constant__ int d_f18_yield_enabled = 0;
__device__ unsigned long long d_f18_yield_counters[KT_LINE_COUNT][KT_F18_MAX_RES];

/* S2a F22: approximate reservoir sampling of post-Fermat survivors (Algo R).
 * 1000 slots; d_f22_enabled controls sampling. */
#define KT_F22_RESERVOIR_SIZE 1000
typedef struct { uint64_t cand_lo; uint64_t cand_hi; uint32_t flags; uint32_t _pad; } KtF22ReservoirSlot;
__constant__ int d_f22_enabled = 0;
__device__ unsigned long long d_f22_counter = 0;
__device__ KtF22ReservoirSlot d_f22_reservoir[KT_F22_RESERVOIR_SIZE];

/* S2b-F23: texture fingerprint reservoir. 128 slots × 40 bytes.
 * Reservoir-samples post-cascade survivors (Vitter Algo R approx); mask is
 * all-zero for survivors (they passed every prime). Field preserved for a
 * future Stage-0-admissible sampling extension. Default OFF; activated by
 * --enable-f23-texture. Branch is __constant__-guarded so OFF state produces
 * identical PTX/SASS to baseline. */
#define KT_F23_RESERVOIR_SIZE 128
typedef struct {
    uint64_t cand_lo;
    uint64_t cand_hi;
    uint64_t mask0;       /* kill mask bits 0..63   (all-zero for survivors) */
    uint64_t mask1;       /* kill mask bits 64..127 */
    uint64_t mask2;       /* kill mask bits 128..137 (high 54 bits unused) */
} KtF23TextureSlot;
__constant__ int d_f23_enabled = 0;
__device__ unsigned long long d_f23_counter = 0;
__device__ KtF23TextureSlot d_f23_reservoir[KT_F23_RESERVOIR_SIZE];

/* W18-K: per-stage kill-position counters for the v7 cascade.  Always-on
 * (no __constant__ gate — this is the alignment-regression trip-wire).
 * Counts threads that PASSED each stage; kills at stage X = passed_(X-1)
 * - passed_X.  Warp-aggregated atomicAdd keeps the per-launch cost at
 * one atomic per active warp per stage (~22K-warp × 5-stage = 110K atomics
 * per batch on a saturated 5090, dominated by L1 atomic latency, not the
 * cascade compute). */
__device__ unsigned long long d_w18k_admit       = 0;  /* entered cascade (post Stage-0 admit-by-indexing) */
__device__ unsigned long long d_w18k_pass_l2     = 0;
__device__ unsigned long long d_w18k_pass_ext_l2 = 0;
__device__ unsigned long long d_w18k_pass_line   = 0;
__device__ unsigned long long d_w18k_pass_fermat = 0;

/* Line-sieve packed kill mask in global memory (125*14 u64 = 14 KiB). The
