#define CUDA_CHECK(call) do { \
    cudaError_t e = (call); \
    if (e != cudaSuccess) { \
        fprintf(stderr, "CUDA error %s at %s:%d: %s\n", \
                cudaGetErrorString(e), __FILE__, __LINE__, #call); \
        exit(2); \
    } \
} while (0)

static double wall_time_sec(void) {
    /* W18-I (multi-angle N6): CLOCK_MONOTONIC, not gettimeofday — the latter
     * can step backward on NTP corrections, which would make `(now - t0)`
     * briefly negative and corrupt the reporter / min-util sampler.
     * CLOCK_MONOTONIC is monotonic-non-decreasing by POSIX contract. */
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        /* Defensive: fall back to gettimeofday if the monotonic clock isn't
         * available (kernel < 2.5.63 — won't happen on this platform).  The
         * absolute value is irrelevant; only diffs matter. */
        struct timeval tv;
        gettimeofday(&tv, NULL);
        return (double)tv.tv_sec + (double)tv.tv_usec * 1e-6;
    }
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1e-9;
}

/* =============================================================================
 * Phase v8-Sobs-A §1.2 fix: total_cand counter promoted from u64 to u128 so
 * 30-min cells at b110+ no longer wrap mid-run.  The two helpers below format
 * a u128 to decimal (for "cand=..." prints + JSONL number emit) and convert
 * a u128 to double (for "cand/s" rate computation, exact to ~53 bits).
 *
 * Format helper writes up to 39 decimal digits + NUL.  Caller provides buf;
 * if buflen < 40 the result is truncated (returns "0").
 *
 * Double-conversion helper avoids reliance on libgcc's __floattidf which is
 * present on linux/x86_64 builds with cuda 13.2 but not guaranteed across
 * toolchains; we open-code (double)hi * 2^64 + (double)lo.
 * ========================================================================== */
void kt_u128_format_dec(unsigned __int128 v, char *buf, size_t buflen) {
    if (!buf || buflen == 0) return;
    if (buflen < 2) { buf[0] = '\0'; return; }
    if (v == 0) { buf[0] = '0'; buf[1] = '\0'; return; }
    char tmp[40];
    int  n = 0;
    while (v != 0 && n < (int)sizeof(tmp)) {
        unsigned int d = (unsigned int)(v % 10u);
        tmp[n++] = (char)('0' + d);
        v /= 10u;
    }
    if ((size_t)n + 1 > buflen) {
        /* Truncation: report zero-string to make the bug obvious upstream. */
        buf[0] = '0';
        buf[1] = '\0';
        return;
    }
    for (int i = 0; i < n; i++) buf[i] = tmp[n - 1 - i];
    buf[n] = '\0';
}

static double kt_u128_to_double(unsigned __int128 v) {
    /* 2^64 = 18446744073709551616.0; loss limited to ~53 mantissa bits. */
    uint64_t hi = (uint64_t)(v >> 64);
    uint64_t lo = (uint64_t)v;
    return (double)hi * 18446744073709551616.0 + (double)lo;
}

/* =============================================================================
 * Phase v8-Sobs-B (§0.3): host-side Bloom filter for chunk-anchor revisit
 * detection.  Sized 524288 bits = 64 KiB, k=4 hash streams via FNV-1a-64
 * mixed with golden-ratio rotors.  False-positive rate is well under 0.01 %
 * for the sweep cell sizes we care about (≤10k anchors per cell at b101).
 *
 * API:
 *   kt_bloom_alloc()   → zero-initialized Bloom (NULL on OOM).
 *   kt_bloom_free()
 *   kt_bloom_probe()   → 1 if all k bits already set (likely-seen), 0 otherwise.
 *   kt_bloom_insert()  → set all k bits.
 *   kt_bloom_test_and_insert() → atomic probe-then-insert; returns 1 if seen.
 *
 * Each anchor is keyed on (anchor_high_bits | anchor_bits).  Sequential and
 * sequential-prefix modes don't pick new anchors; the Bloom is allocated for
 * uniformity but never probes/inserts past the initial anchor.
 * ========================================================================== */
#define KT_BLOOM_BITS  524288u            /* 2^19 */
#define KT_BLOOM_BYTES (KT_BLOOM_BITS / 8u)
#define KT_BLOOM_K     4u

typedef struct KtBloom {
    uint8_t bits[KT_BLOOM_BYTES];
    unsigned long long inserts;
    unsigned long long revisits;
} KtBloom;

KtBloom *kt_bloom_alloc(void) {
    KtBloom *b = (KtBloom*)calloc(1, sizeof(KtBloom));
    return b;
}

void kt_bloom_free(KtBloom *b) {
    if (b) free(b);
}

/* FNV-1a-64 over an 8-byte little-endian key, then split into k=4 streams via
 * golden-ratio rotors so a single u64 input produces 4 independent indices. */
static inline void kt_bloom_indices(uint64_t key, uint32_t out[KT_BLOOM_K]) {
    uint64_t h = 0xcbf29ce484222325ULL;
    static const uint64_t prime = 0x100000001b3ULL;
    for (int b = 0; b < 8; b++) {
        uint8_t byte = (uint8_t)((key >> (8 * b)) & 0xff);
        h ^= (uint64_t)byte;
        h *= prime;
    }
    static const uint64_t rotors[KT_BLOOM_K] = {
        0x9e3779b97f4a7c15ULL,
        0xbf58476d1ce4e5b9ULL,
        0x94d049bb133111ebULL,
        0xd6e8feb86659fd93ULL,
    };
    for (uint32_t i = 0; i < KT_BLOOM_K; i++) {
        uint64_t v = h ^ rotors[i];
        v ^= v >> 33;
        v *= 0xff51afd7ed558ccdULL;
        v ^= v >> 33;
        out[i] = (uint32_t)(v & (uint64_t)(KT_BLOOM_BITS - 1u));
    }
}

int kt_bloom_probe(const KtBloom *b, uint64_t key) {
    if (!b) return 0;
    uint32_t idx[KT_BLOOM_K];
    kt_bloom_indices(key, idx);
    for (uint32_t i = 0; i < KT_BLOOM_K; i++) {
        if (((b->bits[idx[i] >> 3] >> (idx[i] & 7u)) & 1u) == 0u) return 0;
    }
    return 1;
}

void kt_bloom_insert(KtBloom *b, uint64_t key) {
    if (!b) return;
    uint32_t idx[KT_BLOOM_K];
    kt_bloom_indices(key, idx);
    for (uint32_t i = 0; i < KT_BLOOM_K; i++) {
        b->bits[idx[i] >> 3] |= (uint8_t)(1u << (idx[i] & 7u));
    }
    b->inserts++;
}

/* Probe-then-insert.  Returns 1 if the key was likely already present.
 * Caller can decide whether to bump revisits + emit a [WARN] line. */
int kt_bloom_test_and_insert(KtBloom *b, uint64_t key) {
    int seen = kt_bloom_probe(b, key);
    kt_bloom_insert(b, key);
    if (seen) b->revisits++;
    return seen;
}

/* =============================================================================
 * Phase v8-Sobs-B (§0.1): anchor-key derivation.  We key the Bloom on the
 * high `anchor_bits` of the cursor (i.e., the chunk anchor), so that within a
 * single cell, the same anchor recurring after a PRNG self-collision is
 * detected even when the per-tile cursor advances by primorial.
 *
 * For sequential / sequential-prefix modes anchor_bits is g_prefix_bits
 * (or 0 for unbounded sequential) and the anchor is g_prefix_value_u128.
 * For random mode (Phase 4-GPU, live), anchor_bits is the chunk-anchor pin
 * width (g_prefix_bits in prefix mode, g_target_bits-1 otherwise) and the
 * anchor rotates each batch via the xorshift64* draw in run_search_loop.
 * ========================================================================== */
uint64_t kt_anchor_key(unsigned __int128 anchor, int anchor_bits) {
    /* Combine anchor's high 64 bits + anchor_bits into a single u64 key. */
    uint64_t hi = (uint64_t)(anchor >> 64);
    uint64_t lo = (uint64_t)anchor;
    /* Mix anchor_bits into the key so two different chunk widths with the
     * same high bits don't collide spuriously. */
    return hi ^ (lo * 0x9e3779b97f4a7c15ULL) ^ ((uint64_t)anchor_bits * 0xc6bc279692b5c323ULL);
}

/* =============================================================================
 * Phase 9 T1.2: checkpoint save / load.  W20-DEC Phase 1 Step 2 moved the
 * raw file I/O (write + parse, atomic via tmp+rename+dir-fsync) to
 * src/cuda/kt_checkpoint.{c,h}.  The wrappers below thread global state
 * (g_target_bits, g_pattern, g_prefix_mode, g_random_seed_*, etc.) through
 * the kt_checkpoint_t struct and host the identity-validation logic that
 * stays coupled to engine state.
 *
 * W18-B drain-boundary invariant: `cursor`, `total_cand`, `total_surv`,
 * `total_hits`, and `batches` are all captured at the SAME drain boundary
 * (state after every batch whose survivors have been fully processed).
 * On resume the loop picks up at the saved cursor and re-launches in-flight
 * batches — graceful-shutdown safe; SIGKILL-mid-flight resume re-does the
 * in-flight batches (idempotent — same survivors → same hits → log dedupes).
 * ========================================================================== */
static int kt_checkpoint_save(const char *path,
                              unsigned __int128 cursor,
                              unsigned __int128 total_cand,
                              unsigned long long total_surv,
                              int total_hits,
                              int batches,
                              int exhausted) {
    if (!path || !*path) return -1;
    kt_checkpoint_t ck;
    memset(&ck, 0, sizeof ck);
    ck.bits           = g_target_bits;
    ck.target_k       = g_target_k;
    ck.primorial_n    = g_primorial_n_primes;
    {
        const char *pat = g_pattern ? g_pattern->name : "none";
        strncpy(ck.pattern_name, pat, sizeof ck.pattern_name - 1);
        ck.pattern_name[sizeof ck.pattern_name - 1] = '\0';
    }
    {
        const char *we = kt_checkpoint_wheel_expr_identity();
        strncpy(ck.wheel_expr, we, sizeof ck.wheel_expr - 1);
        ck.wheel_expr[sizeof ck.wheel_expr - 1] = '\0';
    }
    {
        const char *pfx = g_use_prefix && g_prefix_str ? g_prefix_str : "none";
        strncpy(ck.prefix, pfx, sizeof ck.prefix - 1);
        ck.prefix[sizeof ck.prefix - 1] = '\0';
    }
    {
        const char *pm = (g_prefix_mode == KT_PREFIX_MODE_SEQ)    ? "sequential"
                       : (g_prefix_mode == KT_PREFIX_MODE_RANDOM) ? "random"
                       :                                           "inherit";
        strncpy(ck.prefix_mode, pm, sizeof ck.prefix_mode - 1);
        ck.prefix_mode[sizeof ck.prefix_mode - 1] = '\0';
    }
    ck.prefix_lanes   = g_prefix_lanes;
    ck.prefix_lane_id = g_prefix_lane_id;
    ck.seed           = (uint64_t)g_random_seed_used;
    ck.seed_present   = 1;
    ck.cursor         = cursor;
    ck.total_cand     = total_cand;
    ck.total_surv     = total_surv;
    ck.total_hits     = total_hits;
    ck.batches        = batches;
    ck.exhausted      = exhausted ? 1 : 0;
    return kt_checkpoint_write(path, &ck);
}

/* Returns 0 on successful load (out_* populated), 1 on soft fail (start fresh,
 * stderr-logged), -1 on hard error.  Caller treats both 1 and -1 as "do not
 * resume".  Validates against current invocation's (bits, target_k, pattern,
 * prefix, lanes, lane_id, primorial_n, prefix_mode, seed). */
static int kt_checkpoint_load(const char *path,
                              unsigned __int128 *out_cursor,
                              unsigned __int128 *out_total_cand,
                              unsigned long long *out_total_surv,
                              int *out_total_hits,
                              int *out_batches,
                              int *out_exhausted) {
    if (!path || !*path) return -1;
    kt_checkpoint_t ck;
    int rc = kt_checkpoint_read(path, &ck);
    if (rc != 0) return rc;

    if (ck.bits != g_target_bits) {
        fprintf(stderr, "[RESUME] bits=%d != current --bits %d — starting fresh\n",
                ck.bits, g_target_bits);
        return 1;
    }
    if (ck.target_k != g_target_k) {
        fprintf(stderr, "[RESUME] target_k=%d != current --k %d — starting fresh\n",
                ck.target_k, g_target_k);
        return 1;
    }
    const char *cur_pat = g_pattern ? g_pattern->name : "none";
    if (strcmp(ck.pattern_name, cur_pat) != 0) {
        fprintf(stderr, "[RESUME] pattern=%s != current %s — starting fresh\n",
                ck.pattern_name, cur_pat);
        return 1;
    }
    const char *cur_prefix = g_use_prefix && g_prefix_str ? g_prefix_str : "none";
    if (strcmp(ck.prefix, cur_prefix) != 0) {
        fprintf(stderr, "[RESUME] prefix=%s != current %s — starting fresh\n",
                ck.prefix, cur_prefix);
        return 1;
    }
    if (ck.prefix_lanes != g_prefix_lanes) {
        fprintf(stderr, "[RESUME] prefix_lanes=%d != current %d — starting fresh\n",
                ck.prefix_lanes, g_prefix_lanes);
        return 1;
    }
    if (ck.prefix_lane_id != g_prefix_lane_id) {
        fprintf(stderr, "[RESUME] prefix_lane_id=%d != current %d — starting fresh\n",
                ck.prefix_lane_id, g_prefix_lane_id);
        return 1;
    }
    /* W18-C: primorial_n match (older pre-W18-C ckpts have primorial_n=-1
     * from the reader; skip the check for backward-compat). */
    if (ck.primorial_n >= 0 && ck.primorial_n != g_primorial_n_primes) {
        fprintf(stderr, "[RESUME] primorial_n=%d != current %d — starting fresh\n",
                ck.primorial_n, g_primorial_n_primes);
        return 1;
    }
    if (ck.wheel_expr[0] != '\0') {
        const char *cur_we = kt_checkpoint_wheel_expr_identity();
        if (strcmp(ck.wheel_expr, cur_we) != 0) {
            fprintf(stderr, "[RESUME] wheel_expr=%s != current %s — starting fresh\n",
                    ck.wheel_expr, cur_we);
            return 1;
        }
    } else if (g_active_wheel_from_expr) {
        fprintf(stderr,
                "[RESUME] checkpoint has no wheel_expr field but current run "
                "uses --wheel-expr '%s' — starting fresh\n",
                g_active_wheel_expr);
        return 1;
    }
    /* W19-B-3: refuse random-mode ckpts unconditionally (coverage gap on
     * SIGKILL recovery; random-rotated batches cannot be replayed
     * deterministically). */
    if (ck.prefix_mode[0] != '\0' && strcmp(ck.prefix_mode, "random") == 0) {
        fprintf(stderr,
            "[RESUME] ckpt prefix_mode=random; coverage gap on SIGKILL recovery "
            "(random-rotated batches cannot be replayed deterministically) — "
            "starting fresh\n");
        return 1;
    }
    /* W18-C: prefix_mode match against current invocation (skip if absent
     * in pre-W18-C ckpts). */
    if (ck.prefix_mode[0] != '\0') {
        const char *cur_pm =
            (g_prefix_mode == KT_PREFIX_MODE_SEQ)    ? "sequential" :
            (g_prefix_mode == KT_PREFIX_MODE_RANDOM) ? "random"     :
                                                      "inherit";
        if (strcmp(ck.prefix_mode, cur_pm) != 0) {
            fprintf(stderr, "[RESUME] prefix_mode=%s != current %s — starting fresh\n",
                    ck.prefix_mode, cur_pm);
            return 1;
        }
    }
    /* W18-C + W19-B-2: seed reconciliation.
     *   - Explicit --random-seed: enforce match; soft-fail on mismatch.
     *   - No --random-seed: adopt ckpt's seed if present (including seed=0). */
    if (g_random_seed_explicit) {
        if (ck.seed_present &&
            ck.seed != (unsigned long long)g_random_seed_used) {
            fprintf(stderr,
                "[RESUME] seed=0x%016llx != current --random-seed 0x%016llx — starting fresh\n",
                (unsigned long long)ck.seed, (unsigned long long)g_random_seed_used);
            return 1;
        }
    } else if (ck.seed_present) {
        if (ck.seed != (unsigned long long)g_random_seed_used) {
            fprintf(stderr,
                "[RESUME] adopting ckpt seed=0x%016llx (was engine-default 0x%016llx)\n",
                (unsigned long long)ck.seed, (unsigned long long)g_random_seed_used);
            g_random_seed_used = (uint64_t)ck.seed;
            g_rng_state        = (uint64_t)ck.seed ? (uint64_t)ck.seed : 1ULL;
        }
    }
    if (out_cursor)     *out_cursor     = ck.cursor;
    if (out_total_cand) *out_total_cand = ck.total_cand;
    if (out_total_surv) *out_total_surv = ck.total_surv;
    if (out_total_hits) *out_total_hits = ck.total_hits;
    if (out_batches)    *out_batches    = ck.batches;
    if (out_exhausted)  *out_exhausted  = ck.exhausted;
    fprintf(stderr,
        "[RESUME] loaded cursor=0x%016llx%016llx batches=%d total_cand=0x%016llx%016llx\n",
        (unsigned long long)(ck.cursor >> 64), (unsigned long long)ck.cursor,
        ck.batches,
        (unsigned long long)(ck.total_cand >> 64), (unsigned long long)ck.total_cand);
    return 0;
}

/* =============================================================================
 * Stub kernel (3a) - kept for the --test T3 path which anchors a ceiling
 * reference for kernel-launch + atomicAdd cost. Real candidate generation
 * runs through kt_stage0_admissibility_kernel below.
 * ========================================================================== */
__global__ void kt_scaffold_count_kernel(unsigned long long *counter,
                                         unsigned long long n_per_thread) {
    atomicAdd(counter, n_per_thread);
}

/* =============================================================================
 * Stage-0 admissibility kernel (Phase 3b).
 *
 *   cand = base_n + tid * stride          (u64 path; n <= 60-bit smoke)
 *   r    = cand mod primorial
 *   binary search r in d_admissible_offsets[0..n_admissible-1]
 *
 * Stages 1/2/3 (filter primes, BPSW) land in 3c/3d. The reporter prints
 * cand/s and surv/s; rejection ratio = 1 - surv/cand.
 *
 * n-bit-width: 3b limits n to 60 bits (so cand fits in u64 with no
 * overflow on cand mod primorial). Phase 3d generalizes to u128 for
 * widths up to 127 bits.
 * ========================================================================== */
__global__ void kt_stage0_admissibility_kernel(
    const uint64_t * __restrict__ d_offsets,
    int                          d_n_admissible,
    unsigned long long           d_primorial,
    unsigned long long           base_n_low,
    unsigned long long           stride_low,
    unsigned long long           batch_size,
    unsigned long long          *survivor_count,
    unsigned long long          *cand_count) {
    unsigned long long tid = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= batch_size) return;

    unsigned long long cand = base_n_low + tid * stride_low;
    unsigned long long r    = cand % d_primorial;

    int lo = 0, hi = d_n_admissible - 1, found = 0;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned long long v = d_offsets[mid];
        if (v == r) { found = 1; break; }
        if (v < r)  lo = mid + 1; else hi = mid - 1;
    }
    atomicAdd(cand_count, 1ULL);
    if (found) atomicAdd(survivor_count, 1ULL);
}

/* =============================================================================
 * Phase 3c: Stage-0 -> L2 -> ext-L2 -> line-sieve cascade.
 *
 *   cand = base_n + tid * stride                (u64 path; n <= 60-bit smoke)
 *   Stage 0: r = cand % primorial; binary-search admissible-offset list.
 *   Stage L2 (KT_L2_COUNT primes < 64): single u64 mask per prime.
 *   Stage ext-L2 (KT_EXT_L2_COUNT primes < 128): lo/hi u64 mask per prime.
 *   Stage line (KT_LINE_COUNT primes 101..863): packed 14-u64 bitvec per prime.
 *
 * Each stage rejects on the first hit (early-return). Survivors emitted via
 * warp-aggregated atomicAdd (v15:1906 idiom). stages_active is a runtime
 * bitmask so 3d/3e can A/B against Stage-0-only or against any subset.
 * ========================================================================== */
__global__ __launch_bounds__(256, KT_LB_BLOCKS)
void kt_stage0_to_line_kernel(
    const uint64_t * __restrict__ d_offsets,
    int                          d_n_admissible,
    unsigned long long           d_primorial,
    unsigned long long           base_n_low,
    unsigned long long           stride_low,
    unsigned long long           batch_size,
    const uint64_t * __restrict__ d_line_kill_packed,  /* 125*14 */
    unsigned int                 stages_active,
    KtSurvivor                  *survivors,
    unsigned int                *survivor_count,
    unsigned int                *survivor_overflow,
    unsigned int                 max_survivors,
    unsigned long long          *cand_count) {
    unsigned long long tid = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
    /* Phase 3f C3: single atomic per launch (was per-thread). NULL-guarded so
     * the production search loop can pass NULL and skip the counter entirely. */
    if (tid == 0 && cand_count) atomicAdd(cand_count, batch_size);
    if (tid >= batch_size) return;

    unsigned long long cand = base_n_low + tid * stride_low;

    /* Stage 0: 37# admissibility wheel. */
    unsigned long long r0 = cand % d_primorial;
    int lo = 0, hi = d_n_admissible - 1, found = 0;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned long long v = d_offsets[mid];
        if (v == r0) { found = 1; break; }
        if (v < r0)  lo = mid + 1; else hi = mid - 1;
    }
    if (!found) return;

    /* Stage L2: 6 primes, single u64 mask each. */
    if (stages_active & KT_STAGE_L2) {
        #pragma unroll
        for (int i = 0; i < KT_L2_COUNT; i++) {
            uint32_t q   = d_kt_l2_primes[i];
            uint32_t r_q = (uint32_t)(cand % q);
            if ((d_kt_l2_mask[i] >> r_q) & 1ULL) return;
        }
    }

    /* Stage ext-L2: 7 primes, lo/hi u64 mask. */
    if (stages_active & KT_STAGE_EXT_L2) {
        #pragma unroll
        for (int i = 0; i < KT_EXT_L2_COUNT; i++) {
            uint32_t q    = d_kt_ext_l2_primes[i];
            uint32_t r_q  = (uint32_t)(cand % q);
            uint64_t word = (r_q < 64) ? d_kt_ext_l2_mask_lo[i]
                                       : d_kt_ext_l2_mask_hi[i];
            if ((word >> (r_q & 63u)) & 1ULL) return;
        }
    }

    /* Stage line-sieve: 125 primes, packed bitvec. v15:1884 prefetch idiom -
     * one block of d_line_kill_packed brings ~10 primes' rows into L1. */
    if (stages_active & KT_STAGE_LINE) {
        asm volatile("prefetch.global.L1 [%0];" :: "l"(&d_line_kill_packed[0]));
        for (int ls = 0; ls < KT_LINE_COUNT; ls++) {
            uint32_t q    = d_kt_line_primes[ls];
            uint32_t r_q  = (uint32_t)(cand % q);
            uint64_t word = d_line_kill_packed[ls * KT_LINE_KILL_WORDS + (r_q >> 6)];
            if ((word >> (r_q & 63u)) & 1ULL) return;
        }
    }

    /* Survivor: warp-aggregated emission per v15:1906. Lower-numbered lane
     * in the surviving set leads the atomicAdd; broadcasted base + per-lane
     * popcount gives the slot index. */
    unsigned active_mask = __activemask();
    unsigned pass_mask   = __ballot_sync(active_mask, 1);
    int lane             = threadIdx.x & 31;
    int leader           = __ffs((int)pass_mask) - 1;
    unsigned int warp_base = 0;
    if (lane == leader) {
        warp_base = atomicAdd(survivor_count, (unsigned int)__popc(pass_mask));
    }
    warp_base = __shfl_sync(pass_mask, warp_base, leader);
    unsigned int slot = warp_base + (unsigned int)__popc(pass_mask & ((1u << lane) - 1u));
    if (slot < max_survivors) {
        survivors[slot].cand_lo     = cand;
        survivors[slot].cand_hi     = 0;
        survivors[slot].pattern_idx = 0;
        survivors[slot]._pad        = 0;
    } else if (survivor_overflow) {
        /* Phase 3f C2: explicit overflow signal (lane scope). Host treats any
         * set bit as fatal; no silent-drop. */
        atomicOr(survivor_overflow, 1u);
    }
}

/* =============================================================================
 * Phase 3d: Stage-0 -> L2 -> ext-L2 -> line-sieve -> Fermat-2 cascade (u128).
 *
 *   cand = base_n + tid * stride         (kt_u128, n <= 127 bits)
 *   Stage 0..line: identical math to 3c, but candidate is u128.
 *   Stage Fermat: per offset b_i, run base-2 Fermat in u128 Montgomery-free
 *   arithmetic (kt_fermat_base2_u128). Reject if any b_i yields composite.
 *
 * Stage gating bitmask carries KT_STAGE_FERMAT for the new stage.
 * ========================================================================== */
__global__ __launch_bounds__(256, KT_LB_BLOCKS)
void kt_stage0_to_fermat_kernel(
    const uint64_t * __restrict__ d_offsets,
    int                          d_n_admissible,
    unsigned long long           d_primorial,
    kt_u128                      base_n,
    kt_u128                      stride,
    unsigned long long           batch_size,
    const uint64_t * __restrict__ d_line_kill_packed,  /* 125*14 */
    unsigned int                 stages_active,
    KtSurvivor                  *survivors,
    unsigned int                *survivor_count,
    unsigned int                *survivor_overflow,
    unsigned int                 max_survivors,
    unsigned long long          *cand_count) {
    unsigned long long tid = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
    /* Phase 3f C3: single atomic per launch (was per-thread). NULL-guarded so
     * the production search loop can pass NULL and skip the counter entirely. */
    if (tid == 0 && cand_count) atomicAdd(cand_count, batch_size);
    if (tid >= batch_size) return;

    /* cand = base_n + tid * stride. tid is u64; stride is u128; multiply via
     * kt_u128_mul64_u128 (returns low 128 bits of u64*u128). */
    kt_u128 step = kt_u128_mul64_u128((uint64_t)tid, stride);
    kt_u128 cand = kt_u128_add(base_n, step);

    /* Stage 0: 37# admissibility wheel. d_primorial fits in u64 (37# = 7.42e12).
     * Phase 4a-3: Barrett reciprocal multiply replaces the shift-and-add
     * reduction loop. mu = floor(2^128/d_primorial) is in __constant__ mem,
     * uploaded once per launch by build_and_upload_stage0_wheel. */
    uint64_t r0 = kt_u128_mod_u64_barrett(cand, d_primorial, d_primorial_mu);
    int lo = 0, hi = d_n_admissible - 1, found = 0;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        /* Phase 4a-2: __ldg routes binary-search reads through the
         * read-only data cache; pointer is __restrict__ + const-qualified. */
        unsigned long long v = __ldg(&d_offsets[mid]);
        if (v == r0) { found = 1; break; }
        if (v < r0)  lo = mid + 1; else hi = mid - 1;
    }
    if (!found) return;

    /* Stage L2: 6 primes. */
    if (stages_active & KT_STAGE_L2) {
        #pragma unroll
        for (int i = 0; i < KT_L2_COUNT; i++) {
            uint32_t q   = d_kt_l2_primes[i];
            uint32_t r_q = kt_u128_mod_u32(cand, q);
            if ((d_kt_l2_mask[i] >> r_q) & 1ULL) return;
        }
    }

    /* Stage ext-L2: 7 primes, lo/hi u64 mask. */
    if (stages_active & KT_STAGE_EXT_L2) {
        #pragma unroll
        for (int i = 0; i < KT_EXT_L2_COUNT; i++) {
            uint32_t q    = d_kt_ext_l2_primes[i];
            uint32_t r_q  = kt_u128_mod_u32(cand, q);
            uint64_t word = (r_q < 64) ? d_kt_ext_l2_mask_lo[i]
                                       : d_kt_ext_l2_mask_hi[i];
            if ((word >> (r_q & 63u)) & 1ULL) return;
        }
    }

    /* Stage line-sieve: 125 primes, packed bitvec.
     * Phase 4a-2: removed the index-0 prefetch (it always fetched
     * d_line_kill_packed[0] regardless of r_q, so it warmed an
     * unrelated cache line). A useful row-targeted prefetch needs the
     * per-tile residue cache from Phase 4b-1; until then, no prefetch.
     * __ldg routes the line-sieve read through the read-only cache. */
    if (stages_active & KT_STAGE_LINE) {
        for (int ls = 0; ls < KT_LINE_COUNT; ls++) {
            uint32_t q    = d_kt_line_primes[ls];
            uint32_t r_q  = kt_u128_mod_u32(cand, q);
            uint64_t word = __ldg(&d_line_kill_packed[ls * KT_LINE_KILL_WORDS + (r_q >> 6)]);
            if ((word >> (r_q & 63u)) & 1ULL) return;
        }
    }

    /* S2a F18: per-(line_prime, residue) yield counters at Fermat-stage entry.
     * Branch is warp-uniform (d_f18_yield_enabled is __constant__). */
    if (d_f18_yield_enabled) {
        for (int ls = 0; ls < KT_LINE_COUNT; ls++) {
            uint32_t q   = d_kt_line_primes[ls];
            uint32_t r_q = kt_u128_mod_u32(cand, q);
            atomicAdd(&d_f18_yield_counters[ls][r_q], 1ULL);
        }
    }

    /* Stage Fermat-2: k tests on n + b_i. Reject if any composite. */
    if (stages_active & KT_STAGE_FERMAT) {
        int kk = d_kt_pattern_k;
        for (int i = 0; i < kk; i++) {
            uint64_t off = (uint64_t)d_kt_pattern_offsets[i];
            kt_u128 cand_i;
            cand_i.lo = cand.lo + off;
            cand_i.hi = cand.hi + (cand_i.lo < cand.lo ? 1 : 0);
            if (!kt_fermat_base2_u128(cand_i)) return;
        }
    }

    /* Survivor: warp-aggregated emission. */
    unsigned active_mask = __activemask();
    unsigned pass_mask   = __ballot_sync(active_mask, 1);
    int lane             = threadIdx.x & 31;
    int leader           = __ffs((int)pass_mask) - 1;
    unsigned int warp_base = 0;
    if (lane == leader) {
        warp_base = atomicAdd(survivor_count, (unsigned int)__popc(pass_mask));
    }
    warp_base = __shfl_sync(pass_mask, warp_base, leader);
    unsigned int slot = warp_base + (unsigned int)__popc(pass_mask & ((1u << lane) - 1u));
    if (slot < max_survivors) {
        survivors[slot].cand_lo     = cand.lo;
        survivors[slot].cand_hi     = cand.hi;
        survivors[slot].pattern_idx = 0;
        survivors[slot]._pad        = 0;
    } else if (survivor_overflow) {
        /* Phase 3f C2: explicit overflow signal. Host fail-fasts on this. */
        atomicOr(survivor_overflow, 1u);
    }

    /* S2a F22: reservoir-sample this survivor (approximate Algo R). */
    if (d_f22_enabled) {
        unsigned long long my_idx = atomicAdd(&d_f22_counter, 1ULL);
        unsigned long long j;
        if (my_idx < (unsigned long long)KT_F22_RESERVOIR_SIZE) {
            j = my_idx;
        } else {
            unsigned long long lcg = my_idx * 6364136223846793005ULL
                                   + 1442695040888963407ULL;
            j = lcg % (my_idx + 1ULL);
        }
        if (j < (unsigned long long)KT_F22_RESERVOIR_SIZE) {
            d_f22_reservoir[j].cand_lo = cand.lo;
            d_f22_reservoir[j].cand_hi = cand.hi;
            d_f22_reservoir[j].flags   = stages_active;
            d_f22_reservoir[j]._pad    = 0;
        }
    }

    /* S2b-F23: texture reservoir-sample this survivor (Vitter Algo R approx).
     * Mask all-zero: post-cascade survivors passed every prime; field reserved
     * for future Stage-0-admissible sampling extension. */
    if (d_f23_enabled) {
        unsigned long long my_idx = atomicAdd(&d_f23_counter, 1ULL);
        unsigned long long j;
        if (my_idx < (unsigned long long)KT_F23_RESERVOIR_SIZE) {
            j = my_idx;
        } else {
            unsigned long long lcg = my_idx * 6364136223846793005ULL
                                   + 1442695040888963407ULL;
            j = lcg % (my_idx + 1ULL);
        }
        if (j < (unsigned long long)KT_F23_RESERVOIR_SIZE) {
            d_f23_reservoir[j].cand_lo = cand.lo;
            d_f23_reservoir[j].cand_hi = cand.hi;
            d_f23_reservoir[j].mask0   = 0ULL;
            d_f23_reservoir[j].mask1   = 0ULL;
            d_f23_reservoir[j].mask2   = 0ULL;
        }
    }
}

/* =============================================================================
 * Phase 4b-3: wheel-offset-iter kernel (kt_stage0_to_fermat_v7_kernel).
 *
 * Earlier profiling showed v6's per-tile residue LUT amortized over <1
 * Stage-0 survivor per 256-thread tile because KT19_P0 wheel density is
 * 3.6e-5 (266112 / 37#). The structural lever is to flip iteration
 * order: each thread maps directly to a wheel-admissible offset, so every
 * launched thread is already a Stage-0 survivor — no admissibility check,
 * no wasted threads.
 *
 * Grid layout — two modes selected by template parameter kt_axes_swapped:
 *
 *   kt_axes_swapped=false (default, primorial ≤ 11):
 *     gridDim.x = n_tiles_per_launch               [tiles; always < 65535]
 *     gridDim.y = ceil(n_admissible / blockDim.x)  [woff chunks]
 *     tile_idx  = blockIdx.x,  woff_block = blockIdx.y
 *     Preserves original scheduling order → no throughput regression.
 *
 *   kt_axes_swapped=true (T2.2, primorial ≥ 12 when gridDim.y > 65535):
 *     gridDim.x = ceil(n_admissible / blockDim.x)  [woff chunks; can exceed 65535]
 *     gridDim.y = n_tiles_per_launch               [tiles; ≤1024 << 65535 cap]
 *     tile_idx  = blockIdx.y,  woff_block = blockIdx.x
 *     CUDA caps gridDim.y at 65535 but gridDim.x at 2^31.
 *
 *   blockDim.x = 256 (locked by __launch_bounds__)
 *   base_n MUST be aligned to a multiple of d_primorial.
 *
 * Per thread:
 *   woff_idx  = woff_block * blockDim.x + threadIdx.x
 *   if woff_idx >= n_admissible: return (after the cooperative sync)
 *   wheel_off = d_offsets[woff_idx]   // < d_primorial, fits in u64
 *   tile_base = base_n + tile_idx * d_primorial   (u128 add)
 *   cand      = tile_base + wheel_off  (always Stage-0 admissible)
 *
 * Cooperative residue compute: threads 0..12 cover the 13 small primes
 * (L2 + ext-L2). Stored in shared mem; reused by all woff_idx threads in
 * the block. Line-sieve (125 primes) stays per-thread per G11/G12 — a
 * shared LUT for 125 entries pushed v6 into spill territory, not the
 * cooperative compute itself.
 * ============================================================================ */
template<bool kt_axes_swapped>
__global__ __launch_bounds__(256, KT_LB_BLOCKS)
void kt_stage0_to_fermat_v7_kernel(
    const uint64_t * __restrict__ d_offsets,
    int                          d_n_admissible,
    unsigned long long           d_primorial,
    kt_u128                      base_n,
    unsigned int                 n_tiles,
    const uint64_t * __restrict__ d_line_kill_packed,  /* 125*14 */
    unsigned int                 stages_active,
    KtSurvivor                  *survivors,
    unsigned int                *survivor_count,
    unsigned int                *survivor_overflow,
    unsigned int                 max_survivors,
    unsigned long long          *cand_count) {

    /* T2.2: template selects grid axis assignment at compile time (zero
     * branch).  When kt_axes_swapped=false the original layout is used
     * (tile=blockIdx.x, woff=blockIdx.y, grid=dim3(n_tiles,gridY)) so
     * the PTX is identical to pre-T2.2 and no throughput regression
     * occurs at 37#.  When kt_axes_swapped=true the axes are swapped
     * (tile=blockIdx.y, woff=blockIdx.x, grid=dim3(gridY,n_tiles))
     * allowing gridY>65535 on the gridDim.x axis (cap 2^31) needed at
     * 41#+ for k=16/17. */
    int tile_idx  = kt_axes_swapped ? (int)blockIdx.y : (int)blockIdx.x;
    int woff_block = kt_axes_swapped ? (int)blockIdx.x : (int)blockIdx.y;
    int woff_idx  = woff_block * (int)blockDim.x + (int)threadIdx.x;

    /* Single-writer atomic for cand_count: report raw integers covered
     * (n_tiles * primorial) so the host bench Gcand/s metric stays
     * apples-to-apples with v5's "raw integers iterated" semantics.
     * NULL-guarded so the production search loop can skip it. */
    if (tile_idx == 0 && blockIdx.x == 0 && threadIdx.x == 0 && cand_count) {
        unsigned long long total = (unsigned long long)n_tiles * d_primorial;
        atomicAdd(cand_count, total);
    }

    /* tile_base = base_n + tile_idx * primorial. base_n is u128; tile_idx
     * * primorial fits in u128 (n_tiles <= ~64, primorial=37#=7.42e12). */
    kt_u128 tile_base;
    {
        unsigned __int128 b = ((unsigned __int128)base_n.hi << 64) | base_n.lo;
        b += (unsigned __int128)(unsigned int)tile_idx
             * (unsigned __int128)d_primorial;
        tile_base.lo = (uint64_t)b;
        tile_base.hi = (uint64_t)(b >> 64);
    }

    /* Cooperative residue compute for 13 small primes (L2 + ext-L2).
     * Each block must fill its own shared (one block per (tile,chunk));
     * blocks with the same tile_idx redundantly compute the same s_tile,
     * but the work is 13 mods + one __syncthreads per block — negligible. */
    __shared__ uint32_t s_tile_l2[KT_L2_COUNT];
    __shared__ uint32_t s_tile_ext_l2[KT_EXT_L2_COUNT];

    int tx = (int)threadIdx.x;
    if (tx < KT_L2_COUNT) {
        s_tile_l2[tx] = kt_u128_mod_u32(tile_base, d_kt_l2_primes[tx]);
    } else if (tx < KT_L2_COUNT + KT_EXT_L2_COUNT) {
        int j = tx - KT_L2_COUNT;
        s_tile_ext_l2[j] = kt_u128_mod_u32(tile_base, d_kt_ext_l2_primes[j]);
    }
    __syncthreads();

    /* Tail threads (woff_idx out of range, or in the last chunk) drop after
     * the sync to avoid divergent-sync UB. */
    if (woff_idx >= d_n_admissible) return;

    /* W18-K: per-stage kill-position counters.  Warp-aggregated atomic at
     * each stage exit point keeps the per-launch cost to one atomic per
     * active warp per stage (~22K warps × 5 sites = 110K atomics; trivial
     * compared to cascade compute on a saturated 5090).  Stage-0 (= admit
     * to cascade) is captured here, immediately after the woff_idx range
     * check, before any L2 work. */
    {
        unsigned _m = __activemask();
        if (((int)threadIdx.x & 31) == __ffs((int)_m) - 1)
            atomicAdd(&d_w18k_admit, (unsigned long long)__popc(_m));
    }

    uint64_t wheel_off = d_offsets[woff_idx];   /* < primorial, u64 */
    kt_u128 cand;
    cand.lo = tile_base.lo + wheel_off;
    cand.hi = tile_base.hi + (cand.lo < tile_base.lo ? 1 : 0);

    /* Stage L2: 6 primes < 64, single u64 mask. r_q = (s_tile + off_q) mod q
     * with one conditional subtract — both s_tile and off_q are < q. */
    if (stages_active & KT_STAGE_L2) {
        #pragma unroll
        for (int i = 0; i < KT_L2_COUNT; i++) {
            uint32_t q     = d_kt_l2_primes[i];
            uint32_t off_q = (uint32_t)(wheel_off % q);
            uint32_t r_q   = s_tile_l2[i] + off_q;
            if (r_q >= q) r_q -= q;
            if ((d_kt_l2_mask[i] >> r_q) & 1ULL) return;
        }
    }
    /* W18-K: passed L2. */
    {
        unsigned _m = __activemask();
        if (((int)threadIdx.x & 31) == __ffs((int)_m) - 1)
            atomicAdd(&d_w18k_pass_l2, (unsigned long long)__popc(_m));
    }

    /* Stage ext-L2: 7 primes < 128, lo/hi u64 mask. */
    if (stages_active & KT_STAGE_EXT_L2) {
        #pragma unroll
        for (int i = 0; i < KT_EXT_L2_COUNT; i++) {
            uint32_t q     = d_kt_ext_l2_primes[i];
            uint32_t off_q = (uint32_t)(wheel_off % q);
            uint32_t r_q   = s_tile_ext_l2[i] + off_q;
            if (r_q >= q) r_q -= q;
            uint64_t word  = (r_q < 64) ? d_kt_ext_l2_mask_lo[i]
                                        : d_kt_ext_l2_mask_hi[i];
            if ((word >> (r_q & 63u)) & 1ULL) return;
        }
    }
    /* W18-K: passed ext-L2. */
    {
        unsigned _m = __activemask();
        if (((int)threadIdx.x & 31) == __ffs((int)_m) - 1)
            atomicAdd(&d_w18k_pass_ext_l2, (unsigned long long)__popc(_m));
    }

    /* Stage line-sieve: 125 primes, per-thread u128 mod (no shared LUT).
     * Inherits v5's __ldg + no-prefetch posture per Phase 4a-2 lessons. */
    if (stages_active & KT_STAGE_LINE) {
        for (int ls = 0; ls < KT_LINE_COUNT; ls++) {
            uint32_t q    = d_kt_line_primes[ls];
            uint32_t r_q  = kt_u128_mod_u32(cand, q);
            uint64_t word = __ldg(&d_line_kill_packed[ls * KT_LINE_KILL_WORDS + (r_q >> 6)]);
            if ((word >> (r_q & 63u)) & 1ULL) return;
        }
    }
    /* W18-K: passed line-sieve. */
    {
        unsigned _m = __activemask();
        if (((int)threadIdx.x & 31) == __ffs((int)_m) - 1)
            atomicAdd(&d_w18k_pass_line, (unsigned long long)__popc(_m));
    }

    /* S2a F18: per-(line_prime, residue) yield counters at Fermat-stage entry.
     * Branch is warp-uniform (d_f18_yield_enabled is __constant__). */
    if (d_f18_yield_enabled) {
        for (int ls = 0; ls < KT_LINE_COUNT; ls++) {
            uint32_t q   = d_kt_line_primes[ls];
            uint32_t r_q = kt_u128_mod_u32(cand, q);
            atomicAdd(&d_f18_yield_counters[ls][r_q], 1ULL);
        }
    }

    /* Stage Fermat-2: identical to v5. */
    if (stages_active & KT_STAGE_FERMAT) {
        int kk = d_kt_pattern_k;
        for (int i = 0; i < kk; i++) {
            uint64_t off = (uint64_t)d_kt_pattern_offsets[i];
            kt_u128 cand_i;
            cand_i.lo = cand.lo + off;
            cand_i.hi = cand.hi + (cand_i.lo < cand.lo ? 1 : 0);
            if (!kt_fermat_base2_u128(cand_i)) return;
        }
    }
    /* W18-K: passed Fermat (= survivor; tracked separately from
     * survivor_count because the reporter prints kill deltas from this
     * d_w18k_* counter, not from the per-batch survivor_count). */
    {
        unsigned _m = __activemask();
        if (((int)threadIdx.x & 31) == __ffs((int)_m) - 1)
            atomicAdd(&d_w18k_pass_fermat, (unsigned long long)__popc(_m));
    }

    /* Survivor handoff: warp-aggregated atomicAdd, identical to v5. */
    unsigned active_mask = __activemask();
    unsigned pass_mask   = __ballot_sync(active_mask, 1);
    int lane             = threadIdx.x & 31;
    int leader           = __ffs((int)pass_mask) - 1;
    unsigned int warp_base = 0;
    if (lane == leader) {
        warp_base = atomicAdd(survivor_count, (unsigned int)__popc(pass_mask));
    }
    warp_base = __shfl_sync(pass_mask, warp_base, leader);
    unsigned int slot = warp_base + (unsigned int)__popc(pass_mask & ((1u << lane) - 1u));
    if (slot < max_survivors) {
        survivors[slot].cand_lo     = cand.lo;
        survivors[slot].cand_hi     = cand.hi;
        survivors[slot].pattern_idx = 0;
        survivors[slot]._pad        = 0;
    } else if (survivor_overflow) {
        atomicOr(survivor_overflow, 1u);
    }

    /* S2a F22: reservoir-sample this survivor (approximate Algo R). */
    if (d_f22_enabled) {
        unsigned long long my_idx = atomicAdd(&d_f22_counter, 1ULL);
        unsigned long long j;
        if (my_idx < (unsigned long long)KT_F22_RESERVOIR_SIZE) {
            j = my_idx;
        } else {
            unsigned long long lcg = my_idx * 6364136223846793005ULL
                                   + 1442695040888963407ULL;
            j = lcg % (my_idx + 1ULL);
        }
        if (j < (unsigned long long)KT_F22_RESERVOIR_SIZE) {
            d_f22_reservoir[j].cand_lo = cand.lo;
            d_f22_reservoir[j].cand_hi = cand.hi;
            d_f22_reservoir[j].flags   = stages_active;
            d_f22_reservoir[j]._pad    = 0;
        }
    }

    /* S2b-F23: texture reservoir-sample this survivor (Vitter Algo R approx). */
    if (d_f23_enabled) {
        unsigned long long my_idx = atomicAdd(&d_f23_counter, 1ULL);
        unsigned long long j;
        if (my_idx < (unsigned long long)KT_F23_RESERVOIR_SIZE) {
            j = my_idx;
        } else {
            unsigned long long lcg = my_idx * 6364136223846793005ULL
                                   + 1442695040888963407ULL;
            j = lcg % (my_idx + 1ULL);
        }
        if (j < (unsigned long long)KT_F23_RESERVOIR_SIZE) {
            d_f23_reservoir[j].cand_lo = cand.lo;
            d_f23_reservoir[j].cand_hi = cand.hi;
            d_f23_reservoir[j].mask0   = 0ULL;
            d_f23_reservoir[j].mask1   = 0ULL;
            d_f23_reservoir[j].mask2   = 0ULL;
        }
    }
}

/* =============================================================================
 * Phase 3d: novel-record preservation + crash-safe persistence.
 *
 * Contract per feedback_novel_record_preservation.md:
 *   - Every k>=16 certified hit cross-checked against records.json.
 *   - Novel hits append a JSON line to ./novel_records.jsonl with fsync, or
 *     ./novel_records_gpuN.jsonl when --gpu-device N was explicitly supplied,
 *     plus a stderr banner via write(2) (bypasses stdio so it survives SIGPIPE/etc).
 *   - Known hits log to the standard log file but skip the novel jsonl path.
 *
 * Test override: KT_NOVEL_JSONL env var redirects the append path so unit
 * tests can write to ./tmp/novel_records_test.jsonl without polluting the
 * real ./novel_records.jsonl.
 * ========================================================================== */

/* W20-DEC Phase 1 Step 3: thin wrappers that delegate to kt_novel_record.{c,h}.
 * The module is engine-state-free; it takes gpu_device/_explicit as args
 * (resolved here from the globals) and the JSON line context fields via
 * the ctx struct (resolved by the caller of kt_novel_record_append). */
static const char* novel_jsonl_path(void) {
    return kt_novel_record_jsonl_path(g_gpu_device, g_gpu_device_explicit);
}

static const char* kt_hostname(void) {
    return kt_novel_record_hostname();
}

static const char* kt_gpu_uuid(void) {
    static char buf[128];
    static int  done = 0;
    if (done) return buf;
    int dev = 0;
    cudaError_t e = cudaGetDevice(&dev);
    if (e != cudaSuccess) { snprintf(buf, sizeof buf, "unknown"); done = 1; return buf; }
    if (cudaDeviceGetPCIBusId(buf, sizeof buf, dev) != cudaSuccess) {
        snprintf(buf, sizeof buf, "device%d", dev);
    }
    done = 1;
    return buf;
}

/* Write the FOUND banner to stderr via write(2); survives stdio corruption. */
static void crash_safe_announce(const char *base_str, const KTupletPattern *pat,
                                int bits) {
    char msg[1024];
    int n = snprintf(msg, sizeof msg,
        "\n*** FOUND k=%d bits=%d pattern=%s base=%s ***\n",
        pat->k, bits, pat->name, base_str);
    if (n > 0 && (size_t)n < sizeof msg) {
        ssize_t wr = write(STDERR_FILENO, msg, (size_t)n);
        (void)wr;
    }
}

/* Append a certified hit to g_log_fp with fflush+fsync, mutex-protected so
 * concurrent BPSW host threads serialize on the log. */
static void log_certified_tuplet(const char *base_dec, const KTupletPattern *pat) {
    if (!g_log_fp) return;
    pthread_mutex_lock(&g_log_lock);
    fprintf(g_log_fp, "KT%d %s %s\n", pat->k, pat->name, base_dec);
    fflush(g_log_fp);
#ifdef __linux__
    fsync(fileno(g_log_fp));
#endif
    pthread_mutex_unlock(&g_log_lock);
}

/* W20-DEC Phase 2 Step 4: kt_records_load_with_search moved to
 * kt_records.{c,h} as kt_records_load.  This wrapper preserves the
 * original symbol name so the in-file call sites (T16 unit test +
 * preserve_novel_record's lazy load + the run_validate_known prelude)
 * keep compiling without per-site edits. */
struct kt_known_records *
kt_records_load_with_search(const char **out_used_path, int verbose) {
    return kt_records_load(out_used_path, verbose);
}

static void preserve_novel_record(const char *pattern, int k, int bits,
                                  const char *base_decimal) {
    if (k < 16) return;                                 /* policy gate */

    if (!g_records_loaded) {
        const char *used = NULL;
        g_known_records = kt_records_load_with_search(&used, /*verbose=*/1);
        if (!g_known_records) {
            fprintf(stderr,
                "WARNING: could not load records.json for novel-record "
                "cross-check; treating all hits as novel.\n");
        }
        g_records_loaded = 1;
    }

    if (g_known_records &&
        kt_known_records_contains(g_known_records, k, base_decimal)) {
        /* Known record. Log via crash_safe_announce + log_certified_tuplet
         * already happened at the call site; no novel jsonl entry. */
        return;
    }

    /* W20-DEC Phase 1 Step 3: delegate filesystem hygiene + JSON-line
     * formatting + crash-safe stderr banner to kt_novel_record_append.
     * Identity of the running process (wheel, build_sha, hostname, gpu_uuid,
     * cuda_version) flows in via the ctx struct; the module never reads
     * engine globals. */
    kt_novel_record_ctx_t ctx;
    ctx.build_sha    = KT_BUILD_SHA;
    ctx.hostname     = kt_novel_record_hostname();
    ctx.gpu_uuid     = kt_gpu_uuid();
    ctx.cuda_version = CUDART_VERSION;
    ctx.wheel_expr   = kt_checkpoint_wheel_expr_identity();
    ctx.primorial_n  = g_primorial_n_primes;
    (void)kt_novel_record_append(novel_jsonl_path(), &ctx,
                                 pattern, k, bits, base_decimal);
}
/* W20-DEC Phase 3 Step 6: signal handler, atexit hooks, and fatal-cleanup
 * helper moved to kt_signal.cu.  Forward decls live in kt_signal.h. */

/* =============================================================================
 * Pattern resolution helpers (kept simple - no static catalog defaults table
 * here; 3a leans on kt_pattern_by_name + first-match-with-k for --k N).
 * ========================================================================== */
static const KTupletPattern* resolve_pattern_by_k(int k) {
    for (int i = 0; i < KT_PATTERNS_COUNT; i++) {
        if (KT_PATTERNS[i].k == k) return &KT_PATTERNS[i];
    }
    return NULL;
}

static int set_pattern(const char* name, int k) {
    if (name) {
        g_pattern = kt_pattern_by_name(name);
        if (!g_pattern) {
            fprintf(stderr, "ERROR: unknown pattern '%s'\n", name);
            return 1;
        }
        if (k > 0 && k != g_pattern->k) {
            fprintf(stderr, "ERROR: --k %d does not match pattern %s (k=%d)\n",
                    k, name, g_pattern->k);
            return 1;
        }
        g_pattern_name = g_pattern->name;
        return 0;
    }
    if (k > 0) {
        g_pattern = resolve_pattern_by_k(k);
        if (!g_pattern) {
            fprintf(stderr, "ERROR: no catalog pattern for k=%d\n", k);
            return 1;
        }
        g_pattern_name = g_pattern->name;
        return 0;
    }
    fprintf(stderr, "ERROR: --pattern or --k required\n");
    return 1;
}

/* =============================================================================
 * Stage-0 wheel: build for active pattern, cross-check vs canonical hash,
 * and upload to device global memory.
 * ========================================================================== */
static int build_and_upload_stage0_wheel(void) {
    if (!g_pattern) {
        fprintf(stderr, "ERROR: build_stage0_wheel called before pattern resolution\n");
        return 1;
    }
    if (kt_prepare_active_wheel_config() != 0) return 1;
    /* pattern offsets: KTupletPattern stores int[]; convert to u32. */
    uint32_t pat[KT_MAX_K];
    for (int i = 0; i < g_pattern->k; i++) pat[i] = (uint32_t)g_pattern->offsets[i];

    /* Phase 9 T2.1 / wheel-expr: dispatch on the active prime list.  Plain
     * --primorial N uses consecutive kt_first_primes[0..N].  --wheel-expr
     * can drop primes from X#, e.g. 47#/17/31, and therefore supplies a
     * non-consecutive list. */
    int n_primes_used = g_active_wheel_n_primes;
    int rc;
    size_t peak_bytes = 0;
    int use_streaming = (g_active_wheel_ceiling_idx > 11 || n_primes_used > 12);
    if (!use_streaming) {
        rc = kt_wheel_crt_join(pat, g_pattern->k,
                               g_active_wheel_primes, n_primes_used,
                               &g_wheel);
    } else {
        /* Cap on host scratch for the streaming CRT-join. Was 4 GiB (T2.1
         * brief default) but raised 2026-05-10 to 64 GiB so that K=19 47#
         * (~31 GiB peak) and K=20 47# (~12.7 GiB) become feasible on the
         * RTX 5090 server (197 GiB host RAM, 32 GiB VRAM). The final
         * device-side wheel table is much smaller than the peak host
         * scratch (admissible-residue trim), so this cap does not push
         * VRAM past prior 47# levels. */
        const size_t MAX_BYTES = (size_t)64 << 30;       /* 64 GiB */
        rc = kt_wheel_crt_join_streaming(pat, g_pattern->k,
                                         g_active_wheel_primes, n_primes_used,
                                         MAX_BYTES, &peak_bytes,
                                         &g_wheel);
        fprintf(stderr,
            "[wheel] %s @ %s streaming: predicted peak alloc = %.3f MiB "
            "(cap = %.0f GiB)\n",
            g_pattern->name,
            g_active_wheel_expr,
            (double)peak_bytes / (1024.0 * 1024.0),
            (double)MAX_BYTES / (1024.0 * 1024.0 * 1024.0));
    }
    if (rc != 0) {
        fprintf(stderr,
                "ERROR: kt_wheel_crt_join%s(%s, %s) failed rc=%d "
                "(-1 cap/predicted=%.3f GiB, -2 inadmissible, -3 primorial overflow, -4 alloc)\n",
                use_streaming ? "_streaming" : "",
                g_pattern->name,
                g_active_wheel_expr,
                rc,
                (double)peak_bytes / (1024.0 * 1024.0 * 1024.0));
        return 1;
    }

    const kt_canonical_wheel_t *can =
        kt_wheel_canonical_lookup(g_pattern->name,
                                  g_active_wheel_primes, n_primes_used);
    uint32_t prim_top = kt_first_primes[g_active_wheel_ceiling_idx];
    if (can) {
        if (can->n_admissible != g_wheel.n_admissible ||
            can->fnv1a64_hash  != g_wheel.fnv1a64_hash) {
            fprintf(stderr,
                "ERROR: Stage-0 wheel disagrees with canonical for %s @ %u#:\n"
                "  runtime  n=%d hash=0x%016llx\n"
                "  canonical n=%d hash=0x%016llx\n",
                g_pattern->name, prim_top,
                g_wheel.n_admissible, (unsigned long long)g_wheel.fnv1a64_hash,
                can->n_admissible,    (unsigned long long)can->fnv1a64_hash);
            kt_wheel_free(&g_wheel);
            exit(2);
        }
        if (!g_full_quiet_mode) {
            printf("Wheel hash (FNV-1a-64): 0x%016llx (matches canonical)\n",
                   (unsigned long long)g_wheel.fnv1a64_hash);
        }
    } else {
        if (!g_full_quiet_mode) {
            printf("Wheel hash (FNV-1a-64): 0x%016llx (no canonical entry for %s @ %s)\n",
                   (unsigned long long)g_wheel.fnv1a64_hash,
                   g_pattern->name, g_active_wheel_expr);
        }
    }

    if (!g_full_quiet_mode) {
        printf("Stage 0: %s wheel admissibility, n_primes=%d, n_admissible=%d, modulus=%llu\n",
               g_active_wheel_expr,
               n_primes_used,
               g_wheel.n_admissible,
               (unsigned long long)g_wheel.primorial);
        fflush(stdout);
    }

    /* Upload to GPU global memory. */
    size_t bytes = (size_t)g_wheel.n_admissible * sizeof(uint64_t);
    CUDA_CHECK(cudaMalloc((void**)&g_d_admissible_offsets, bytes));
    CUDA_CHECK(cudaMemcpy(g_d_admissible_offsets, g_wheel.offsets, bytes,
                          cudaMemcpyHostToDevice));

    /* Phase 4a-3: precompute Barrett reciprocal mu = floor(2^128 / primorial)
     * and upload to __constant__ mem. The hot kernel uses this to replace
     * kt_u128_mod_u64's 64-iter shift loop with one 128x128 multiply.
     *
     * Identity: mu = (-(unsigned __int128)m) / m + 1.
     * Proof: -m as u128 = 2^128 - m. Write 2^128 = q*m + r, 0 <= r < m.
     *        Then 2^128 - m = (q-1)*m + r, so floor((2^128-m)/m) = q-1,
     *        and mu = q = floor((2^128-m)/m) + 1. Holds for r=0 too.
     * Valid for m >= 2; primorial(37#) ~= 7.42e12 satisfies this trivially. */
    {
        uint64_t m = (uint64_t)g_wheel.primorial;
        if (m < 2) {
            fprintf(stderr,
                "ERROR: primorial=%llu < 2; Barrett mu undefined.\n",
                (unsigned long long)m);
            return 1;
        }
        unsigned __int128 mu128 = ((unsigned __int128)0 - (unsigned __int128)m) / m + 1;
        kt_u128 mu_h;
        mu_h.lo = (uint64_t)mu128;
        mu_h.hi = (uint64_t)(mu128 >> 64);
        CUDA_CHECK(cudaMemcpyToSymbol(d_primorial_mu, &mu_h, sizeof(kt_u128)));
        if (!g_full_quiet_mode) {
            printf("Stage 0: Barrett mu = 0x%016llx%016llx (precomputed for primorial=%llu)\n",
                   (unsigned long long)mu_h.hi,
                   (unsigned long long)mu_h.lo,
                   (unsigned long long)m);
            fflush(stdout);
        }
        fprintf(stderr, "[v4] phase4a-3 barrett mu uploaded (m=%llu mu=0x%016llx%016llx)\n",
                (unsigned long long)m,
                (unsigned long long)mu_h.hi, (unsigned long long)mu_h.lo);
    }

    return 0;
}

static void release_stage0_wheel(void) {
    if (g_d_admissible_offsets) {
        cudaFree(g_d_admissible_offsets);
        g_d_admissible_offsets = NULL;
    }
    kt_wheel_free(&g_wheel);
}

/* =============================================================================
 * Phase 3c: build per-pattern filter masks, cross-check vs canonical hashes,
 * and upload to constant + global memory. Allocates the survivor buffer too.
 * ========================================================================== */
static int build_and_upload_filter_tables(void) {
    if (!g_pattern) {
        fprintf(stderr, "ERROR: build_filter_tables called before pattern\n");
        return 1;
    }
    uint32_t pat[KT_MAX_K];
    for (int i = 0; i < g_pattern->k; i++) pat[i] = (uint32_t)g_pattern->offsets[i];

    /* L2: 6 u64 masks. */
    for (int i = 0; i < KT_L2_COUNT; i++) {
        g_l2_mask_h[i] = kt_forbidden_mask_u64(pat, g_pattern->k, kt_l2_primes_h[i]);
    }

    /* ext-L2: 7 lo/hi pairs. */
    for (int i = 0; i < KT_EXT_L2_COUNT; i++) {
        kt_forbidden_mask_u128(pat, g_pattern->k, kt_ext_l2_primes_h[i],
                               &g_ext_l2_lo_h[i], &g_ext_l2_hi_h[i]);
    }

    /* line-sieve: 125 packed bitvecs (14 u64 each). */
    for (int i = 0; i < KT_LINE_COUNT; i++) {
        kt_forbidden_mask_packed(pat, g_pattern->k, kt_line_primes_h[i],
                                 &g_line_kill_h[i * KT_LINE_KILL_WORDS],
                                 KT_LINE_KILL_WORDS);
    }

    /* Canonical-hash cross-check. */
    uint64_t l2_hash = kt_wheel_fnv1a64_u64_array(g_l2_mask_h, KT_L2_COUNT);
    uint64_t ext_l2_packed[KT_EXT_L2_COUNT * 2];
    for (int i = 0; i < KT_EXT_L2_COUNT; i++) {
        ext_l2_packed[2 * i + 0] = g_ext_l2_lo_h[i];
        ext_l2_packed[2 * i + 1] = g_ext_l2_hi_h[i];
    }
    uint64_t ext_l2_hash = kt_wheel_fnv1a64_u64_array(ext_l2_packed, KT_EXT_L2_COUNT * 2);
    uint64_t line_hash   = kt_wheel_fnv1a64_u64_array(g_line_kill_h,
                                  KT_LINE_COUNT * KT_LINE_KILL_WORDS);

    const kt_canonical_filter_t *can = kt_filter_canonical_lookup(g_pattern->name);
    if (can) {
        if (can->l2_hash != l2_hash || can->ext_l2_hash != ext_l2_hash ||
            can->line_hash != line_hash) {
            fprintf(stderr,
                "ERROR: filter-mask hashes disagree with canonical for %s:\n"
                "  runtime  l2=0x%016llx ext-l2=0x%016llx line=0x%016llx\n"
                "  canonical l2=0x%016llx ext-l2=0x%016llx line=0x%016llx\n",
                g_pattern->name,
                (unsigned long long)l2_hash, (unsigned long long)ext_l2_hash,
                (unsigned long long)line_hash,
                (unsigned long long)can->l2_hash, (unsigned long long)can->ext_l2_hash,
                (unsigned long long)can->line_hash);
            exit(2);
        }
        if (!g_full_quiet_mode) {
            printf("Filter mask hashes (FNV-1a-64): l2=0x%016llx ext-l2=0x%016llx line=0x%016llx (matches canonical)\n",
                   (unsigned long long)l2_hash, (unsigned long long)ext_l2_hash,
                   (unsigned long long)line_hash);
        }
    } else {
        if (!g_full_quiet_mode) {
            printf("Filter mask hashes (FNV-1a-64): l2=0x%016llx ext-l2=0x%016llx line=0x%016llx (no canonical entry for %s)\n",
                   (unsigned long long)l2_hash, (unsigned long long)ext_l2_hash,
                   (unsigned long long)line_hash, g_pattern->name);
        }
    }

    /* Banner: prime bands + popcount sanity. */
    if (!g_full_quiet_mode) {
        printf("Filter primes: L2=[41,43,47,53,59,61] ext-L2=[67..97] line=[101..863] (125)\n");
        printf("Filter masks built: L2 popcounts=[");
        unsigned long long ext_l2_pc_sum = 0;
        for (int i = 0; i < KT_L2_COUNT; i++) {
            printf("%d%s", __builtin_popcountll(g_l2_mask_h[i]),
                   (i + 1 < KT_L2_COUNT) ? "," : "");
        }
        for (int i = 0; i < KT_EXT_L2_COUNT; i++) {
            ext_l2_pc_sum += (unsigned long long)
                (__builtin_popcountll(g_ext_l2_lo_h[i]) +
                 __builtin_popcountll(g_ext_l2_hi_h[i]));
        }
        unsigned long long line_pc_sum = 0;
        for (int i = 0; i < KT_LINE_COUNT * KT_LINE_KILL_WORDS; i++) {
            line_pc_sum += (unsigned long long)__builtin_popcountll(g_line_kill_h[i]);
        }
        printf("] ext-L2 popcount sum=%llu line-prime popcount sum=%llu\n",
               ext_l2_pc_sum, line_pc_sum);
        fflush(stdout);
    }

    /* Constant-mem uploads. */
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_l2_primes,     kt_l2_primes_h,
                                  sizeof(kt_l2_primes_h)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_ext_l2_primes, kt_ext_l2_primes_h,
                                  sizeof(kt_ext_l2_primes_h)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_line_primes,   kt_line_primes_h,
                                  sizeof(kt_line_primes_h)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_l2_mask,       g_l2_mask_h,
                                  sizeof(g_l2_mask_h)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_ext_l2_mask_lo, g_ext_l2_lo_h,
                                  sizeof(g_ext_l2_lo_h)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_ext_l2_mask_hi, g_ext_l2_hi_h,
                                  sizeof(g_ext_l2_hi_h)));

    /* Global-mem upload of line-sieve packed bitvec (14 KiB). */
    size_t line_bytes = sizeof(g_line_kill_h);
    CUDA_CHECK(cudaMalloc((void**)&g_d_line_kill_packed, line_bytes));
    CUDA_CHECK(cudaMemcpy(g_d_line_kill_packed, g_line_kill_h, line_bytes,
                          cudaMemcpyHostToDevice));

    /* Survivor buffer + counter. */
    CUDA_CHECK(cudaMalloc((void**)&g_d_survivors,
                          (size_t)KT_MAX_SURVIVORS_PER_BATCH * sizeof(KtSurvivor)));
    CUDA_CHECK(cudaMalloc((void**)&g_d_survivor_count, sizeof(unsigned int)));
    CUDA_CHECK(cudaMemset(g_d_survivor_count, 0, sizeof(unsigned int)));

    /* Phase 3d: upload pattern offsets to __constant__ memory for the
     * Fermat-2 stage. KT_MAX_K is the catalog cap (32). */
    if (g_pattern->k > KT_MAX_K) {
        fprintf(stderr, "ERROR: pattern->k=%d exceeds KT_MAX_K=%d\n",
                g_pattern->k, KT_MAX_K);
        return 1;
    }
    uint32_t pat32[KT_MAX_K] = {0};
    for (int i = 0; i < g_pattern->k; i++) pat32[i] = (uint32_t)g_pattern->offsets[i];
    int kk = g_pattern->k;
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_pattern_offsets, pat32, sizeof(pat32)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_pattern_k, &kk, sizeof(int)));

    /* S2a: upload F18/F22 enable flags; zero device counters when ON. */
    {
        int f18_on = g_f18_yield_enabled ? 1 : 0;
        CUDA_CHECK(cudaMemcpyToSymbol(d_f18_yield_enabled, &f18_on, sizeof(int)));
        if (g_f18_yield_enabled) {
            static unsigned long long z18[KT_LINE_COUNT][KT_F18_MAX_RES];
            memset(z18, 0, sizeof(z18));
            CUDA_CHECK(cudaMemcpyToSymbol(d_f18_yield_counters, z18, sizeof(z18)));
            if (!g_full_quiet_mode)
                fprintf(stderr, "[f18] yield counters ON (%zu KiB device)\n",
                        sizeof(z18) / 1024);
        }
        int f22_on = g_f22_enabled ? 1 : 0;
        CUDA_CHECK(cudaMemcpyToSymbol(d_f22_enabled, &f22_on, sizeof(int)));
        if (g_f22_enabled) {
            unsigned long long zc = 0;
            CUDA_CHECK(cudaMemcpyToSymbol(d_f22_counter, &zc, sizeof(zc)));
            static KtF22ReservoirSlot zres[KT_F22_RESERVOIR_SIZE];
            memset(zres, 0, sizeof(zres));
            CUDA_CHECK(cudaMemcpyToSymbol(d_f22_reservoir, zres, sizeof(zres)));
            if (!g_full_quiet_mode)
                fprintf(stderr, "[f22] reservoir ON (%d slots, %zu B device)\n",
                        KT_F22_RESERVOIR_SIZE, sizeof(zres));
        }
        int f23_on = g_f23_enabled ? 1 : 0;
        CUDA_CHECK(cudaMemcpyToSymbol(d_f23_enabled, &f23_on, sizeof(int)));
        if (g_f23_enabled) {
            unsigned long long zc = 0;
            CUDA_CHECK(cudaMemcpyToSymbol(d_f23_counter, &zc, sizeof(zc)));
            static KtF23TextureSlot zres[KT_F23_RESERVOIR_SIZE];
            memset(zres, 0, sizeof(zres));
            CUDA_CHECK(cudaMemcpyToSymbol(d_f23_reservoir, zres, sizeof(zres)));
            if (!g_full_quiet_mode)
                fprintf(stderr, "[f23] texture reservoir ON (%d slots, %zu B device)\n",
                        KT_F23_RESERVOIR_SIZE, sizeof(zres));
        }
    }
    /* S2b-F2: mirror mask tables into bank 0 of the RCU arrays and zero the
     * version counter. Bank 1 is left undefined until the first flip writes it.
     * Hot-path kernel is untouched; these symbols are only read by kt_f2_probe_kernel. */
    if (g_f2_rcu_enabled) {
        CUDA_CHECK(cudaMemcpyToSymbol(d_kt_l2_mask_rcu, g_l2_mask_h,
                                      sizeof(g_l2_mask_h), 0));
        CUDA_CHECK(cudaMemcpyToSymbol(d_kt_ext_l2_mask_lo_rcu, g_ext_l2_lo_h,
                                      sizeof(g_ext_l2_lo_h), 0));
        CUDA_CHECK(cudaMemcpyToSymbol(d_kt_ext_l2_mask_hi_rcu, g_ext_l2_hi_h,
                                      sizeof(g_ext_l2_hi_h), 0));
        uint32_t v0 = 0;
        CUDA_CHECK(cudaMemcpyToSymbol(d_kt_filter_version, &v0, sizeof(v0)));
        fprintf(stderr,
                "[f2] RCU dual-bank enabled: bank 0 published, version=0 "
                "(const-mem footprint +%zu B = %zu B for dual-bank mirror)\n",
                sizeof(g_l2_mask_h) + sizeof(g_ext_l2_lo_h) + sizeof(g_ext_l2_hi_h),
                2 * (sizeof(g_l2_mask_h) + sizeof(g_ext_l2_lo_h) + sizeof(g_ext_l2_hi_h)));
    }
    return 0;
}

static void release_filter_tables(void) {
    if (g_d_line_kill_packed) { cudaFree(g_d_line_kill_packed); g_d_line_kill_packed = NULL; }
    if (g_d_survivors)        { cudaFree(g_d_survivors);        g_d_survivors        = NULL; }
    if (g_d_survivor_count)   { cudaFree(g_d_survivor_count);   g_d_survivor_count   = NULL; }
}

/* =============================================================================
 * S2b-F2: RCU dual-bank flip scaffolding.
 *
 * Probe kernel: reads d_kt_l2_mask_rcu[d_kt_filter_version][0] and the current
 * version into host-visible device buffers so f2_run_flip_test() can assert
 * post-flip visibility. Single-thread, no perf relevance.
 *
 * f2_run_flip_test(): write a sentinel u64 to the inactive bank (bank 1),
 * cudaDeviceSynchronize() as the grace period, flip d_kt_filter_version to 1,
 * run the probe kernel, assert version=1 and mask[0]==sentinel, then restore
 * version=0 for downstream code.  Returns 0 PASS / 1 FAIL.
 * ========================================================================== */
__global__ void kt_f2_probe_kernel(uint64_t *out_l2_mask0, uint32_t *out_version) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        uint32_t v    = d_kt_filter_version;
        *out_version  = v;
        *out_l2_mask0 = d_kt_l2_mask_rcu[v][0];
    }
}

static int f2_run_flip_test(void) {
    if (!g_f2_rcu_enabled) {
        fprintf(stderr, "[f2] flip test requires --enable-f2-rcu — skipping\n");
        return 0;
    }
    fprintf(stderr, "[f2] flip test: writing sentinel to inactive bank 1...\n");
    const uint64_t sentinel = 0xDEADBEEFCAFEBABEULL;
    uint64_t bank1[KT_L2_COUNT];
    uint64_t ext_lo1[KT_EXT_L2_COUNT];
    uint64_t ext_hi1[KT_EXT_L2_COUNT];
    bank1[0] = sentinel;
    for (int i = 1; i < KT_L2_COUNT; i++)      bank1[i]    = g_l2_mask_h[i];
    for (int i = 0; i < KT_EXT_L2_COUNT; i++) { ext_lo1[i] = g_ext_l2_lo_h[i];
                                                 ext_hi1[i] = g_ext_l2_hi_h[i]; }
    /* Write sentinel to bank 1 (byte offset = sizeof one bank). */
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_l2_mask_rcu,        bank1,
                                  sizeof(bank1),    sizeof(bank1)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_ext_l2_mask_lo_rcu, ext_lo1,
                                  sizeof(ext_lo1),  sizeof(ext_lo1)));
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_ext_l2_mask_hi_rcu, ext_hi1,
                                  sizeof(ext_hi1),  sizeof(ext_hi1)));
    /* Grace period: any in-flight kernels complete before the version flip. */
    CUDA_CHECK(cudaDeviceSynchronize());
    uint32_t v1 = 1;
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_filter_version, &v1, sizeof(v1)));
    /* Probe: verify device sees version=1 and mask[0]==sentinel. */
    uint64_t *d_out_mask = NULL;
    uint32_t *d_out_ver  = NULL;
    CUDA_CHECK(cudaMalloc((void**)&d_out_mask, sizeof(uint64_t)));
    CUDA_CHECK(cudaMalloc((void**)&d_out_ver,  sizeof(uint32_t)));
    kt_f2_probe_kernel<<<1, 1>>>(d_out_mask, d_out_ver);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
    uint64_t h_mask = 0;
    uint32_t h_ver  = 0;
    CUDA_CHECK(cudaMemcpy(&h_mask, d_out_mask, sizeof(uint64_t), cudaMemcpyDeviceToHost));
    CUDA_CHECK(cudaMemcpy(&h_ver,  d_out_ver,  sizeof(uint32_t), cudaMemcpyDeviceToHost));
    cudaFree(d_out_mask);
    cudaFree(d_out_ver);
    int ok = (h_ver == 1) && (h_mask == sentinel);
    fprintf(stderr,
            "[f2] flip test: probe returned version=%u bank[ver][0]=0x%016llx "
            "(expect ver=1 mask=0x%016llx) — %s\n",
            (unsigned)h_ver, (unsigned long long)h_mask,
            (unsigned long long)sentinel, ok ? "PASS" : "FAIL");
    /* Restore bank 0 as active so downstream code sees the canonical masks. */
    uint32_t v0 = 0;
    CUDA_CHECK(cudaMemcpyToSymbol(d_kt_filter_version, &v0, sizeof(v0)));
    return ok ? 0 : 1;
}

/* S2a F18: dump non-zero (prime, residue, yield) tuples to JSONL on shutdown. */
static void f18_dump_yield_counters(void) {
    if (!g_f18_yield_enabled) return;
    static unsigned long long buf[KT_LINE_COUNT][KT_F18_MAX_RES];
    cudaError_t e = cudaMemcpyFromSymbol(buf, d_f18_yield_counters, sizeof(buf));
    if (e != cudaSuccess) {
        fprintf(stderr, "[f18] cudaMemcpyFromSymbol failed: %s\n",
                cudaGetErrorString(e));
        return;
    }
    char path[512];
    kt_ensure_bench_dir();
    snprintf(path, sizeof(path), "bench/yield_counters_%s_%d.jsonl",
             KT_BINARY_NAME, (int)getpid());
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "[f18] fopen %s failed: %s\n", path, strerror(errno));
        return;
    }
    unsigned long long total_nz = 0;
    for (int ls = 0; ls < KT_LINE_COUNT; ls++) {
        uint32_t q = kt_line_primes_h[ls];
        for (int r = 0; r < (int)q && r < KT_F18_MAX_RES; r++) {
            if (buf[ls][r] != 0) {
                fprintf(fp, "{\"prime\":%u,\"residue\":%d,\"yield\":%llu}\n",
                        q, r, buf[ls][r]);
                total_nz++;
            }
        }
    }
    fclose(fp);
    if (!g_full_quiet_mode)
        fprintf(stderr, "[f18] wrote %s (%llu non-zero entries)\n",
                path, total_nz);
}

/* S2a F22: dump reservoir to JSONL on shutdown. */
static void f22_dump_reservoir(void) {
    if (!g_f22_enabled) return;
    KtF22ReservoirSlot buf[KT_F22_RESERVOIR_SIZE];
    unsigned long long ctr = 0;
    cudaError_t e1 = cudaMemcpyFromSymbol(buf, d_f22_reservoir, sizeof(buf));
    cudaError_t e2 = cudaMemcpyFromSymbol(&ctr, d_f22_counter,  sizeof(ctr));
    if (e1 != cudaSuccess || e2 != cudaSuccess) {
        fprintf(stderr, "[f22] cudaMemcpyFromSymbol failed: %s/%s\n",
                cudaGetErrorString(e1), cudaGetErrorString(e2));
        return;
    }
    char path[512];
    kt_ensure_bench_dir();
    snprintf(path, sizeof(path), "bench/reservoir_%s_%d.jsonl",
             KT_BINARY_NAME, (int)getpid());
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "[f22] fopen %s failed: %s\n", path, strerror(errno));
        return;
    }
    int filled = (ctr < (unsigned long long)KT_F22_RESERVOIR_SIZE)
                 ? (int)ctr : KT_F22_RESERVOIR_SIZE;
    for (int i = 0; i < filled; i++) {
        fprintf(fp, "{\"cand_lo\":%llu,\"cand_hi\":%llu,\"flags\":%u}\n",
                (unsigned long long)buf[i].cand_lo,
                (unsigned long long)buf[i].cand_hi,
                buf[i].flags);
    }
    fclose(fp);
    if (!g_full_quiet_mode)
        fprintf(stderr, "[f22] wrote %s (filled=%d total_seen=%llu)\n",
                path, filled, ctr);
}

/* S2b-F23: dump texture reservoir to bench/texture_<binary>_<pid>.jsonl.
 * Schema: slot, cand_hi, cand_lo, mask0..mask2 (hex), total_seen.
 * Mask fields are all-zero for post-cascade survivors; preserved for a future
 * Stage-0-admissible sampling extension. */
static void f23_dump_reservoir(void) {
    if (!g_f23_enabled) return;
