/* =============================================================================
 * Phase 3d: post-kernel survivor handoff. Copy KtSurvivor batch to host;
 * for each survivor build mpz, run BPSW (verify_tuplet_gmp); on success log
 * to file + crash-safe announce + preserve_novel_record. Returns the number
 * of certified hits found in this batch.
 *
 * Single-threaded for now. The 3c numbers say survivor counts post-line are
 * ~5/Mcand and post-Fermat are ~1e-4 of that, so per-batch BPSW work is
 * negligible. Multi-thread can be a follow-up if it becomes a bottleneck.
 * ========================================================================== */
static int process_survivors_host(unsigned int *out_n_surv, int *out_hits) {
    unsigned int n_surv = 0;
    if (out_n_surv) *out_n_surv = 0;
    if (out_hits)   *out_hits   = 0;
    CUDA_CHECK(cudaMemcpy(&n_surv, g_d_survivor_count, sizeof(unsigned int),
                          cudaMemcpyDeviceToHost));
    if (out_n_surv) *out_n_surv = n_surv;
    if (n_surv == 0) {
        return 0;
    }
    if (n_surv > KT_MAX_SURVIVORS_PER_BATCH) n_surv = KT_MAX_SURVIVORS_PER_BATCH;

    KtSurvivor *h_surv = (KtSurvivor*)malloc((size_t)n_surv * sizeof(KtSurvivor));
    if (!h_surv) {
        fprintf(stderr, "ERROR: malloc(%u survivors) failed\n", n_surv);
        return 0;
    }
    CUDA_CHECK(cudaMemcpy(h_surv, g_d_survivors,
                          (size_t)n_surv * sizeof(KtSurvivor),
                          cudaMemcpyDeviceToHost));
    /* Reset device counter so the next launch starts at 0. */
    CUDA_CHECK(cudaMemset(g_d_survivor_count, 0, sizeof(unsigned int)));

    int hits = 0;
    mpz_t n_mpz, scratch;
    mpz_init(n_mpz);
    mpz_init(scratch);
    for (unsigned int i = 0; i < n_surv; i++) {
        uint64_t limbs[2] = { h_surv[i].cand_lo, h_surv[i].cand_hi };
        mpz_import(n_mpz, 2, -1, sizeof(uint64_t), 0, 0, limbs);
        if (verify_tuplet_gmp(n_mpz, g_pattern, scratch)) {
            char *base_dec = mpz_get_str(NULL, 10, n_mpz);
            if (base_dec) {
                crash_safe_announce(base_dec, g_pattern, g_target_bits);
                log_certified_tuplet(base_dec, g_pattern);
                preserve_novel_record(g_pattern->name, g_pattern->k,
                                      g_target_bits, base_dec);
                if (g_validate_expected_base &&
                    strcmp(base_dec, g_validate_expected_base) == 0) {
                    g_validate_hit_seen = 1;
                }
                free(base_dec);
                hits++;
            }
        }
    }
    mpz_clear(n_mpz);
    mpz_clear(scratch);
    free(h_surv);
    if (out_hits) *out_hits = hits;
    return hits;
}

/* Phase 3f: pinned-host BPSW handoff. h_surv was already D2H'd via
 * cudaMemcpyAsync from the streamed loop; we only run the verify_tuplet_gmp
 * pass here. The non-pinned process_survivors_host above remains for run_smoke
 * and the test path that allocate device buffers freshly per call. */
static int process_survivors_pinned(const KtSurvivor *h_surv,
                                    unsigned int n_surv,
                                    int *out_hits) {
    int hits = 0;
    if (out_hits) *out_hits = 0;
    if (n_surv > KT_MAX_SURVIVORS_PER_BATCH) n_surv = KT_MAX_SURVIVORS_PER_BATCH;
    if (n_surv == 0) return 0;
    mpz_t n_mpz, scratch;
    mpz_init(n_mpz);
    mpz_init(scratch);
    for (unsigned int i = 0; i < n_surv; i++) {
        uint64_t limbs[2] = { h_surv[i].cand_lo, h_surv[i].cand_hi };
        mpz_import(n_mpz, 2, -1, sizeof(uint64_t), 0, 0, limbs);
        if (verify_tuplet_gmp(n_mpz, g_pattern, scratch)) {
            char *base_dec = mpz_get_str(NULL, 10, n_mpz);
            if (base_dec) {
                crash_safe_announce(base_dec, g_pattern, g_target_bits);
                log_certified_tuplet(base_dec, g_pattern);
                preserve_novel_record(g_pattern->name, g_pattern->k,
                                      g_target_bits, base_dec);
                if (g_validate_expected_base &&
                    strcmp(base_dec, g_validate_expected_base) == 0) {
                    g_validate_hit_seen = 1;
                }
                free(base_dec);
                hits++;
            }
        }
    }
    mpz_clear(n_mpz);
    mpz_clear(scratch);
    if (out_hits) *out_hits = hits;
    return hits;
}

/* =============================================================================
 * Smoke (--smoke): one batch through Stage-0 kernel; assert cand > 0 and
 * surv/cand within an order of magnitude of n_admissible/primorial.
 * ========================================================================== */
/* Compute a bit-aligned u128 candidate base for the requested bit-width.
 * Returns an odd value at the high end of the bit range so the Fermat
 * stage actually sees ~2^bits candidates. */
static kt_u128 compute_u128_base(int bits) {
    kt_u128 r; r.lo = 0; r.hi = 0;
    if (bits <= 1) { r.lo = 1; return r; }
    if (bits <= 64) {
        r.lo = (bits == 64) ? (1ULL << 63) | 1ULL : (1ULL << (bits - 1)) | 1ULL;
    } else {
        r.lo = 1;
        r.hi = (bits >= 128) ? (1ULL << 63) : (1ULL << (bits - 1 - 64));
    }
    return r;
}

static int run_smoke(void) {
    if (test_t2_cuda_device() != 0) return 1;
    if (!g_d_admissible_offsets || g_wheel.n_admissible <= 0) {
        fprintf(stderr, "smoke FAILED: Stage-0 wheel not initialized\n");
        return 1;
    }
    if (!g_d_line_kill_packed || !g_d_survivor_count) {
        fprintf(stderr, "smoke FAILED: filter tables not initialized\n");
        return 1;
    }
    unsigned long long *d_cand = NULL;
    CUDA_CHECK(cudaMalloc((void**)&d_cand, sizeof(unsigned long long)));
    CUDA_CHECK(cudaMemset(d_cand, 0, sizeof(unsigned long long)));
    CUDA_CHECK(cudaMemset(g_d_survivor_count, 0, sizeof(unsigned int)));

    int block = 256;
    int grid = 256;        /* 65536 candidates */
    unsigned long long batch = (unsigned long long)grid * (unsigned long long)block;

    kt_u128 base_n = compute_u128_base(g_target_bits);
    kt_u128 stride; stride.lo = 1; stride.hi = 0;

    kt_stage0_to_fermat_kernel<<<grid, block>>>(
        g_d_admissible_offsets, g_wheel.n_admissible, g_wheel.primorial,
        base_n, stride, batch,
        g_d_line_kill_packed, g_stages_active,
        g_d_survivors, g_d_survivor_count, /*overflow=*/NULL,
        KT_MAX_SURVIVORS_PER_BATCH,
        d_cand);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());

    unsigned long long h_cand = 0;
    unsigned int       h_surv = 0;
    int                hits   = 0;
    CUDA_CHECK(cudaMemcpy(&h_cand, d_cand, sizeof(unsigned long long),
                          cudaMemcpyDeviceToHost));
    cudaFree(d_cand);

    /* Run BPSW handoff on any post-Fermat survivors. */
    process_survivors_host(&h_surv, &hits);

    if (h_cand == 0) {
        fprintf(stderr, "smoke FAILED: cand zero\n");
        return 1;
    }
    if (!g_quiet_mode) {
        printf("smoke OK pattern=%s bits=%d cand=%llu surv=%u hits=%d "
               "rate=%.3e (Stage-0 expected=%.3e)\n",
               g_pattern_name ? g_pattern_name : "(none)",
               g_target_bits, h_cand, h_surv, hits,
               (double)h_surv / (double)h_cand,
               (double)g_wheel.n_admissible / (double)g_wheel.primorial);
    } else {
        printf("smoke OK pattern=%s\n",
               g_pattern_name ? g_pattern_name : "(none)");
    }
    return 0;
}

/* =============================================================================
 * Search loop (--max-time / --max-batches). Stage-0 only in 3b: each batch
 * counts cand and surv (n_admissible / primorial admit rate). Stages 1/2/3
 * land in 3c/3d. Throughput: cand/s + surv/s + rejection ratio.
 * ========================================================================== */
/* Compute the analytical surv/cand expected from active stages. */
static double compute_expected_ratio(void) {
    double r = (double)g_wheel.n_admissible / (double)g_wheel.primorial;
    if (g_stages_active & KT_STAGE_L2) {
        for (int i = 0; i < KT_L2_COUNT; i++) {
            uint32_t q  = kt_l2_primes_h[i];
            int      pc = __builtin_popcountll(g_l2_mask_h[i]);
            r *= (double)((int)q - pc) / (double)q;
        }
    }
    if (g_stages_active & KT_STAGE_EXT_L2) {
        for (int i = 0; i < KT_EXT_L2_COUNT; i++) {
            uint32_t q  = kt_ext_l2_primes_h[i];
            int      pc = __builtin_popcountll(g_ext_l2_lo_h[i]) +
                          __builtin_popcountll(g_ext_l2_hi_h[i]);
            r *= (double)((int)q - pc) / (double)q;
        }
    }
    if (g_stages_active & KT_STAGE_LINE) {
        for (int i = 0; i < KT_LINE_COUNT; i++) {
            uint32_t q  = kt_line_primes_h[i];
            int      pc = 0;
            for (int w = 0; w < KT_LINE_KILL_WORDS; w++) {
                pc += __builtin_popcountll(
                    g_line_kill_h[i * KT_LINE_KILL_WORDS + w]);
            }
            r *= (double)((int)q - pc) / (double)q;
        }
    }
    return r;
}

/* Phase 3f: double-buffered streamed search loop.
 *
 *   pattern (mirrors v15:4067-4234):
 *       prime: launch on stream[0]
 *       for each subsequent batch i:
 *           launch on stream[i&1]
 *           cudaStreamSynchronize(stream[(i-1)&1])     // wait for prior batch
 *           accumulate cudaEventElapsedTime(start[prev], end[prev])
 *           read pinned h_count[prev], h_overflow[prev]
 *           if overflow: ERROR + exit(1)
 *           if n_surv > 0:  cudaMemcpyAsync(h_surv[prev], d_surv[prev], n_surv, stream[prev])
 *                           cudaStreamSynchronize(stream[prev])
 *           process_survivors_pinned(h_surv[prev], n_surv)
 *       drain: same on the final in-flight batch.
 *
 * GPU is busy on stream[cur] while host BPSWs prev's survivors. Util gate: the
 * cudaEvent timings aggregated into total_kernel_ms divided by wall_time_ms
 * yields gpu_util_pct. v15 reports 100% on a 4090; the engineering target on
 * the 5090 is identical.
 *
 * Per-thread atomicAdd on cand_count is dropped (Phase 3f C3); total_cand is
 * tracked on the host as the sum of (clamped) batch sizes. The d_cand
 * allocation and per-reporter-tick D2H are gone from this path. */

/* W20-DEC Phase 1 Step 1: kt_seed_anchor_offset, kt_compute_lane_bounds,
 * and kt_compute_lane_start_no_lanes moved to src/cuda/kt_lanes.{c,h}.
 * They are referenced from this TU and from kt_filter_v5_f1_baked-aware
 * test paths below; the prototypes come in via the kt_lanes.h include in
 * the extern "C" header block at the top of this file. */

/* Phase 4-GPU mid-run anchor rotation: xorshift64* PRNG.  Ported verbatim
 * from cunningham-chain-search/src/cuda/cc18_filter_cuda_CpC_v15.cu:790-801.
 * Period 2^64 - 1; deterministic given a non-zero seed.  Called once per
 * batch in random mode; state lives in g_rng_state. */
static uint64_t kt_rng_next(void) {
    uint64_t x = g_rng_state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    g_rng_state = x ? x : 1;
    return g_rng_state;
}

static int run_search_loop(void) {
    if (test_t2_cuda_device() != 0) return 1;
    if (!g_d_admissible_offsets || g_wheel.n_admissible <= 0) {
        fprintf(stderr, "ERROR: Stage-0 wheel not initialized for search loop\n");
        return 1;
    }
    if (!g_d_line_kill_packed || !g_d_survivor_count) {
        fprintf(stderr, "ERROR: filter tables not initialized for search loop\n");
        return 1;
    }

    /* KPI TTR early-exit.  When --kpi-target-base was provided,
     * arm the validate-known machinery so the per-survivor proving path sets
     * g_validate_hit_seen=1 on a base match.  Reset the early-exit flag so
     * back-to-back search-loop runs (validate-known harness, T22/T24/T28
     * unit tests) do not inherit a stale match.  validate-known mode never
     * gets here with g_kpi_target_base set (rejected at parse_argv). */
    g_kpi_early_exit = 0;
    if (g_kpi_target_base) {
        g_validate_expected_base = g_kpi_target_base;
        g_validate_hit_seen      = 0;
    }

    /* T2.2: gridY = ceil(n_admissible/block).  When gridY ≤ 65535 the
     * original layout (tiles=gridDim.x, woffs=gridDim.y) is used via the
     * <false> template instance — identical PTX to pre-T2.2, no regression.
     * When gridY > 65535 (k=16/17 at 41#+) the axes are swapped via the
     * <true> instance: tiles→gridDim.y, woffs→gridDim.x (cap 2^31).
     *
     * n_tiles_default: derived so total threads ≈ g_gpu_batch_size.
     * Each tile covers one wheel period (= primorial). */
    int block = 256;
    int n_admissible = g_wheel.n_admissible;
    unsigned long long primorial_u64 = g_wheel.primorial;
    unsigned int gridY = (unsigned int)((n_admissible + block - 1) / block);

    /* n_tiles per launch: chosen so the per-launch THREAD COUNT matches
     * v5's batch size as closely as possible. Each tile consumes
     * gridY*block threads. */
    unsigned long long threads_per_tile = (unsigned long long)gridY * (unsigned long long)block;
    unsigned int n_tiles_default;
    if (threads_per_tile == 0) {
        n_tiles_default = 1;
    } else {
        unsigned long long t = g_gpu_batch_size / threads_per_tile;
        if (t < 1) t = 1;
        if (t > 1024) t = 1024;       /* safety bound; gridDim.x cap */
        n_tiles_default = (unsigned int)t;
    }

    /* Cursor: u128 walk. With --prefix, walk only [prefix << shift,
     * (prefix+1) << shift); otherwise start at the bit-aligned base.
     * v7 requires cursor to be aligned to a primorial boundary so that
     * tile_base + d_offsets[i] is admissible (cursor mod primorial = 0). */
    unsigned __int128 cursor = 0;
    unsigned __int128 range_end_u128 = 0;
    unsigned __int128 lane_start_u128 = 0;       /* Phase 9 T1.2: pre-resume lane bound */
    if (g_use_prefix) {
        int shift = g_target_bits - g_prefix_bits;
        if (shift < 0) shift = 0;
        cursor = g_prefix_value_u128 << shift;
        range_end_u128 = (g_prefix_value_u128 + 1) << shift;
    } else {
        kt_u128 base_n = compute_u128_base(g_target_bits);
        cursor = ((unsigned __int128)base_n.hi << 64) | base_n.lo;
        /* Phase 9 T1.2 fix: when --exhaustive is requested without --prefix,
         * the natural completion point is 2^bits (one past the largest N-bit
         * candidate). Without this, range_end_u128 stays 0, the loop's
         * cursor>=range_end check never fires, the walk continues until
         * --max-time, and the engine reports "prefix NOT exhausted" even
         * after fully covering the bit range. (Random mode intentionally
         * leaves range_end_u128=0 — its cursor walks indefinitely by design.)
         */
        if (g_exhaustive_mode && g_target_bits > 0 && g_target_bits < 128) {
            range_end_u128 = (unsigned __int128)1 << g_target_bits;
        }
    }

    /* Phase 9 T1.2: --prefix-lanes shard the prefix tile range across N GPUs.
     * lane_size = (range_end - cursor) / lanes (in raw integers).  The trailing
     * lane absorbs the remainder so the union still covers [cursor,range_end). */
    if (g_prefix_lanes > 1 && g_use_prefix && range_end_u128 > cursor) {
        if (g_prefix_lane_id < 0 || g_prefix_lane_id >= g_prefix_lanes) {
            fprintf(stderr,
                "ERROR: --prefix-lane-id %d out of range [0,%d)\n",
                g_prefix_lane_id, g_prefix_lanes);
            return 1;
        }
        /* W19-A-3 (P1-8): lane-bound math via kt_compute_lane_bounds() so
         * T46b can unit-test the rounding invariants directly.  The helper
         * applies W18-A's lane_min round AND W19-A-2's lane_max round,
         * with the final lane keeping the unrounded range_end_u128. */
        unsigned __int128 lane_min, lane_max;
        kt_compute_lane_bounds(cursor, range_end_u128,
                               g_prefix_lanes, g_prefix_lane_id,
                               (unsigned __int128)primorial_u64,
                               &lane_min, &lane_max, &lane_start_u128);
        cursor          = lane_min;
        range_end_u128  = lane_max;
        if (!g_full_quiet_mode) {
            char dec_min[40], dec_max[40];
            kt_u128_format_dec(lane_min, dec_min, sizeof dec_min);
            kt_u128_format_dec(lane_max, dec_max, sizeof dec_max);
            fprintf(stderr,
                "[lane] %d/%d  [min=%s, max=%s)  lane_size=%llu_tiles\n",
                g_prefix_lane_id, g_prefix_lanes, dec_min, dec_max,
                (unsigned long long)((range_end_u128 - cursor) / (unsigned __int128)primorial_u64));
        }
    } else {
        /* W19-A-3 (P1-8): single-lane lane_start round via helper so T46c
         * can unit-test the W18-A site 2 invariant directly. */
        lane_start_u128 = kt_compute_lane_start_no_lanes(cursor,
                                                         (unsigned __int128)primorial_u64);
    }
    /* W18-A: round cursor down to primorial boundary (was the only round
     * site pre-W18-A; kept here because cursor still needs to land on a
     * primorial multiple for the v7 kernel's `tile_base + d_offsets[i]`
     * admissibility test). */
    {
        unsigned __int128 prim128 = (unsigned __int128)primorial_u64;
        unsigned __int128 rem = cursor % prim128;
        cursor -= rem;
    }

    /* Fix B: non-prefix --random gets a seed-derived starting anchor so each
     * restart covers a fresh region.  Prefix sharding (--prefix-lanes) is
     * disjoint by construction and doesn't need this offset.
     * W18-A: kt_seed_anchor_offset now returns a primorial-aligned offset
     * (takes primorial as third arg), so cursor stays primorial-aligned. */
    if (g_random_chunk_mode && !g_use_prefix) {
        cursor += kt_seed_anchor_offset(g_random_seed_used, g_target_bits,
                                         (unsigned __int128)primorial_u64);
    }

    /* W18-F DEBUG: misalignment-injection (default 0; no-op outside test).
     * Applied AFTER all cursor-init sites so the bug shows up as missed
     * known records in the regression test. Does NOT propagate through
     * resume (deliberate: test injects post-resume too).
     *
     * W19-A-1 (P1-1): the W18-A "trailing defensive round" that used to
     * follow this line has been removed.  That round silently neutralized
     * the inject before the kernel-launch trip-wire could see it, so the
     * W18-F regression test was passing for the wrong reason — Cases B
     * and C landed at the kernel ALIGNED.  With the round gone, the
     * production cursor flow stays primorial-aligned via the three W18-A
     * construction sites (lane_start round, lane_min round, primorial-
     * aligned kt_seed_anchor_offset return), while any deliberate or
     * accidental post-init misalignment (W18-F inject; future regression)
     * reaches the kernel-launch FATAL trip-wire below and surfaces as an
     * ABORT instead of silently miss-stomping the records. */
    cursor += g_inject_cursor_offset;

    /* =========================================================================
     * Phase v8-Sobs-B (§0.1): per-cell startup banner.  Emitted before any
     * reporter tick so operators can grep stdout for the search context
     * without reading the .cu source.  Resolution rules:
     *   --random  → mode=random
     *   --prefix  → mode=sequential-prefix
     *   neither   → mode=sequential
     * Anchor: in --random the first chunk anchor; in --prefix the high
     * `prefix_bits` of cursor; in plain sequential the bit-aligned cursor.
     * Anchor_bits: prefix mode = g_prefix_bits; random/sequential use
     * g_target_bits - 1 (so the anchor maps to a single high-bit window).
     * chunk_tiles: --chunk-tiles N or n_tiles_default if unset. */
    g_run_mode_str = g_random_chunk_mode ? "random"
                   : (g_use_prefix       ? "sequential-prefix"
                                         : "sequential");
    int   anchor_bits   = g_use_prefix ? g_prefix_bits
                        : (g_target_bits > 0 ? g_target_bits - 1 : 0);
    unsigned __int128 anchor_u128 = g_use_prefix
                        ? g_prefix_value_u128
                        : (cursor >> (g_target_bits - anchor_bits));
    unsigned long long chunk_tiles_b = g_chunk_tiles ? g_chunk_tiles
                                                     : (unsigned long long)n_tiles_default;
    if (!g_full_quiet_mode) {
        char anchor_dec[40], tile_count_dec[40];
        kt_u128_format_dec(anchor_u128, anchor_dec, sizeof anchor_dec);
        /* tile_count = 2^bits / primorial (u128 to avoid overflow at b101+). */
        unsigned __int128 tile_count_u128 = 0;
        if (g_target_bits > 0 && primorial_u64 > 0) {
            unsigned __int128 span = (g_target_bits >= 128)
                ? (unsigned __int128)0
                : ((unsigned __int128)1 << g_target_bits);
            tile_count_u128 = span / (unsigned __int128)primorial_u64;
        }
        kt_u128_format_dec(tile_count_u128, tile_count_dec, sizeof tile_count_dec);
        printf("[search] mode=%s\n", g_run_mode_str);
        if (g_random_chunk_mode) {
            printf("[search] seed=0x%016llx\n", (unsigned long long)g_random_seed_used);
            fprintf(stdout, "[search] verbose_rotation=%s\n", g_verbose_rotation ? "on" : "off");
        } else {
            printf("[search] seed=n/a\n");
        }
        if (g_target_bits > 0) {
            printf("[search] bit_range=[2^%d, 2^%d)\n",
                   g_target_bits - 1, g_target_bits);
        } else {
            printf("[search] bit_range=n/a\n");
        }
        printf("[search] tile_count=%s\n", tile_count_dec);
        /* Surface the active wheel expression so sweep harnesses can separate
         * plain primorial cells from structural quotient cells such as
         * 47#/17/31. */
        if (g_active_wheel_from_expr) {
            printf("[search] wheel_expr=%s  (ceiling=%u#, idx=%d, n_primes=%d, wheel_modulus=%llu)\n",
                   g_active_wheel_expr,
                   kt_first_primes[g_active_wheel_ceiling_idx],
                   g_active_wheel_ceiling_idx,
                   g_active_wheel_n_primes,
                   (unsigned long long)g_wheel.primorial);
        } else {
            printf("[search] primorial=%u#  (idx=%d, n_primes=%d, primorial_value=%llu)\n",
                   kt_first_primes[g_primorial_n_primes],
                   g_primorial_n_primes,
                   g_primorial_n_primes + 1,
                   (unsigned long long)g_wheel.primorial);
        }
        printf("[search] anchor=0x%016llx%016llx (decimal=%s)\n",
               (unsigned long long)(anchor_u128 >> 64),
               (unsigned long long)anchor_u128,
               anchor_dec);
        printf("[search] anchor_bits=%d\n", anchor_bits);
        printf("[search] chunk_tiles=%llu\n", chunk_tiles_b);
        /* Phase 9 T1.2: emit lane sharding info even when --prefix-lanes is
         * not set (lanes=0/0) so log parsers don't need to special-case. */
        printf("[search] prefix_lanes=%d  prefix_lane_id=%d\n",
               g_prefix_lanes, g_prefix_lane_id);
        printf("[search] exhaustive=%d  checkpoint=%s  resume=%s\n",
               g_exhaustive_mode ? 1 : 0,
               g_checkpoint_file ? g_checkpoint_file : "n/a",
               g_resume_mode ? (g_resume_file ? g_resume_file
                                              : (g_checkpoint_file ? g_checkpoint_file : "<missing>"))
                             : "n/a");
        printf("[search] runner_cell_id=%s\n",
               g_runner_cell_id ? g_runner_cell_id : "n/a");
        fflush(stdout);
    }

    /* §0.3: Bloom filter for chunk-anchor revisit detection.  Allocated for
     * every mode (uniformity); only probed/inserted in random mode where
     * anchors actually rotate (Phase 4-GPU).  ~64 KiB, freed at
     * run_search_loop exit.  The initial anchor is inserted unconditionally;
     * the per-batch rotation block in the while loop below probes via
     * kt_bloom_test_and_insert and bumps g_run_revisited_anchors on hit. */
    KtBloom *bloom = kt_bloom_alloc();
    if (!bloom) {
        fprintf(stderr, "WARNING: kt_bloom_alloc() failed; revisit detection disabled\n");
    }
    g_run_anchors_visited      = 0;
    g_run_unique_tiles_visited = 0;
    g_run_revisited_anchors    = 0;
    g_run_coverage_ratio       = 0.0;
    /* Insert the initial anchor.  In sequential / sequential-prefix modes
     * this is the only chunk anchor visited this cell.  In random mode,
     * the Phase 4-GPU PRNG-driven anchor rotation in the while-loop below
     * calls kt_bloom_test_and_insert on each new anchor pick. */
    if (bloom) {
        kt_bloom_insert(bloom, kt_anchor_key(anchor_u128, anchor_bits));
        g_run_anchors_visited = 1;
    }
    unsigned __int128 saved_initial_anchor = anchor_u128;
    (void)anchor_bits; /* kept for reporter banner; used by Phase 4-GPU rotation block */

    /* Phase 4b-1: N-deep stream pool (was N=2 ping-pong in v4). Steady
     * state holds num_streams kernels in flight; the host drains the
     * oldest just before reusing its slot, so launches stay queued ahead
     * of host-side BPSW + survivor handoff. num_streams is bounded by
     * KT_MAX_STREAMS at parse time. */
    int num_streams = g_gpu_streams;
    if (num_streams < 1) num_streams = 1;
    if (num_streams > KT_MAX_STREAMS) num_streams = KT_MAX_STREAMS;

    cudaStream_t       stream[KT_MAX_STREAMS];
    cudaEvent_t        evt_start[KT_MAX_STREAMS], evt_end[KT_MAX_STREAMS];
    KtSurvivor        *d_surv[KT_MAX_STREAMS]     = {0};
    unsigned int      *d_count[KT_MAX_STREAMS]    = {0};
    unsigned int      *d_overflow[KT_MAX_STREAMS] = {0};
    KtSurvivor        *h_surv[KT_MAX_STREAMS]     = {0};
    unsigned int      *h_count[KT_MAX_STREAMS]    = {0};
    unsigned int      *h_overflow[KT_MAX_STREAMS] = {0};
    int                evt_end_recorded[KT_MAX_STREAMS] = {0};
    /* W18-B drain-boundary tracking: snapshot of (cursor, total_cand) taken
     * immediately after launch on each slot, consumed at drain time to update
     * the (cursor_completed, total_cand_completed) save-side state. */
    unsigned __int128  cursor_post_launch[KT_MAX_STREAMS]     = {0};
    unsigned __int128  total_cand_post_launch[KT_MAX_STREAMS] = {0};
    /* W19-B-5: dedicated counter stream for W18-K diagnostic reads.  Created
     * once per run_search_loop call; safe to recreate across calls because
     * the teardown loop destroys it.  cudaStreamDestroy on the symbol is
     * also called from kt_cuda_cleanup_atexit so SIGINT mid-loop still
     * cleans up (atexit runs cudaDeviceReset anyway; redundant explicit
     * destroy is fine and we set the symbol to 0 after destroy). */
    CUDA_CHECK(cudaStreamCreate(&s_w19b_counter_stream));
    for (int b = 0; b < num_streams; b++) {
        CUDA_CHECK(cudaStreamCreate(&stream[b]));
        CUDA_CHECK(cudaEventCreate(&evt_start[b]));
        CUDA_CHECK(cudaEventCreate(&evt_end[b]));
        CUDA_CHECK(cudaMalloc((void**)&d_surv[b],
                              (size_t)KT_MAX_SURVIVORS_PER_BATCH * sizeof(KtSurvivor)));
        CUDA_CHECK(cudaMalloc((void**)&d_count[b],     sizeof(unsigned int)));
        CUDA_CHECK(cudaMalloc((void**)&d_overflow[b],  sizeof(unsigned int)));
        CUDA_CHECK(cudaMemset(d_count[b],    0, sizeof(unsigned int)));
        CUDA_CHECK(cudaMemset(d_overflow[b], 0, sizeof(unsigned int)));
        CUDA_CHECK(cudaMallocHost((void**)&h_surv[b],
                                  (size_t)KT_MAX_SURVIVORS_PER_BATCH * sizeof(KtSurvivor)));
        CUDA_CHECK(cudaMallocHost((void**)&h_count[b],    sizeof(unsigned int)));
        CUDA_CHECK(cudaMallocHost((void**)&h_overflow[b], sizeof(unsigned int)));
        *h_count[b]    = 0;
        *h_overflow[b] = 0;
    }

    double t0 = wall_time_sec();
    double deadline = (g_max_time_sec > 0) ? (t0 + g_max_time_sec) : 0.0;
    int batches = 0;
    int total_hits = 0;
    unsigned long long total_surv = 0;
    unsigned __int128  total_cand = 0;          /* Sobs-A §1.2: u128 cand counter */
    /* last_report / last_cand / last_surv now live inside reporter_state
     * (initialized below via kt_reporter_init).  W20-DEC Step 7. */
    double total_kernel_ms = 0.0;
    double total_prove_ms  = 0.0;

    /* W18-K: per-stage kill-position counters.  Reset device-side at the
     * start of each search loop so the reporter's `kills:` line reports
     * THIS run's distribution, not stale state from a previous run in the
     * same process (--test, --validate-known, T48 unit tests, etc.).
     * Track previous-tick values on the host to print per-tick deltas. */
    {
        unsigned long long zero = 0;
        CUDA_CHECK(cudaMemcpyToSymbol(d_w18k_admit,       &zero, sizeof(zero)));
        CUDA_CHECK(cudaMemcpyToSymbol(d_w18k_pass_l2,     &zero, sizeof(zero)));
        CUDA_CHECK(cudaMemcpyToSymbol(d_w18k_pass_ext_l2, &zero, sizeof(zero)));
        CUDA_CHECK(cudaMemcpyToSymbol(d_w18k_pass_line,   &zero, sizeof(zero)));
        CUDA_CHECK(cudaMemcpyToSymbol(d_w18k_pass_fermat, &zero, sizeof(zero)));
    }
    /* W20-DEC Phase 3 Step 7: per-tick reporter state machine (timing,
     * min-util sampler, W18-K kill-counter history, W19-A trip-wire
     * baseline) now lives in kt_reporter.cu.  Function-local kt_reporter_state_t
     * gives each run_search_loop call a fresh baseline — important inside
     * --validate-known and --test where many cells run back-to-back. */
    kt_reporter_state_t reporter_state;
    kt_reporter_init(&reporter_state, t0);

    /* Phase 4b-1: cur is the next slot to submit on; inflight tracks how
     * many in-flight kernels we hold. Steady state inflight == num_streams
     * just after submit (drained back to num_streams-1 before the next
     * iteration). When num_streams==2 this matches v4's ping-pong. */
    int cur      = 0;
    int inflight = 0;

    /* Phase 9 T1.2: --resume FILE.  Loads cursor + counters from a prior
     * checkpoint, validating (bits, target_k, pattern, prefix, lanes,
     * lane_id) match this invocation.  Soft-fail = start fresh (no resume
     * applied); silent success advances the cursor + seeds counters. */
    g_run_exhausted = 0;
    if (g_resume_mode) {
        const char *path = g_resume_file ? g_resume_file : g_checkpoint_file;
        if (!path) {
            fprintf(stderr,
                "ERROR: --resume requires --checkpoint FILE or --resume FILE\n");
            return 1;
        }
        unsigned __int128  rc_cursor = 0, rc_total_cand = 0;
        unsigned long long rc_surv = 0;
        int rc_hits = 0, rc_batches = 0, rc_exh = 0;
        int rc = kt_checkpoint_load(path, &rc_cursor, &rc_total_cand,
                                    &rc_surv, &rc_hits, &rc_batches, &rc_exh);
        if (rc == 0) {
            /* W18-J (multi-angle N7): validate the resumed cursor lies inside
             * the lane's tile range.  A corrupted ckpt or a ckpt written by a
             * differently-prefixed run could place the cursor outside the
             * intended search window — the loop would then either exit
             * immediately or underflow on the remaining-tiles math.  Soft-fail
             * to fresh-start matches the existing mismatch-handling pattern.
             *
             * Effective upper bound:
             *   --prefix or --exhaustive: range_end_u128 (already computed).
             *   neither (plain --random):  range_end_u128 == 0; cap at 2^bits,
             *     matching the in-loop rotation logic. */
            unsigned __int128 effective_end_u128 = range_end_u128;
            if (effective_end_u128 == 0 &&
                g_target_bits > 0 && g_target_bits < 128) {
                effective_end_u128 = (unsigned __int128)1 << g_target_bits;
            }
            int cursor_in_range =
                (rc_cursor >= lane_start_u128) &&
                (effective_end_u128 == 0 || rc_cursor < effective_end_u128);
            int terminal_exhausted_cursor =
                rc_exh &&
                (rc_cursor >= lane_start_u128) &&
                (effective_end_u128 != 0) &&
                (rc_cursor >= effective_end_u128);
            if (!cursor_in_range && !terminal_exhausted_cursor) {
                fprintf(stderr,
                    "[RESUME] cursor=0x%016llx%016llx outside lane "
                    "[0x%016llx%016llx, 0x%016llx%016llx) — starting fresh\n",
                    (unsigned long long)(rc_cursor >> 64),
                    (unsigned long long)rc_cursor,
                    (unsigned long long)(lane_start_u128 >> 64),
                    (unsigned long long)lane_start_u128,
                    (unsigned long long)(effective_end_u128 >> 64),
                    (unsigned long long)effective_end_u128);
                /* Leave cursor at its pre-resume init (lane_start_u128 or
                 * the random-anchor cursor); do not touch counters. */
            } else {
                cursor       = rc_cursor;
                total_cand   = rc_total_cand;
                total_surv   = rc_surv;
                total_hits   = rc_hits;
                batches      = rc_batches;
                g_run_unique_tiles_visited += (unsigned long long)
                    ((rc_cursor - lane_start_u128) / (unsigned __int128)primorial_u64);
                if (rc_exh) g_run_exhausted = 1;
                /* CC v15 parity (cc18_filter_cuda_CpC_v15.cu:3939): a
                 * successful resume forces sequential continuation from the
                 * checkpoint cursor.  Mid-run anchor rotation would
                 * otherwise wash out the deterministic restart contract
                 * (cursor jumps away from the resumed position on the very
                 * next batch).  Operator restarts the process without
                 * --resume for fresh random coverage. */
                g_random_chunk_mode = 0;
                g_run_mode_str      = "sequential";
                /* W18-J (multi-angle N9): emit a banner-correction line so
                 * log parsers reading "[search] mode=random" up-line don't
                 * misclassify the cell — the resumed cell is now sequential
                 * regardless of how it started. */
                printf("[search] mode-override=sequential (resumed)\n");
                fflush(stdout);
            }
        }
    }

    /* W18-B drain-boundary save state.  These mirror (cursor, total_cand,
     * batches) but only advance at drain — never on launch — so a periodic
     * save captures (cursor_completed, total_cand_completed, batches_completed,
     * total_surv, total_hits) as a consistent tuple.  On resume the loaded
     * cursor IS the post-last-drain cursor; the in-flight batches at save
     * time are re-launched. */
    unsigned __int128 cursor_completed     = cursor;
    unsigned __int128 total_cand_completed = total_cand;
    int               batches_completed    = batches;

    /* Phase 9 T1.2: checkpoint save cadence.  Wallclock-based, so a stalled
     * shell or big batch doesn't postpone the save indefinitely.  First
     * save fires at t0 + interval (not at t0). */
    double last_ckpt_save = wall_time_sec();

    while (!g_shutdown_requested) {
        /* Phase 4-GPU mid-run anchor rotation: draw a fresh random cursor
         * from xorshift64* before each batch when in random mode.  Mirrors
         * cunningham-chain-search/src/cuda/cc18_filter_cuda_CpC_v15.cu:4015-4025.
         * Range:
         *   --prefix-mode random + --prefix : [lane_start, range_end)
         *   --prefix-mode random alone      : [base = 2^(bits-1), 2^bits)
         * Bloom-revisit policy: probe and accept; if revisit, increment
         * g_run_revisited_anchors (the cheaper option (b) from the design
         * brief).  At ~2^54-tile ranges (b101, primorial 14#=30030) revisits
         * are vanishingly rare in a single-process run.  Resume path forces
         * g_random_chunk_mode=0 above, so this block is skipped after a
         * successful checkpoint load. */
        if (g_random_chunk_mode && batches > 0) {
            unsigned __int128 rotate_min = lane_start_u128;
            unsigned __int128 rotate_max;
            if (g_use_prefix || g_exhaustive_mode) {
                rotate_max = (range_end_u128 > rotate_min) ? range_end_u128 : rotate_min;
            } else if (g_target_bits > 0 && g_target_bits < 128) {
                rotate_max = (unsigned __int128)1 << g_target_bits;
            } else {
                rotate_max = rotate_min;          /* defensive: skip rotation */
            }
            if (rotate_max > rotate_min) {
                unsigned __int128 prim_u128 = (unsigned __int128)primorial_u64;
                unsigned __int128 span_tiles =
                    (rotate_max - rotate_min) / prim_u128;
                if (span_tiles > (unsigned __int128)n_tiles_default) {
                    /* Reserve one batch worth of tiles at the top so the
                     * post-rotation kernel launch stays inside [min,max). */
                    span_tiles -= (unsigned __int128)n_tiles_default;
                    /* Mix CLOCK_MONOTONIC nsec into the rng state each tick
                     * so independent processes (multi-GPU) draw distinct
                     * sequences even when seeded identically (CC v15 parity). */
                    struct timespec _ts;
                    clock_gettime(CLOCK_MONOTONIC, &_ts);
                    g_rng_state ^= (uint64_t)_ts.tv_nsec;
                    if (g_rng_state == 0) g_rng_state = 1;
                    unsigned __int128 rand128 =
                        ((unsigned __int128)kt_rng_next() << 64) | kt_rng_next();
                    unsigned __int128 tile_idx = rand128 % span_tiles;
                    cursor = rotate_min + tile_idx * prim_u128;
                    /* Anchor key derived from the same (anchor_high|anchor_bits)
                     * pair as the initial-anchor insert above. */
                    int rot_anchor_bits = g_use_prefix ? g_prefix_bits
                                        : (g_target_bits > 0 ? g_target_bits - 1 : 0);
                    unsigned __int128 rot_anchor = g_use_prefix
                        ? g_prefix_value_u128
                        : (cursor >> (g_target_bits - rot_anchor_bits));
                    if (bloom) {
                        uint64_t key = kt_anchor_key(rot_anchor, rot_anchor_bits);
                        if (kt_bloom_test_and_insert(bloom, key)) {
                            g_run_revisited_anchors++;
                        }
                    }
                    g_run_anchors_visited++;
                    /* Per-rotation log line (greppable by
                     * /root/kt/check_random_coverage.sh).  Emit a single
                     * line per rotation so coverage analysis can count
                     * distinct anchors. */
                    if (g_verbose_rotation) {
                        double rot_elapsed = wall_time_sec() - t0;
                        printf("[search] anchor=0x%016llx%016llx tile=%llu elapsed=%.3fs\n",
                               (unsigned long long)(cursor >> 64),
                               (unsigned long long)cursor,
                               (unsigned long long)tile_idx,
                               rot_elapsed);
                        fflush(stdout);
                    }
                }
            }
        }

        /* Phase 4b-3: per-launch tile count. Default n_tiles_default,
         * clamped so we don't overshoot the prefix range_end by more than
         * one primorial (rounding up: enough tiles to cover [cursor,
         * range_end_u128) at least). */
        unsigned int this_n_tiles = n_tiles_default;
        unsigned __int128 prim128 = (unsigned __int128)primorial_u64;
        if (range_end_u128 > 0) {
            if (cursor >= range_end_u128) break;
            unsigned __int128 remaining = range_end_u128 - cursor;
            unsigned __int128 tiles_needed = (remaining + prim128 - 1) / prim128;
            if (tiles_needed == 0) break;
            if ((unsigned __int128)this_n_tiles > tiles_needed)
                this_n_tiles = (unsigned int)tiles_needed;
        }
        unsigned __int128 this_batch =
            (unsigned __int128)this_n_tiles * (unsigned __int128)primorial_u64;  /* raw integers */

        /* Reset cur stream's device counters before launch. */
        CUDA_CHECK(cudaMemsetAsync(d_count[cur],    0, sizeof(unsigned int), stream[cur]));
        CUDA_CHECK(cudaMemsetAsync(d_overflow[cur], 0, sizeof(unsigned int), stream[cur]));

        kt_u128 cur128;
        cur128.lo = (uint64_t)cursor;
        cur128.hi = (uint64_t)(cursor >> 64);

        /* W18-A : runtime trip-wire for cursor-alignment drift.
         * Every cursor write between init and here is aligned-by-construction
         * (W18-A 3-site fix); cursor += this_batch advances by primorial
         * multiples; the random-rotation block re-derives cursor as
         * lane_start + tile_idx * primorial.  If this invariant ever breaks,
         * the v7 kernel will silently emit 0 survivors per batch instead of
         * misbehaving observably — abort here so the regression surfaces. */
        if (cursor % (unsigned __int128)primorial_u64 != 0) {
            /* W19-B-1: route through kt_fatal_cleanup so cudaDeviceReset
             * fires before exit (W18-I's atexit handler is skipped by abort();
             * the trip-wire is exactly the case where the GPU context most
             * urgently needs to be released to avoid phantom-util sticking
             * across the operator's investigation). */
            char buf[256];
            snprintf(buf, sizeof buf,
                "[FATAL] cursor not primorial-aligned at kernel launch: "
                "cursor_lo=0x%016llx cursor%%prim=%llu primorial=%llu batches=%d\n",
                (unsigned long long)(uint64_t)cursor,
                (unsigned long long)(cursor % (unsigned __int128)primorial_u64),
                (unsigned long long)primorial_u64, batches);
            kt_fatal_cleanup(2, buf);
        }

        CUDA_CHECK(cudaEventRecord(evt_start[cur], stream[cur]));
        if (gridY > 65535u) {
            /* T2.2: gridY exceeds CUDA gridDim.y cap — swap axes. */
            dim3 v7_grid(gridY, (unsigned int)this_n_tiles, 1u);
            kt_stage0_to_fermat_v7_kernel<true><<<v7_grid, block, 0, stream[cur]>>>(
                g_d_admissible_offsets, n_admissible, primorial_u64,
                cur128, this_n_tiles,
                g_d_line_kill_packed, g_stages_active,
                d_surv[cur], d_count[cur], d_overflow[cur],
                KT_MAX_SURVIVORS_PER_BATCH,
                /*cand_count=*/NULL);
        } else {
            /* Original layout: tiles=gridDim.x, woffs=gridDim.y. */
            dim3 v7_grid((unsigned int)this_n_tiles, gridY, 1u);
            kt_stage0_to_fermat_v7_kernel<false><<<v7_grid, block, 0, stream[cur]>>>(
                g_d_admissible_offsets, n_admissible, primorial_u64,
                cur128, this_n_tiles,
                g_d_line_kill_packed, g_stages_active,
                d_surv[cur], d_count[cur], d_overflow[cur],
                KT_MAX_SURVIVORS_PER_BATCH,
                /*cand_count=*/NULL);
        }
        CUDA_CHECK(cudaEventRecord(evt_end[cur], stream[cur]));
        evt_end_recorded[cur] = 1;
        CUDA_CHECK(cudaGetLastError());

        /* Async D2H of count + overflow flag for cur (small, in-flight). */
        CUDA_CHECK(cudaMemcpyAsync(h_count[cur],    d_count[cur],
                                   sizeof(unsigned int),
                                   cudaMemcpyDeviceToHost, stream[cur]));
        CUDA_CHECK(cudaMemcpyAsync(h_overflow[cur], d_overflow[cur],
                                   sizeof(unsigned int),
                                   cudaMemcpyDeviceToHost, stream[cur]));

        total_cand += this_batch;  /* raw integers covered (apples-to-apples vs v5) */
        cursor += this_batch;
        /* W18-B: snapshot (cursor, total_cand) for the slot just launched
         * (= current value of `cur`, before the round-robin advance below).
         * Drain reads these to update (cursor_completed, total_cand_completed). */
        cursor_post_launch[cur]     = cursor;
        total_cand_post_launch[cur] = total_cand;
        batches++;
        /* Sobs-B: tiles touched grows monotonically in sequential / prefix
         * modes (cursor walks forward by primorial-sized tiles).  In Phase
         * 4-GPU random mode the cursor jumps each batch but we still count
         * this_n_tiles as "tiles covered this batch" — the global counter
         * loses its "unique" meaning under rotation (revisits handled by
         * Bloom + g_run_revisited_anchors). */
        g_run_unique_tiles_visited += (unsigned long long)this_n_tiles;

        /* Round-robin advance + steady-state drain. We just submitted on
         * `cur`; the next slot to recycle is (cur+1) % num_streams. Once
         * the pool is full (inflight == num_streams) we drain that
         * slot — it's the oldest in-flight kernel — so it's free for the
         * next launch. */
        cur = (cur + 1) % num_streams;
        inflight++;

        if (inflight >= num_streams) {
            int prev = cur;     /* oldest in-flight = next slot to reuse */
            CUDA_CHECK(cudaStreamSynchronize(stream[prev]));

            float kms = 0.0f;
            CUDA_CHECK(cudaEventElapsedTime(&kms, evt_start[prev], evt_end[prev]));
            total_kernel_ms += (double)kms;

            unsigned int n_overflow = *h_overflow[prev];
            unsigned int n_surv     = *h_count[prev];
            if (n_overflow != 0u) {
                fprintf(stderr,
                    "ERROR: survivor buffer overflow (had=%u cap=%u). "
                    "Reduce --gpu-batch-size or raise KT_MAX_SURVIVORS_PER_BATCH.\n",
                    n_surv, KT_MAX_SURVIVORS_PER_BATCH);
                exit(1);
            }
            if (n_surv > KT_MAX_SURVIVORS_PER_BATCH)
                n_surv = KT_MAX_SURVIVORS_PER_BATCH;     /* defensive clamp */

            if (n_surv > 0) {
                CUDA_CHECK(cudaMemcpyAsync(h_surv[prev], d_surv[prev],
                                           (size_t)n_surv * sizeof(KtSurvivor),
                                           cudaMemcpyDeviceToHost, stream[prev]));
                CUDA_CHECK(cudaStreamSynchronize(stream[prev]));
            }

            double pv0 = wall_time_sec();
            int batch_hits = 0;
            process_survivors_pinned(h_surv[prev], n_surv, &batch_hits);
            double pv1 = wall_time_sec();
            total_prove_ms += (pv1 - pv0) * 1000.0;
            total_surv += n_surv;
            total_hits += batch_hits;
            /* W18-B: this slot is now fully drained — advance the save-side
             * cursor/total_cand/batches to the snapshot captured at its launch. */
            cursor_completed     = cursor_post_launch[prev];
            total_cand_completed = total_cand_post_launch[prev];
            batches_completed++;
            inflight--;
        }

        double now = wall_time_sec();

        /* W20-DEC Phase 3 Step 7: min-util sampling + main reporter tick
         * delegated to kt_reporter.cu.  CUDA symbol reads for W18-K
         * counters stay here (tightly coupled to the device __constant__
         * symbols defined in core); the snapshot is handed to
         * kt_reporter_emit which owns the formatting + W19-A trip-wire. */
        kt_reporter_min_util(&reporter_state, now, total_kernel_ms);

        if (kt_reporter_should_emit(&reporter_state, now)) {
            /* W18-K: read the device kill-counter snapshot via the
             * s_w19b_counter_stream, ordered behind the latest recorded
             * compute-stream end events (W19-B-5/W20).  Soft-fail on any
             * error — kt_reporter_emit honors valid_w18k=0 by skipping
             * the kills line + trip-wire but still advancing the
             * bookkeeping so the next tick's main-line deltas stay
             * accurate. */
            unsigned long long w18k_admit = 0, w18k_pl2 = 0, w18k_pel2 = 0,
                               w18k_pli = 0, w18k_pfe = 0;
            int valid_w18k = 1;
            for (int si = 0; si < num_streams; si++) {
                if (!evt_end_recorded[si]) continue;
                cudaError_t ew = cudaStreamWaitEvent(s_w19b_counter_stream, evt_end[si], 0);
                if (ew != cudaSuccess) {
                    fprintf(stderr,
                        "[reporter] W18-K counter stream wait failed (%s); "
                        "skipping kills line this tick\n",
                        cudaGetErrorString(ew));
                    valid_w18k = 0;
                    break;
                }
            }
            if (valid_w18k) {
                cudaError_t e1 = cudaMemcpyFromSymbolAsync(
                    &w18k_admit, d_w18k_admit, sizeof(w18k_admit),
                    0, cudaMemcpyDeviceToHost, s_w19b_counter_stream);
                cudaError_t e2 = cudaMemcpyFromSymbolAsync(
                    &w18k_pl2, d_w18k_pass_l2, sizeof(w18k_pl2),
                    0, cudaMemcpyDeviceToHost, s_w19b_counter_stream);
                cudaError_t e3 = cudaMemcpyFromSymbolAsync(
                    &w18k_pel2, d_w18k_pass_ext_l2, sizeof(w18k_pel2),
                    0, cudaMemcpyDeviceToHost, s_w19b_counter_stream);
                cudaError_t e4 = cudaMemcpyFromSymbolAsync(
                    &w18k_pli, d_w18k_pass_line, sizeof(w18k_pli),
                    0, cudaMemcpyDeviceToHost, s_w19b_counter_stream);
                cudaError_t e5 = cudaMemcpyFromSymbolAsync(
                    &w18k_pfe, d_w18k_pass_fermat, sizeof(w18k_pfe),
                    0, cudaMemcpyDeviceToHost, s_w19b_counter_stream);
                cudaError_t es = cudaStreamSynchronize(s_w19b_counter_stream);
                if (e1 != cudaSuccess || e2 != cudaSuccess || e3 != cudaSuccess ||
                    e4 != cudaSuccess || e5 != cudaSuccess || es != cudaSuccess) {
                    fprintf(stderr,
                        "[reporter] W18-K counter read failed (%s/%s/%s/%s/%s/sync=%s); "
                        "skipping kills line this tick\n",
                        cudaGetErrorString(e1), cudaGetErrorString(e2),
                        cudaGetErrorString(e3), cudaGetErrorString(e4),
                        cudaGetErrorString(e5), cudaGetErrorString(es));
                    valid_w18k = 0;
                }
            }

            kt_reporter_inputs_t rin;
            rin.now                  = now;
            rin.t0                   = t0;
            rin.batches              = batches;
            rin.total_hits           = total_hits;
            rin.total_cand           = total_cand;
            rin.total_surv           = total_surv;
            rin.total_kernel_ms      = total_kernel_ms;
            rin.total_prove_ms       = total_prove_ms;
            rin.saved_initial_anchor = saved_initial_anchor;
            rin.primorial            = (uint64_t)g_wheel.primorial;
            rin.n_admissible         = (uint64_t)g_wheel.n_admissible;
            rin.anchors_visited      = g_run_anchors_visited;
            rin.unique_tiles_visited = g_run_unique_tiles_visited;
            rin.valid_w18k           = valid_w18k;
            rin.w18k_admit           = w18k_admit;
            rin.w18k_pass_l2         = w18k_pl2;
            rin.w18k_pass_ext_l2     = w18k_pel2;
            rin.w18k_pass_line       = w18k_pli;
            rin.w18k_pass_fermat     = w18k_pfe;
            kt_reporter_emit(&reporter_state, &rin);
        }
        /* Phase 9 T1.2: periodic checkpoint save.  Cheap (text file, atomic
         * rename); fires every g_checkpoint_interval_sec wallclock seconds.
         * total_cand / total_surv reflect work submitted so far; cursor
         * tracks the next byte the loop will scan, so on resume we pick up
         * exactly where we stopped. */
        if (g_checkpoint_file &&
            (now - last_ckpt_save) >= (double)g_checkpoint_interval_sec) {
            /* W18-B: save the drain-boundary snapshot (cursor_completed,
             * total_cand_completed, batches_completed) so the saved tuple
             * is internally consistent with total_surv/total_hits (which
             * already only advance at drain). */
            (void)kt_checkpoint_save(g_checkpoint_file,
                                     cursor_completed, total_cand_completed,
                                     total_surv, total_hits,
                                     batches_completed, /*exh=*/0);
            last_ckpt_save = now;
        }

        if (deadline > 0 && now >= deadline) break;
        if (g_max_batches > 0 && batches >= g_max_batches) break;
        if (range_end_u128 > 0 && cursor >= range_end_u128) {
            g_run_exhausted = 1;            /* Phase 9 T1.2: natural completion */
            break;
        }
        if (g_kpi_target_base && g_validate_hit_seen) {
            /* KPI TTR early-exit.  Survivor pinned-path /
             * host-path sets g_validate_hit_seen=1 when a certified hit's
             * base matches.  Stop here so kpi_run.py records TTR, not
             * full-prefix-sweep elapsed_s.  Drains in-flight slots below. */
            g_kpi_early_exit = 1;
            break;
        }
    }

    /* Drain: walk all remaining in-flight slots in oldest-first order.
     * Submission advances cur by 1 each launch; the oldest still-in-flight
     * slot was submitted `inflight` iterations ago, i.e. (cur - inflight)
     * mod num_streams. (At steady-state exit inflight == num_streams - 1
     * because the in-loop drain ran. On early exit before the pool fills,
     * inflight equals the number of submitted batches and cur points at a
     * never-used slot — using the formula keeps us off it.) */
    int drain_start = ((cur - inflight) % num_streams + num_streams) % num_streams;
    for (int k = 0; k < inflight; k++) {
        int prev = (drain_start + k) % num_streams;
        CUDA_CHECK(cudaStreamSynchronize(stream[prev]));
        float kms = 0.0f;
        CUDA_CHECK(cudaEventElapsedTime(&kms, evt_start[prev], evt_end[prev]));
        total_kernel_ms += (double)kms;

        unsigned int n_overflow = *h_overflow[prev];
        unsigned int n_surv     = *h_count[prev];
        if (n_overflow != 0u) {
            fprintf(stderr,
                "ERROR: survivor buffer overflow on drain (had=%u cap=%u).\n",
                n_surv, KT_MAX_SURVIVORS_PER_BATCH);
            exit(1);
        }
        if (n_surv > KT_MAX_SURVIVORS_PER_BATCH) n_surv = KT_MAX_SURVIVORS_PER_BATCH;
        if (n_surv > 0) {
            CUDA_CHECK(cudaMemcpyAsync(h_surv[prev], d_surv[prev],
                                       (size_t)n_surv * sizeof(KtSurvivor),
                                       cudaMemcpyDeviceToHost, stream[prev]));
            CUDA_CHECK(cudaStreamSynchronize(stream[prev]));
        }
        double pv0 = wall_time_sec();
        int batch_hits = 0;
        process_survivors_pinned(h_surv[prev], n_surv, &batch_hits);
        double pv1 = wall_time_sec();
        total_prove_ms += (pv1 - pv0) * 1000.0;
        total_surv += n_surv;
        total_hits += batch_hits;
        /* W18-B: final-drain also advances the drain-boundary snapshot so
         * the post-loop ckpt save reflects every drained batch. */
        cursor_completed     = cursor_post_launch[prev];
        total_cand_completed = total_cand_post_launch[prev];
        batches_completed++;
    }
    inflight = 0;

    double t1 = wall_time_sec();
    double dt = t1 - t0;
    double wall_ms      = dt * 1000.0;
    double gpu_util     = (wall_ms > 0) ? (total_kernel_ms / wall_ms * 100.0) : 0.0;
    if (gpu_util > 100.0) gpu_util = 100.0;
    double prove_ratio  = (total_kernel_ms > 0)
                          ? (total_prove_ms / total_kernel_ms) : 0.0;
    double total_cand_d = kt_u128_to_double(total_cand);
    double cand_rate    = dt > 0 ? total_cand_d / dt : 0.0;
    double useful_cand_rate = (g_wheel.primorial > 0)
        ? cand_rate * (double)g_wheel.n_admissible / (double)g_wheel.primorial : 0.0;
    double surv_rate    = dt > 0 ? (double)total_surv / dt : 0.0;
    double frac         = total_cand_d > 0
                          ? (double)total_surv / total_cand_d : 0.0;
    double expected     = compute_expected_ratio();
    double dev_pct      = (expected > 0)
                          ? 100.0 * (frac - expected) / expected : 0.0;

    /* If we never sampled a 1Hz tick (very short run), seed the min from mean. */
    if (!reporter_state.have_min_sample) reporter_state.min_util_pct = gpu_util;

    char cand_buf[40];
    kt_u128_format_dec(total_cand, cand_buf, sizeof cand_buf);
    /* Sobs-B §0.4: coverage summary.
     *   Random mode: expected = anchors_drawn * chunk_tiles  (no-revisit case).
     *   Sequential / sequential-prefix: cursor walks forward, no revisits by
     *     construction.  expected := observed so coverage_ratio = 1.0.
     *   Bloom revisits counter populates revisited_anchors. */
    unsigned long long expected_unique_tiles;
    if (g_random_chunk_mode) {
        expected_unique_tiles = g_run_anchors_visited * chunk_tiles_b;
        if (expected_unique_tiles == 0) expected_unique_tiles = g_run_unique_tiles_visited;
    } else {
        expected_unique_tiles = g_run_unique_tiles_visited;
    }
    double coverage_ratio = (expected_unique_tiles > 0)
        ? (double)g_run_unique_tiles_visited / (double)expected_unique_tiles
        : 0.0;
    g_run_coverage_ratio = coverage_ratio;
    if (bloom) g_run_revisited_anchors = bloom->revisits;

    printf("=== final: batches=%d cand=%s surv=%llu hits=%d elapsed=%.3fs "
           "cand/s=%.3e useful_cand/s=%.3e surv/s=%.3e surv/cand=%.3e (expected=%.3e dev=%+0.1f%%) "
           "[stages=0x%x] gpu_util_pct=%.2f gpu_util_pct_min=%.2f "
           "prove_to_kernel_ratio=%.4f total_kernel_ms=%.3f total_prove_ms=%.3f "
           "wall_time_ms=%.3f bench_schema_version=%d "
           "unique_anchors_visited=%llu unique_tiles_visited=%llu "
           "expected_unique_tiles_for_seed=%llu coverage_ratio=%.4f "
           "revisited_anchors=%llu ===\n",
           batches, cand_buf, total_surv, total_hits, dt,
           cand_rate, useful_cand_rate, surv_rate, frac, expected, dev_pct, g_stages_active,
           gpu_util, reporter_state.min_util_pct, prove_ratio,
           total_kernel_ms, total_prove_ms, wall_ms,
           KT_BENCH_SCHEMA_VERSION,
           g_run_anchors_visited, g_run_unique_tiles_visited,
           expected_unique_tiles, coverage_ratio,
           g_run_revisited_anchors);

    /* KPI TTR final-line marker.  Only emitted when the run was
     * launched with --kpi-target-base, so non-KPI runs (validate-known,
     * sweeps, unit tests, smoke) keep the existing single-line `=== final:`
     * contract.  kpi_run.py greps for `kpi_match_seen=1` to distinguish OK
     * (true match within budget) from WRONG_BASE / NOTFOUND. */
    if (g_kpi_target_base) {
        printf("kpi_target_base=%s kpi_early_exit=%d kpi_match_seen=%d\n",
               g_kpi_target_base,
               g_kpi_early_exit,
               g_validate_hit_seen ? 1 : 0);
        fflush(stdout);
    }

    /* §0.3: free Bloom now that revisits is captured into g_run_revisited_anchors. */
    if (bloom) { kt_bloom_free(bloom); bloom = NULL; }
    if (prove_ratio > 1.5) {
        fprintf(stderr,
            "** GPU was idle %.0f%% of the time — try more prove threads or "
            "higher depth to reduce survivors **\n",
            100.0 - gpu_util);
    }

    /* Phase 9 T1.2: final checkpoint save (whether the loop exhausted, hit
     * --max-time, or was SIGINT'd).  This makes resume-after-shutdown work
     * even when the periodic save didn't fire on the last interval.
     * W18-B: save the drain-boundary snapshot (post-final-drain cursor_completed
     * equals the submitted-side cursor here, but we use the explicit name to
     * make the invariant uniform with the periodic-save path). */
    if (g_checkpoint_file) {
        (void)kt_checkpoint_save(g_checkpoint_file,
                                 cursor_completed, total_cand_completed,
                                 total_surv, total_hits, batches_completed,
                                 g_run_exhausted ? 1 : 0);
    }

    /* Phase 9 T1.2: --exhaustive PREFIX EXHAUSTED banner + JSONL row.  Emits
     * exactly when the lane's tile range is fully swept (g_run_exhausted=1
     * AND --exhaustive is requested).  --max-time / --max-batches early
     * termination prints stderr WARN instead. */
    if (g_exhaustive_mode) {
        char iso_now[32];
        time_t tt = time(NULL);
        strftime(iso_now, sizeof iso_now, "%Y-%m-%dT%H:%M:%SZ", gmtime(&tt));
        if (g_run_exhausted) {
            printf("[exhaustive] PREFIX %s EXHAUSTED at %s bits=%d "
                   "admissibles_tested=%llu finds=%d walltime_s=%.3f\n",
                   g_prefix_str ? g_prefix_str : "n/a",
                   iso_now,
                   g_target_bits,
                   g_run_unique_tiles_visited * (unsigned long long)n_admissible,
                   total_hits,
                   dt);
            fflush(stdout);
            kt_ensure_bench_dir();
            FILE *xj = fopen("bench/exhaustive_complete.jsonl", "a");
            if (xj) {
                fprintf(xj,
                    "{\"prefix\":\"%s\",\"prefix_mode\":\"%s\","
                    "\"prefix_lanes\":%d,\"prefix_lane_id\":%d,"
                    "\"pattern\":\"%s\",\"primorial_n\":%d,\"bits\":%d,"
                    "\"unique_tiles_visited\":%llu,"
                    "\"admissibles_tested\":%llu,"
                    "\"finds\":%d,\"walltime_s\":%.3f,"
                    "\"completed_iso\":\"%s\","
                    "\"gpu_uuid\":\"%s\","
                    "\"binary_name\":\"%s\","
                    "\"build_sha\":\"%s\"}\n",
                    g_prefix_str ? g_prefix_str : "none",
                    g_run_mode_str ? g_run_mode_str : "sequential",
                    g_prefix_lanes, g_prefix_lane_id,
                    g_pattern ? g_pattern->name : "none",
                    g_primorial_n_primes, g_target_bits,
                    g_run_unique_tiles_visited,
                    g_run_unique_tiles_visited * (unsigned long long)n_admissible,
                    total_hits, dt,
                    iso_now,
                    kt_gpu_uuid(),
                    KT_BINARY_NAME, KT_BUILD_SHA);
                fclose(xj);
            } else {
                fprintf(stderr,
                    "[exhaustive] WARNING: could not append to bench/exhaustive_complete.jsonl: %s\n",
                    strerror(errno));
            }
        } else {
            fprintf(stderr,
                "[exhaustive] WARNING: --exhaustive run terminated early "
                "(--max-time / SIGINT / --max-batches); prefix NOT exhausted.  "
                "Resume with --resume %s to continue.\n",
                g_checkpoint_file ? g_checkpoint_file : "<no checkpoint>");
        }
    }

    g_run_cand                  = total_cand;
    g_run_surv                  = total_surv;
    g_run_hits                  = total_hits;
    g_run_elapsed_s             = dt;
    g_run_total_kernel_ms       = total_kernel_ms;
    g_run_total_prove_ms        = total_prove_ms;
    g_run_wall_time_ms          = wall_ms;
    g_run_gpu_util_pct          = gpu_util;
    g_run_gpu_util_pct_min      = reporter_state.min_util_pct;
    g_run_prove_to_kernel_ratio = prove_ratio;
    g_run_useful_cand_per_s     = useful_cand_rate;

    /* Tear down streams + buffers. */
    for (int b = 0; b < num_streams; b++) {
        cudaStreamDestroy(stream[b]);
        cudaEventDestroy(evt_start[b]);
        cudaEventDestroy(evt_end[b]);
        if (d_surv[b])     cudaFree(d_surv[b]);
        if (d_count[b])    cudaFree(d_count[b]);
        if (d_overflow[b]) cudaFree(d_overflow[b]);
        if (h_surv[b])     cudaFreeHost(h_surv[b]);
        if (h_count[b])    cudaFreeHost(h_count[b]);
        if (h_overflow[b]) cudaFreeHost(h_overflow[b]);
    }
    /* W19-B-5: destroy the W18-K counter stream.  Set the symbol to 0 so
     * kt_cuda_cleanup_atexit (which mirror-destroys it) is a no-op. */
    if (s_w19b_counter_stream) {
        cudaStreamDestroy(s_w19b_counter_stream);
        s_w19b_counter_stream = 0;
    }
    return 0;
}

/* =============================================================================
 * Phase 3e: --validate-known
 *
 * Walk tools/records_manifest.tsv; per record (k, pattern, base, bits) rebuild
 * the wheel + filter tables, run a 2s sieve probe to estimate throughput,
 * derive a prefix that fits ~60s of work, then run --max-time 60 with the
 * derived prefix and report whether the certified base appeared. One JSONL
 * row per record when --bench-jsonl is set.
 * ========================================================================== */

/* W20-DEC Phase 2 Step 4: records_manifest.tsv loader moved to
 * kt_records.{c,h} as kt_records_manifest_load + kt_record_entry_t.  The
 * local typedef + wrapper below preserve the in-file call sites
 * (`RecordEntryGpu *recs; n = load_records_manifest_gpu(&recs, …)`) so the
 * surrounding validate-known driver loop stays untouched in this commit. */
typedef kt_record_entry_t RecordEntryGpu;

static int load_records_manifest_gpu(RecordEntryGpu **out, int target_k_filter) {
    return kt_records_manifest_load(out, target_k_filter);
}

/* Parse base-10 to u128. Returns 0 OK, -1 on bad char or overflow. */
int parse_decimal_u128(const char *s, unsigned __int128 *out) {
    if (!s || !*s) return -1;
    unsigned __int128 v = 0;
    for (const char *p = s; *p; p++) {
        if (*p < '0' || *p > '9') return -1;
        unsigned __int128 nv = v * 10 + (unsigned __int128)(*p - '0');
        if (nv < v) return -1;
        v = nv;
    }
    *out = v;
    return 0;
}

/* Parse 0bXXX into u128 + bit count. Returns 0 OK, -1 on bad input. */
int parse_prefix_str(const char *s, unsigned __int128 *val, int *bits) {
    if (!s) return -1;
    if (s[0] == '0' && (s[1] == 'b' || s[1] == 'B')) s += 2;
    unsigned __int128 v = 0;
    int n = 0;
    for (const char *p = s; *p; p++) {
        if (*p != '0' && *p != '1') return -1;
        if (n >= 127) return -1;
        v = (v << 1) | (unsigned __int128)(*p - '0');
        n++;
    }
    if (n == 0) return -1;
    *val = v;
    *bits = n;
    return 0;
}

/* Run kernel batches for ~`seconds` against the currently-uploaded wheel +
 * filter tables, return cand/s. No BPSW handoff, no log writes. */
static double estimate_throughput_gpu(double seconds) {
    if (!g_d_admissible_offsets || !g_d_line_kill_packed || !g_d_survivor_count) {
        return 1.0;
    }
    unsigned long long *d_cand = NULL;
    if (cudaMalloc((void **)&d_cand, sizeof(unsigned long long)) != cudaSuccess) return 1.0;
    cudaMemset(d_cand, 0, sizeof(unsigned long long));
    cudaMemset(g_d_survivor_count, 0, sizeof(unsigned int));

    /* Phase 4b-3: 2D launch matching run_search_loop's v7 kernel. */
    int block = 256;
    int n_admissible = g_wheel.n_admissible;
    unsigned long long primorial_u64 = g_wheel.primorial;
    unsigned int gridY = (unsigned int)((n_admissible + block - 1) / block);
    unsigned long long threads_per_tile = (unsigned long long)gridY * (unsigned long long)block;
    unsigned int n_tiles_default;
    if (threads_per_tile == 0) {
        n_tiles_default = 1;
    } else {
        unsigned long long t = g_gpu_batch_size / threads_per_tile;
        if (t < 1) t = 1;
        if (t > 1024) t = 1024;
        n_tiles_default = (unsigned int)t;
    }
    unsigned long long batch_per_launch =
        (unsigned long long)n_tiles_default * primorial_u64;  /* raw int span */

    /* Probe at the bit-aligned base, primorial-aligned. Throughput-only run. */
    kt_u128 base_n = compute_u128_base(g_target_bits);
    unsigned __int128 cursor = ((unsigned __int128)base_n.hi << 64) | base_n.lo;
    {
        unsigned __int128 prim128 = (unsigned __int128)primorial_u64;
        unsigned __int128 rem = cursor % prim128;
        cursor -= rem;
    }

    double t0 = wall_time_sec();
    double deadline = t0 + seconds;
    while (wall_time_sec() < deadline) {
        kt_u128 cur128;
        cur128.lo = (uint64_t)cursor;
        cur128.hi = (uint64_t)(cursor >> 64);
        if (gridY > 65535u) {
            dim3 v7_grid(gridY, n_tiles_default, 1u);
            kt_stage0_to_fermat_v7_kernel<true><<<v7_grid, block>>>(
                g_d_admissible_offsets, n_admissible, primorial_u64,
                cur128, n_tiles_default,
                g_d_line_kill_packed, g_stages_active,
                g_d_survivors, g_d_survivor_count, /*overflow=*/NULL,
                KT_MAX_SURVIVORS_PER_BATCH,
                d_cand);
        } else {
            dim3 v7_grid(n_tiles_default, gridY, 1u);
            kt_stage0_to_fermat_v7_kernel<false><<<v7_grid, block>>>(
                g_d_admissible_offsets, n_admissible, primorial_u64,
                cur128, n_tiles_default,
                g_d_line_kill_packed, g_stages_active,
                g_d_survivors, g_d_survivor_count, /*overflow=*/NULL,
                KT_MAX_SURVIVORS_PER_BATCH,
                d_cand);
        }
        if (cudaGetLastError() != cudaSuccess) break;
        if (cudaDeviceSynchronize() != cudaSuccess) break;
        cursor += (unsigned __int128)batch_per_launch;
        cudaMemset(g_d_survivor_count, 0, sizeof(unsigned int));
    }
    double dt = wall_time_sec() - t0;
    unsigned long long h_cand = 0;
    cudaMemcpy(&h_cand, d_cand, sizeof h_cand, cudaMemcpyDeviceToHost);
    cudaFree(d_cand);
    if (dt < 1e-6) dt = 1e-6;
    return (double)h_cand / dt;
}

/* Reset GPU state for a new pattern (release + rebuild wheel + filter). */
static int set_pattern_for_validate(const char *name) {
    g_pattern = kt_pattern_by_name(name);
    if (!g_pattern) {
        fprintf(stderr, "ERROR: pattern '%s' not in catalog\n", name);
        return -1;
    }
    g_pattern_name = g_pattern->name;
    g_target_k = g_pattern->k;
    release_filter_tables();
    release_stage0_wheel();
    if (build_and_upload_stage0_wheel() != 0) return -1;
    if (build_and_upload_filter_tables() != 0) return -1;
    return 0;
}

static int run_validate_known(void) {
    if (test_t2_cuda_device() != 0) return 1;

    /* If --validate-known got no positional k but --k N was set, honor it as
     * the validate target — matches the brief's acceptance command shape. */
    if (g_validate_target_k == 0 && g_target_k > 0) {
        g_validate_target_k = g_target_k;
    }

    RecordEntryGpu *recs = NULL;
    int n = load_records_manifest_gpu(&recs, g_validate_target_k);
    if (n < 0) return 1;
    if (n == 0) {
        fprintf(stderr, "No records for k=%d\n", g_validate_target_k);
        free(recs);
        return g_validate_target_k > 0 ? 1 : 0;
    }

    if (g_bench_jsonl_path && !g_bench_jsonl_fp) {
        g_bench_jsonl_fp = fopen(g_bench_jsonl_path, "w");
        if (!g_bench_jsonl_fp) {
            fprintf(stderr, "ERROR: cannot open --bench-jsonl path %s: %s\n",
                    g_bench_jsonl_path, strerror(errno));
            free(recs);
            return 2;
        }
    }

    /* Phase 3f.1: per-record gate. ok_count_by_k counts records actually
     * reproduced in this run; touched_count_by_k counts records walked.
     * The exit gate is `ok==touched` for every k we touched — every walked
     * record must reproduce within budget. */
    int ok_count_by_k[64] = {0};
    int touched_count_by_k[64] = {0};
    int skipped_required_count = 0;  /* W19-A-4 (P1-10/P1-5): wheel-cap skips when --validate-known-require-coverage set */

    /* Default scope: k=16..19; --validate-known K narrows to one k. */
    for (int i = 0; i < n; i++) {
        RecordEntryGpu *r = &recs[i];
        if (g_validate_target_k == 0 && (r->k < 16 || r->k > 19)) continue;
        /* Skip once per-k cap reached, but DO NOT short-circuit on first
         * success: --validate-known is honest about scope only if every
         * record up to the cap is touched. */
        if (touched_count_by_k[r->k] >= g_validate_max_records_per_k) continue;

        /* Skip records whose base would not fit in u128. */
        if (r->bits > 127) {
            printf("[k=%d %s] SKIPPED reason=bits>127 base=%s\n",
                   r->k, r->pattern, r->base_dec);
            continue;
        }
        /* Phase 9 T2.1: at high primorials (47# in particular), wheel
         * construction for lower-k wide patterns (KT19_P0 et al) can hit
         * the 64 GiB host-scratch cap, the INT32 admissible-count cap, or
         * another wheel-build limit and return failure.
         * SKIP rather than FAIL: validate-known stays green for the
         * patterns that fit, while operator gets a clear reason line. */
        if (set_pattern_for_validate(r->pattern) != 0) {
            if (g_primorial_n_primes > 11) {
                printf("[k=%d %s] SKIPPED reason=wheel_build_cap_or_failure @ %u#\n",
                       r->k, r->pattern, kt_first_primes[g_primorial_n_primes]);
                /* W19-A-4 (P1-10/P1-5): --validate-known-require-coverage
                 * elevates wheel-cap skips from "operator advisory" to
                 * "gate failure" so production-primorial sweeps don't
                 * silently lose all internal validation. */
                if (g_validate_known_require_coverage) {
                    skipped_required_count++;
                }
            } else {
                printf("[k=%d %s] FAIL set_pattern\n", r->k, r->pattern);
                touched_count_by_k[r->k]++;
            }
            continue;
        }
        touched_count_by_k[r->k]++;
        g_target_bits = r->bits;

        /* Phase 4b-3: probe with ALL stages enabled (incl. Fermat).
         * v7's wheel-offset-iter design issues every admissible candidate
         * as a real thread, so Fermat actually runs (vs v5/v6 where Stage-0
         * killed 99.99% of threads before Fermat). Disabling Fermat in the
         * probe — the v5/v6 behavior — overestimates v7 throughput by
         * ~2-3×, undersizing prefix_bits and missing records that fall
         * past 60s of true throughput. Keep stages_active as is. */
        double tput = estimate_throughput_gpu(2.0);
        if (tput < 1.0) tput = 1.0;

        /* W6 G25 Fix-A: at smallest k (16-18) the raw-cand throughput probe
         * inflates effective rate by ~2^4..2^8 vs the rate at which the engine
         * actually surfaces a found-base; result is the selector picks a
         * too-shallow prefix and the base hides in a deeper sub-shard never
         * visited within the per-record budget. De-rate tput on the small-k
         * branch so the selector plans a deeper prefix. Default behavior for
         * k>=19 is unchanged. */
        if (r->k <= 18) {
            /* Empirical: estimate_throughput_gpu() returns raw-probe rate
             * (~7.5e18 cand/s on 5090) while the actual cand-processing rate
             * during run_search_loop is ~2.3e16 cand/s — a probe-vs-loop ratio
             * of ~2^8.4. Fix-A de-rates by 2^7..2^9 across k=18..16 so the
             * selector's planned shard matches what the loop can actually
             * sweep within budget. Verified on KT16_P0 base=4.77e19: at 60s
             * budget selector picks prefix_bits=7 (shard 2^59, scan ~23s);
             * at 180s budget picks prefix_bits=5 (shard 2^61, base reached
             * ~70s into 180s). */
            int extra_bits = (18 - r->k) + 7;   /* k=18→7, k=17→8, k=16→9 */
            if (extra_bits > 10) extra_bits = 10;
            if (extra_bits < 0) extra_bits = 0;
            double new_tput = tput / (double)(1ULL << extra_bits);
            fprintf(stderr,
                "[G25-fix] k=%d %s: tput de-rated by 2^%d (%.2e -> %.2e cand/s) "
                "for selector planning\n",
                r->k, r->pattern, extra_bits, tput, new_tput);
            tput = new_tput;
            if (tput < 1.0) tput = 1.0;
        }

        /* Choose prefix_bits so 2^(bits - prefix_bits) candidates fit in the
         * per-record budget (default 60s; T18 bumps to 180s). */
        double budget = g_validate_per_record_budget_sec * tput;
        int needed_prefix_bits;
        if (budget < 1.0) {
            needed_prefix_bits = r->bits - 1;
        } else {
            double log2_budget = log(budget) / log(2.0);
            needed_prefix_bits = (int)ceil((double)r->bits - log2_budget);
            if (needed_prefix_bits < 1) needed_prefix_bits = 1;
            if (needed_prefix_bits > r->bits - 1) needed_prefix_bits = r->bits - 1;
        }

        unsigned __int128 base_u128 = 0;
        if (parse_decimal_u128(r->base_dec, &base_u128) != 0) {
            printf("[k=%d %s] SKIPPED reason=bad_base\n", r->k, r->pattern);
            continue;
        }

        /* prefix = base >> (bits - prefix_bits). If the prefix's leading bit
         * lands below position needed_prefix_bits-1 (which can happen for
         * bases whose top bit isn't at position bits-1), walk needed_prefix_bits
         * down until the prefix has a leading 1. */
        unsigned __int128 prefix = base_u128 >> (r->bits - needed_prefix_bits);
        while (needed_prefix_bits > 1) {
            int top = 0;
            unsigned __int128 t = prefix;
            while (t) { top++; t >>= 1; }
            if (top == needed_prefix_bits) break;
            needed_prefix_bits--;
            prefix = base_u128 >> (r->bits - needed_prefix_bits);
        }

        if (needed_prefix_bits >= r->bits) {
            printf("[k=%d %s] SKIPPED reason=throughput_too_low (tput=%.0f/s)\n",
                   r->k, r->pattern, tput);
            continue;
        }

        g_use_prefix = 1;
        g_prefix_value_u128 = prefix;
        g_prefix_bits = needed_prefix_bits;
        g_max_time_sec = g_validate_per_record_budget_sec;
        g_max_batches = 0;
        g_validate_expected_base = r->base_dec;
        g_validate_hit_seen = 0;
        g_run_cand = 0; g_run_surv = 0; g_run_hits = 0; g_run_elapsed_s = 0.0;

        run_search_loop();

        int hit = g_validate_hit_seen ? 1 : 0;
        char cand_dec[40];
        kt_u128_format_dec(g_run_cand, cand_dec, sizeof cand_dec);
        if (hit) {
            ok_count_by_k[r->k]++;
            printf("[k=%d %s] base=%s OK time=%.1fs prefix_bits=%d tput=%.0f/s "
                   "cand=%s surv=%llu hits=%d\n",
                   r->k, r->pattern, r->base_dec, g_run_elapsed_s,
                   needed_prefix_bits, tput,
                   cand_dec,
                   (unsigned long long)g_run_surv, g_run_hits);
        } else {
            printf("[k=%d %s] base=%s NOTFOUND time=%.1fs prefix_bits=%d cand=%s surv=%llu hits=%d\n",
                   r->k, r->pattern, r->base_dec, g_run_elapsed_s,
                   needed_prefix_bits,
                   cand_dec,
                   (unsigned long long)g_run_surv, g_run_hits);
        }

        if (g_bench_jsonl_fp) {
            char ts[64]; time_t t = time(NULL);
            strftime(ts, sizeof ts, "%Y-%m-%dT%H:%M:%SZ", gmtime(&t));
            double cand_per_s = g_run_elapsed_s > 0
                              ? kt_u128_to_double(g_run_cand) / g_run_elapsed_s : 0.0;
            char seed_str[24];
            if (g_random_chunk_mode) {
                snprintf(seed_str, sizeof seed_str, "0x%016llx",
                         (unsigned long long)g_random_seed_used);
            } else {
                snprintf(seed_str, sizeof seed_str, "n/a");
            }
            int fermat_active = (g_stages_active & KT_STAGE_FERMAT) ? 1 : 0;
            pthread_mutex_lock(&g_bench_jsonl_lock);
            fprintf(g_bench_jsonl_fp,
                "{\"k\":%d,\"pattern\":\"%s\",\"base\":\"%s\",\"bits\":%d,"
                "\"prefix_bits\":%d,\"elapsed_s\":%.4f,"
                "\"cand\":%s,\"surv\":%llu,"
                "\"surv_post_fermat\":%llu,"
                "\"verified\":%d,\"found\":%d,"
                "\"tput_cand_per_s\":%.0f,"
                "\"tput_useful_cand_per_s\":%.3f,"
                "\"useful_cand_per_s\":%.3f,"
                "\"ts_utc\":\"%s\","
                "\"engine\":\"gpu\","
                "\"host\":\"%s\","
                "\"gpu_uuid\":\"%s\","
                "\"cuda_runtime\":%d,"
                "\"primorial\":%d,"
                "\"wheel_expr\":\"%s\","
                "\"wheel_n_admissible\":%d,"
                "\"stages_active\":%u,"
                "\"fermat_active\":%d,"
                "\"gpu_batch_size\":%llu,"
                "\"gpu_streams\":%d,"
                "\"gpu_util_pct\":%.2f,"
                "\"gpu_util_pct_min\":%.2f,"
                "\"total_kernel_ms\":%.3f,"
                "\"total_prove_ms\":%.3f,"
                "\"prove_to_kernel_ratio\":%.4f,"
                "\"wall_time_ms\":%.3f,"
                "\"bench_schema_version\":%d,"
                "\"mode\":\"%s\","
                "\"seed\":\"%s\","
                "\"runner_cell_id\":\"%s\","
                "\"anchors_visited\":%llu,"
                "\"unique_tiles_visited\":%llu,"
                "\"coverage_ratio\":%.6f,"
                "\"revisited_anchors\":%llu,"
                "\"build_sha\":\"%s\","
                "\"binary_name\":\"%s\"}\n",
                r->k, r->pattern, r->base_dec, r->bits,
                needed_prefix_bits, g_run_elapsed_s,
                cand_dec,
                (unsigned long long)g_run_surv,
                (unsigned long long)g_run_surv,
                hit, hit, cand_per_s,
                g_run_useful_cand_per_s, g_run_useful_cand_per_s,
                ts, kt_hostname(), kt_gpu_uuid(), CUDART_VERSION,
                g_primorial_n_primes,
                g_active_wheel_from_expr ? g_active_wheel_expr : "none",
                g_wheel.n_admissible,
                g_stages_active, fermat_active,
                (unsigned long long)g_gpu_batch_size,
                g_gpu_streams,
                g_run_gpu_util_pct, g_run_gpu_util_pct_min,
                g_run_total_kernel_ms, g_run_total_prove_ms,
                g_run_prove_to_kernel_ratio, g_run_wall_time_ms,
                KT_BENCH_SCHEMA_VERSION,
                g_run_mode_str,
                seed_str,
                g_runner_cell_id ? g_runner_cell_id : "n/a",
                g_run_anchors_visited,
                g_run_unique_tiles_visited,
                g_run_coverage_ratio,
                g_run_revisited_anchors,
                KT_BUILD_SHA,
                KT_BINARY_NAME);
            fflush(g_bench_jsonl_fp);
            pthread_mutex_unlock(&g_bench_jsonl_lock);
        }

        g_validate_expected_base = NULL;
        g_max_time_sec = 0.0;
    }

    /* Phase 3f.1: gate_ok iff every touched record reproduced. */
    int gate_ok = 1;
    {
        int kmin = (g_validate_target_k > 0) ? g_validate_target_k : 16;
        int kmax = (g_validate_target_k > 0) ? g_validate_target_k : 19;
        for (int k = kmin; k <= kmax; k++) {
            if (touched_count_by_k[k] > 0 &&
                ok_count_by_k[k] != touched_count_by_k[k]) {
                gate_ok = 0;
            }
        }
    }
    /* W19-A-4 (P1-10/P1-5): if --validate-known-require-coverage was set
     * and any record was SKIPPED due to wheel_build_cap_or_failure (or other
     * structural skips at primorial > 11), fail the gate.  Without this
     * flag, validate-known at --primorial 14 (47#) can silently SKIP every
     * lower-k record whose wheel exceeds the 64 GiB host-scratch cap, INT32
     * admissible-count cap, or another build limit, leaving the production-
     * primorial sweep with ZERO internal validation — exactly the gap identified during review
     * P1-5 flagged. */
    if (g_validate_known_require_coverage && skipped_required_count > 0) {
        printf("[validate-known] FAIL: %d record(s) SKIPPED but "
               "--validate-known-require-coverage required they be covered\n",
               skipped_required_count);
        gate_ok = 0;
    }

    printf("\n=== validate-known summary (engine=gpu) ===\n");
    for (int k = 16; k <= 24; k++) {
        if (touched_count_by_k[k] > 0) {
            int pass = (ok_count_by_k[k] == touched_count_by_k[k]);
            printf("validate-known: k=%d touched=%d ok=%d %s\n",
                   k, touched_count_by_k[k], ok_count_by_k[k],
                   pass ? "PASS" : "FAIL");
        }
    }
    printf("validate-known: gate=%s\n", gate_ok ? "PASS" : "FAIL");

    free(recs);
    if (g_bench_jsonl_fp) {
        fclose(g_bench_jsonl_fp);
        g_bench_jsonl_fp = NULL;
    }
    release_filter_tables();
    release_stage0_wheel();
    return gate_ok ? 0 : 1;
}

/* =============================================================================
 * Phase 3e tests — T18..T20.
 * ========================================================================== */

/* T18: --validate-known --k 16 reproduces at least the first KT16 record
 * (smallest one in the manifest) within 60s. Run in-process: invoke
 * run_validate_known() with target_k=16 + a temp bench-jsonl path. Pass
 * iff at least one row landed AND its found field == 1. */
static int test_t18_validate_known_kt16_smoke(void) {
    if (test_t2_cuda_device() != 0) return 1;
    const char *path = "./tmp/t18_validate_kt16.jsonl";
    (void)mkdir("./tmp", 0755);
    unlink(path);
    int saved_target_k = g_validate_target_k;
    const char *saved_bench = g_bench_jsonl_path;
    int saved_use_prefix = g_use_prefix;
    int saved_full_quiet = g_full_quiet_mode;
    /* G25: bump per-record budget to 180s; the smallest
     * k=16 record's throughput-derived prefix shard occasionally exceeds 60s
     * under startup-probe noise, leaving no found=1 row before the deadline. */
    double saved_per_record_budget = g_validate_per_record_budget_sec;
    g_validate_per_record_budget_sec = 180.0;

    g_validate_target_k = 16;
    g_bench_jsonl_path  = path;
    g_full_quiet_mode   = 1;
    int saved_max = g_validate_max_records_per_k;
    g_validate_max_records_per_k = 1;

    int rc = run_validate_known();
    g_validate_max_records_per_k = saved_max;

    g_validate_target_k = saved_target_k;
    g_bench_jsonl_path  = saved_bench;
    g_use_prefix        = saved_use_prefix;
    g_full_quiet_mode   = saved_full_quiet;
    g_validate_per_record_budget_sec = saved_per_record_budget;

    /* Inspect jsonl for at least one row with "found":1.  Review fix
     * (G25 fallback):  Option A bumped per-record budget to 180s but
     * estimate_throughput_gpu()'s raw-cand/s figure (~2.4e16 on a 5090)
     * inflates the budget so prefix-bit selection lands at 1, leaving the
     * scan ~1500s short of covering KT16_P0's 65-bit shard.  Re-engineering
     * the throughput estimator is out of scope for a reviewed fix, so
     * accept the engine-ran-cleanly-without-finding case as G25-acceptable:
     * row written, cand>0 (kernel actually executed), and no FATAL.  The
     * test still fails on FATAL, missing rows (records.json broken), or a
     * found=1 row whose base differs from the expected KT16 records (those
     * are tracked by validate-known's gate, not asserted here). */
    FILE *fp = fopen(path, "r");
    int any_found = 0, n_rows = 0;
    long long max_cand = 0;
    if (fp) {
        char line[4096];
        while (fgets(line, sizeof line, fp)) {
            n_rows++;
            if (strstr(line, "\"found\":1")) any_found = 1;
            const char *cp = strstr(line, "\"cand\":");
            if (cp) {
                long long c = atoll(cp + strlen("\"cand\":"));
                if (c > max_cand) max_cand = c;
            }
        }
        fclose(fp);
    }
    printf("T18 --validate-known --k 16: rows=%d any_found=%d run_rc=%d "
           "max_cand=%lld\n", n_rows, any_found, rc, max_cand);
    if (n_rows < 1) {
        fprintf(stderr, "T18 FAILED: no rows produced "
                "(records.json missing or load failure)\n");
        return 1;
    }
    if (any_found) {
        fprintf(stderr, "T18 PASS (real path): any_found=1 rows=%d "
                "max_cand=%lld\n", n_rows, max_cand);
        return 0;
    }
    /* G25-tolerant fallback removed 2026-05-10 (W11): now that W6 selector
     * fix (kt_filter_v8.cu:4634) lands real-path PASS reliably, soft-PASS
     * would mask future regressions in the engine selector or budget. */
    fprintf(stderr, "T18 FAIL: any_found=0 (rows=%d, max_cand=%lld); "
            "engine ran prefix shard but did not surface found=1 within "
            "budget. Check W6 selector heuristic at kt_filter_v8.cu:4634.\n",
            n_rows, max_cand);
    return 1;
}

/* T19: --prefix range math. parse_prefix_str("0b1") at bits=60 confines the
 * search to [2^59, 2^60). Verify the math directly. */

/* T20: --bench-jsonl row schema sanity. Run validate-known briefly on k=16,
 * read back one row, assert the required keys are all present. */
static int test_t20_bench_jsonl_schema(void) {
    const char *path = "./tmp/t20_schema.jsonl";
    (void)mkdir("./tmp", 0755);
    unlink(path);
    int saved_target_k = g_validate_target_k;
    const char *saved_bench = g_bench_jsonl_path;
    int saved_full_quiet = g_full_quiet_mode;

    g_validate_target_k = 16;
    g_bench_jsonl_path  = path;
    g_full_quiet_mode   = 1;
    int saved_max = g_validate_max_records_per_k;
    g_validate_max_records_per_k = 1;
    /* Light: don't need a real hit. The row gets written even on NOTFOUND.
     * Only one record runs (~60s). */

    (void)run_validate_known();
    g_validate_max_records_per_k = saved_max;

    g_validate_target_k = saved_target_k;
    g_bench_jsonl_path  = saved_bench;
    g_full_quiet_mode   = saved_full_quiet;

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "T20 FAILED: could not open %s\n", path);
        return 1;
    }
    char line[4096];
    int got_row = 0;
    if (fgets(line, sizeof line, fp)) got_row = 1;
    fclose(fp);
    if (!got_row) {
        fprintf(stderr, "T20 FAILED: no row in %s\n", path);
        return 1;
    }
    static const char *required[] = {
        "\"k\":", "\"pattern\":", "\"base\":", "\"bits\":",
        "\"elapsed_s\":", "\"cand\":", "\"surv\":",
        "\"verified\":", "\"found\":",
        "\"tput_cand_per_s\":", "\"tput_useful_cand_per_s\":", "\"useful_cand_per_s\":",
        "\"ts_utc\":",
        "\"engine\":", "\"host\":", "\"gpu_uuid\":",
        "\"primorial\":", "\"wheel_n_admissible\":",
        "\"stages_active\":", "\"fermat_active\":",
        "\"gpu_util_pct\":", "\"gpu_util_pct_min\":",
        "\"total_kernel_ms\":", "\"total_prove_ms\":",
        "\"prove_to_kernel_ratio\":", "\"wall_time_ms\":",
        "\"bench_schema_version\":",
        "\"build_sha\":",
        NULL
    };
    for (int i = 0; required[i]; i++) {
        if (!strstr(line, required[i])) {
            fprintf(stderr, "T20 FAILED: missing field %s\n", required[i]);
            return 1;
        }
    }
    printf("T20 bench-jsonl schema OK (%d required keys present)\n",
           (int)(sizeof(required)/sizeof(required[0])) - 1);
    return 0;
}

/* =============================================================================
 * Phase 3f tests — T21..T24.
 * ========================================================================== */

/* T21: cudaEvent timing path returns a positive elapsed-ms reading on a
 * trivial scaffold-kernel launch. Smoke for the event-timing wiring in 3f. */
static int test_t21_event_timing(void) {
    if (test_t2_cuda_device() != 0) return 1;
    cudaStream_t s;
    cudaEvent_t e0, e1;
    if (cudaStreamCreate(&s) != cudaSuccess) {
        fprintf(stderr, "T21 FAILED: cudaStreamCreate\n"); return 1;
    }
    if (cudaEventCreate(&e0) != cudaSuccess ||
        cudaEventCreate(&e1) != cudaSuccess) {
        fprintf(stderr, "T21 FAILED: cudaEventCreate\n"); return 1;
    }
    unsigned long long *d = NULL;
    if (cudaMalloc((void**)&d, sizeof(unsigned long long)) != cudaSuccess) {
        fprintf(stderr, "T21 FAILED: cudaMalloc\n"); return 1;
    }
    cudaMemset(d, 0, sizeof(unsigned long long));
    cudaEventRecord(e0, s);
    /* Each thread does 1024 atomic adds to keep the kernel non-trivially
     * short so the elapsed reading is a real positive number. */
    kt_scaffold_count_kernel<<<256, 256, 0, s>>>(d, 1024ULL);
    cudaEventRecord(e1, s);
    cudaStreamSynchronize(s);
    float ms = 0.0f;
    cudaError_t er = cudaEventElapsedTime(&ms, e0, e1);
    cudaFree(d);
    cudaEventDestroy(e0); cudaEventDestroy(e1);
    cudaStreamDestroy(s);
    if (er != cudaSuccess) {
        fprintf(stderr, "T21 FAILED: cudaEventElapsedTime rc=%d\n", (int)er);
        return 1;
    }
    if (!(ms > 0.0f) || !(ms < 60000.0f)) {
        fprintf(stderr, "T21 FAILED: implausible elapsed ms=%.4f\n", ms);
        return 1;
    }
    printf("T21 cudaEvent timing OK (kernel %.3f ms)\n", ms);
    return 0;
}

/* T22: prefix clamp. Configure a tiny --prefix range that fits in fewer
 * candidates than batch_per_launch; assert run_search_loop terminates with
 * exactly that many issued cand (no overrun). */
static int test_t22_prefix_clamp(void) {
    if (test_t2_cuda_device() != 0) return 1;
    /* Phase 3f.1: KT19_P0 instead of KT5_P0. KT5_P0 + 37# overflows
     * KT_WHEEL_MAX_ADMISSIBLE (T15 documents this); KT19_P0 + 37# is the
     * production wheel and fits the cap. T22 is a structural prefix-clamp
     * test — pattern doesn't matter as long as the wheel builds. */
    if (set_pattern_for_validate("KT19_P0") != 0) {
        fprintf(stderr, "T22 FAILED: set_pattern_for_validate\n"); return 1;
    }
    int saved_target_bits = g_target_bits;
    int saved_use_prefix = g_use_prefix;
    int saved_prefix_bits = g_prefix_bits;
    unsigned __int128 saved_prefix_val = g_prefix_value_u128;
    double saved_max_time = g_max_time_sec;
    int saved_max_batches = g_max_batches;
    u64 saved_batch_size = g_gpu_batch_size;
    int saved_full_quiet = g_full_quiet_mode;

    /* Force a tiny range: bits=100, prefix bits=100, prefix's leading bit
     * at position 99 → range_end - cursor = 1. batch_per_launch = 65535*256
     * = 16.77M, so the clamp must cap to 1. */
    g_target_bits = 100;
    g_use_prefix = 1;
    g_prefix_bits = 100;
    g_prefix_value_u128 = ((unsigned __int128)1) << 99;
    g_max_time_sec = 5.0;
    g_max_batches = 1;
    g_gpu_batch_size = (u64)1 << 19;     /* default */
    g_full_quiet_mode = 1;

    int rc = run_search_loop();

    g_target_bits = saved_target_bits;
    g_use_prefix = saved_use_prefix;
    g_prefix_bits = saved_prefix_bits;
    g_prefix_value_u128 = saved_prefix_val;
    g_max_time_sec = saved_max_time;
    g_max_batches = saved_max_batches;
    g_gpu_batch_size = saved_batch_size;
    g_full_quiet_mode = saved_full_quiet;

    if (rc != 0) {
        fprintf(stderr, "T22 FAILED: run_search_loop rc=%d\n", rc);
        return 1;
    }
    /* Phase 4b-3: clamp granularity is primorial (one tile = one wheel
     * period). The "1-candidate prefix" is rounded up to a single tile.
     * v7's contract: cand == primorial after exactly one launch on a
     * sub-primorial prefix range. */
    unsigned long long expected_t22 = g_wheel.primorial;
    if (g_run_cand != expected_t22) {
        fprintf(stderr,
            "T22 FAILED: prefix-clamp expected cand=%llu (one tile=primorial) "
            "but got %llu\n",
            expected_t22, (unsigned long long)g_run_cand);
        return 1;
    }
    printf("T22 prefix-clamp OK (cand=%llu = 1 tile = primorial)\n",
           (unsigned long long)g_run_cand);
    return 0;
}

/* T23: survivor overflow exits the process. Simulated by writing 1 directly
 * to a pinned-host overflow flag and exercising the same fail-fast path the
 * search loop uses. We do not actually run the kernel to overflow because
 * KT_MAX_SURVIVORS_PER_BATCH = 1M survivors is impractical to provoke from
 * a unit test. Instead: check that the ERROR + exit(1) path is wired by
 * fork()-running a small probe that flips the flag and asserts exit-code 1.
 *
 * Implementation note: forking from a CUDA-initialized process is fragile,
 * so we test the predicate logic only — the search loop's "if n_overflow
 * != 0u: exit(1)" is a single line with no side effects to verify
 * separately. We assert that a freshly-zeroed overflow flag stays zero
 * after a clean kernel launch (no false positive), and that atomicOr from
 * a kernel does set it. The "would call exit(1)" branch is exercised
 * implicitly by the search loop when the buffer truly overflows in a real
 * run — which does not happen in our test configuration. */
__global__ void kt_set_overflow_kernel(unsigned int *flag) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        atomicOr(flag, 1u);
    }
}

static int test_t23_survivor_overflow_signal(void) {
    if (test_t2_cuda_device() != 0) return 1;
    unsigned int *d_flag = NULL;
    unsigned int  h_flag = 0;
    if (cudaMalloc((void**)&d_flag, sizeof(unsigned int)) != cudaSuccess) {
        fprintf(stderr, "T23 FAILED: cudaMalloc\n"); return 1;
    }
    cudaMemset(d_flag, 0, sizeof(unsigned int));
    /* Clean baseline: no kernel write -> flag stays 0. */
    cudaMemcpy(&h_flag, d_flag, sizeof(unsigned int), cudaMemcpyDeviceToHost);
    if (h_flag != 0u) {
        fprintf(stderr, "T23 FAILED: baseline flag != 0 (%u)\n", h_flag);
        cudaFree(d_flag); return 1;
    }
    /* Now set it from a kernel and confirm host reads non-zero. */
    kt_set_overflow_kernel<<<1, 1>>>(d_flag);
    cudaDeviceSynchronize();
    cudaMemcpy(&h_flag, d_flag, sizeof(unsigned int), cudaMemcpyDeviceToHost);
    cudaFree(d_flag);
    if (h_flag == 0u) {
        fprintf(stderr,
            "T23 FAILED: atomicOr from kernel did not set flag\n");
        return 1;
    }
    printf("T23 survivor-overflow signal OK (atomicOr propagates)\n");
    return 0;
}

/* T24: double-buffered streams round-trip. Run two batches via run_search_loop
 * on KT5_P0 with --max-batches=2 and assert the cand count equals
 * 2 * batch_per_launch (or the clamped value). Surv count is non-negative.
 * This exercises the priming, prev-process, drain code paths. */
static int test_t24_streamed_round_trip(void) {
    if (test_t2_cuda_device() != 0) return 1;
    /* Phase 3f.1: KT19_P0 (production wheel; fits 37# cap). KT5_P0 + 37#
     * overflows KT_WHEEL_MAX_ADMISSIBLE — see T22 note. */
    if (set_pattern_for_validate("KT19_P0") != 0) {
        fprintf(stderr, "T24 FAILED: set_pattern_for_validate\n"); return 1;
    }
    int saved_target_bits = g_target_bits;
    int saved_use_prefix = g_use_prefix;
    int saved_max_batches = g_max_batches;
    double saved_max_time = g_max_time_sec;
    u64 saved_batch_size = g_gpu_batch_size;
    int saved_full_quiet = g_full_quiet_mode;

    g_target_bits = 100;
    g_use_prefix = 0;
    g_max_batches = 2;
    g_max_time_sec = 0.0;
    g_gpu_batch_size = (u64)1 << 18;
    g_full_quiet_mode = 1;

    int rc = run_search_loop();

    /* Phase 4b-3: v7 reports cand as raw integers covered. Per launch we
     * cover n_tiles_default × primorial. With g_gpu_batch_size = 2^18 and
     * threads_per_tile = ceil(n_admissible/256) × 256 = 1040 × 256 =
     * 266240, n_tiles_default = max(1, 2^18 / 266240) = 1. Two launches
     * cover 2 × primorial. Surv count is non-negative; util may be low. */
    int block_t24 = 256;
    int n_admissible_t24 = g_wheel.n_admissible;
    unsigned long long primorial_t24 = g_wheel.primorial;
    unsigned int gridY_t24 =
        (unsigned int)((n_admissible_t24 + block_t24 - 1) / block_t24);
    unsigned long long threads_per_tile_t24 =
        (unsigned long long)gridY_t24 * (unsigned long long)block_t24;
    unsigned int n_tiles_default_t24 = 1;
    if (threads_per_tile_t24 > 0) {
        unsigned long long t = g_gpu_batch_size / threads_per_tile_t24;
        if (t < 1) t = 1;
        if (t > 1024) t = 1024;
        n_tiles_default_t24 = (unsigned int)t;
    }
    unsigned long long expected_per_batch =
        (unsigned long long)n_tiles_default_t24 * primorial_t24;
    unsigned long long expected_total = 2ULL * expected_per_batch;

    g_target_bits = saved_target_bits;
    g_use_prefix = saved_use_prefix;
    g_max_batches = saved_max_batches;
    g_max_time_sec = saved_max_time;
    g_gpu_batch_size = saved_batch_size;
    g_full_quiet_mode = saved_full_quiet;

    if (rc != 0) {
        fprintf(stderr, "T24 FAILED: run_search_loop rc=%d\n", rc);
        return 1;
    }
    if (g_run_cand != expected_total) {
        fprintf(stderr,
            "T24 FAILED: cand=%llu expected=%llu\n",
            (unsigned long long)g_run_cand, expected_total);
        return 1;
    }
    /* GPU-util can be < 95% on this micro-run (overhead-dominated), but
     * total_kernel_ms must be > 0 — proves the event path fired. */
    if (g_run_total_kernel_ms <= 0.0) {
        fprintf(stderr,
            "T24 FAILED: total_kernel_ms=%.3f (event path not firing)\n",
            g_run_total_kernel_ms);
        return 1;
    }
    printf("T24 streamed round-trip OK (cand=%llu kernel_ms=%.3f util=%.1f%%)\n",
           (unsigned long long)g_run_cand,
           g_run_total_kernel_ms, g_run_gpu_util_pct);
    return 0;
}

/* =============================================================================
 * Phase 4a-3 test — T25: Barrett kt_u128_mod_u64_barrett vs shift-loop.
 *
 * Sweeps a representative set of (a, m) pairs through both the original
 * shift-loop reduction (kt_u128_mod_u64) and the Barrett variant
 * (kt_u128_mod_u64_barrett with mu = floor(2^128/m) computed on host).
 * Failure if any pair disagrees. Cases include:
 *   - small dividend (a < m, hi=0 fast path)
 *   - large dividend with hi != 0
 *   - a near 2^128-1, a == 0, a == m-1
 *   - moduli: m=2, 3, m=2^32, m=2^32+15, large prime, KT19_P0 primorial(37#)
 * ========================================================================== */
__global__ void kt_test_mod_u64_barrett_kernel(kt_u128 a, uint64_t m, kt_u128 mu,
                                               uint64_t *out_barrett,
                                               uint64_t *out_shift) {
    if (threadIdx.x == 0 && blockIdx.x == 0) {
        *out_barrett = kt_u128_mod_u64_barrett(a, m, mu);
        *out_shift   = kt_u128_mod_u64(a, m);
    }
}

static int test_t25_barrett_mod_u64_vs_shift(void) {
    if (test_t2_cuda_device() != 0) return 1;

    uint64_t *d_barrett = NULL, *d_shift = NULL;
    CUDA_CHECK(cudaMalloc((void**)&d_barrett, sizeof(uint64_t)));
    CUDA_CHECK(cudaMalloc((void**)&d_shift,   sizeof(uint64_t)));

    /* Build the (a, m) test sweep. */
    struct { uint64_t a_lo, a_hi, m; } cases[] = {
        /* hi == 0 fast path */
        { 0,                     0, 7420738134810ULL },     /* a=0 */
        { 1,                     0, 7420738134810ULL },
        { 7420738134809ULL,      0, 7420738134810ULL },     /* a == m-1 */
        { 7420738134811ULL,      0, 7420738134810ULL },     /* a == m+1 */
        /* hi != 0 slow path, primorial-37# modulus */
        { 0,                     1ULL, 7420738134810ULL },  /* a = 2^64 */
        { 0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, 7420738134810ULL }, /* a = 2^128-1 */
        { 0x123456789ABCDEF0ULL, 0x0000000000000001ULL, 7420738134810ULL },
        { 0xDEADBEEFCAFEBABEULL, 0xFEEDFACE12345678ULL, 7420738134810ULL },
        /* m = 2 (smallest valid; mu = 2^127) */
        { 0,                     0, 2ULL },
        { 1,                     0, 2ULL },
        { 0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, 2ULL },
        /* m = 3 (small odd) */
        { 0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, 3ULL },
        /* m = 2^32 */
        { 0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, (uint64_t)1ULL << 32 },
        /* m = 2^32 + 15 (prime, awkward) */
        { 0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, ((uint64_t)1ULL << 32) + 15ULL },
        /* m = large prime near 2^43 */
        { 0xCAFEBABEDEADBEEFULL, 0x1234567890ABCDEFULL, 8796093022217ULL },
        /* m = 2^63 (large modulus exercising mu_hi small) */
        { 0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, (uint64_t)1ULL << 63 },
        /* m = 2^63 + 1 — upper bound of the well-defined range for both
         *   the original kt_u128_mod_u64 shift-loop (its inner `r <<= 1`
         *   overflows once m > 2^63) and our Barrett (q.lo*m wraps u64
         *   in the same regime). Production use (m = 37# ≈ 2^43) is well
         *   below this, so we restrict T25 to m ≤ 2^63 + 1. */
        { 0xFFFFFFFFFFFFFFFFULL, 0xFFFFFFFFFFFFFFFFULL, ((uint64_t)1ULL << 63) + 1ULL },
    };
    int n_cases = (int)(sizeof cases / sizeof cases[0]);

    int failed = 0;
    for (int i = 0; i < n_cases; i++) {
        kt_u128 a;
        a.lo = cases[i].a_lo;
        a.hi = cases[i].a_hi;
        uint64_t m = cases[i].m;

        /* Compute mu = floor(2^128 / m) on host using __int128. */
        unsigned __int128 mu128 =
            ((unsigned __int128)0 - (unsigned __int128)m) / m + 1;
        kt_u128 mu;
        mu.lo = (uint64_t)mu128;
        mu.hi = (uint64_t)(mu128 >> 64);

        kt_test_mod_u64_barrett_kernel<<<1,1>>>(a, m, mu, d_barrett, d_shift);
        CUDA_CHECK(cudaGetLastError());
        CUDA_CHECK(cudaDeviceSynchronize());

        uint64_t r_barrett = 0, r_shift = 0;
        CUDA_CHECK(cudaMemcpy(&r_barrett, d_barrett, sizeof r_barrett, cudaMemcpyDeviceToHost));
        CUDA_CHECK(cudaMemcpy(&r_shift,   d_shift,   sizeof r_shift,   cudaMemcpyDeviceToHost));

        /* Host reference via __int128. */
        unsigned __int128 a128 =
            ((unsigned __int128)cases[i].a_hi << 64) | (unsigned __int128)cases[i].a_lo;
        uint64_t r_host = (uint64_t)(a128 % (unsigned __int128)m);

        if (r_barrett != r_shift || r_barrett != r_host) {
            fprintf(stderr,
                "T25 FAILED case[%d]: a=(0x%016llx,0x%016llx) m=%llu "
                "barrett=%llu shift=%llu host=%llu\n",
                i,
                (unsigned long long)cases[i].a_hi,
                (unsigned long long)cases[i].a_lo,
                (unsigned long long)m,
                (unsigned long long)r_barrett,
                (unsigned long long)r_shift,
                (unsigned long long)r_host);
            failed++;
        }
    }

    cudaFree(d_barrett); cudaFree(d_shift);
    if (failed) return 1;
    printf("T25 Barrett kt_u128_mod_u64_barrett vs shift-loop: %d/%d cases agree\n",
           n_cases, n_cases);
    return 0;
}

/* =============================================================================
 * Phase 3f.2 tests — T26 (G1: --bits>=127 + Fermat) and T27 (G2: --bits<10 +
 * line-sieve). Both capture kt_emit_envelope_warnings output to a tmpfile and
 * assert the diagnostic fires (or stays silent) at the right bit-width and
 * stage-mask combo. Warning-emission tests, not math-correctness tests of the
 * underlying envelope edge.
 * ========================================================================== */
/* kt_emit_envelope_warnings: forward decl now in kt_cli.h (linkage `extern "C"`). */




/* T28: useful_cand_per_s metric self-test. Run one batch, then verify that
 * g_run_useful_cand_per_s == tiles_completed * wheel_n_admissible / elapsed_s
 * within floating-point tolerance (1e-9 relative). */
static int test_t28_useful_cand_metric(void) {
    if (test_t2_cuda_device() != 0) return 1;
    if (set_pattern_for_validate("KT19_P0") != 0) {
        fprintf(stderr, "T28 FAILED: set_pattern_for_validate\n"); return 1;
    }
    int saved_target_bits    = g_target_bits;
    int saved_use_prefix     = g_use_prefix;
    int saved_prefix_bits    = g_prefix_bits;
    unsigned __int128 saved_prefix_val = g_prefix_value_u128;
    double saved_max_time    = g_max_time_sec;
    int saved_max_batches    = g_max_batches;
    u64 saved_batch_size     = g_gpu_batch_size;
    int saved_full_quiet     = g_full_quiet_mode;

    /* One-batch deterministic run: small prefix so it terminates quickly. */
    g_target_bits         = 100;
    g_use_prefix          = 1;
    g_prefix_bits         = 100;
    g_prefix_value_u128   = ((unsigned __int128)1) << 99;
    g_max_time_sec        = 10.0;
    g_max_batches         = 1;
    g_gpu_batch_size      = (u64)1 << 19;
    g_full_quiet_mode     = 1;

    int rc = run_search_loop();

    g_target_bits         = saved_target_bits;
    g_use_prefix          = saved_use_prefix;
    g_prefix_bits         = saved_prefix_bits;
    g_prefix_value_u128   = saved_prefix_val;
    g_max_time_sec        = saved_max_time;
    g_max_batches         = saved_max_batches;
    g_gpu_batch_size      = saved_batch_size;
    g_full_quiet_mode     = saved_full_quiet;

    if (rc != 0) {
        fprintf(stderr, "T28 FAILED: run_search_loop rc=%d\n", rc);
        return 1;
    }
    if (g_wheel.primorial == 0 || g_wheel.n_admissible == 0) {
        fprintf(stderr, "T28 FAILED: wheel not initialised\n"); return 1;
    }
    if (g_run_elapsed_s <= 0.0) {
        fprintf(stderr, "T28 FAILED: elapsed_s=%.6f\n", g_run_elapsed_s); return 1;
    }
    /* tiles_completed = raw_cand / primorial (exact integer) */
    unsigned long long tiles = (unsigned long long)g_run_cand / g_wheel.primorial;
    double expected_useful = (double)tiles * (double)g_wheel.n_admissible / g_run_elapsed_s;
    double got_useful      = g_run_useful_cand_per_s;
    /* Allow 1e-9 relative tolerance for double arithmetic order differences. */
    double rel_err = (expected_useful > 0.0)
        ? (got_useful - expected_useful) / expected_useful : got_useful;
    if (rel_err < -1e-9 || rel_err > 1e-9) {
        fprintf(stderr,
            "T28 FAILED: useful_cand_per_s mismatch: got=%.6e expected=%.6e rel_err=%e\n",
            got_useful, expected_useful, rel_err);
        return 1;
    }
    printf("T28 useful_cand_per_s metric OK (tiles=%llu n_admissible=%d "
           "elapsed=%.3fs useful/s=%.3e)\n",
           tiles, g_wheel.n_admissible, g_run_elapsed_s, got_useful);
    return 0;
}

/* T29: F18 OFF-path verification. With g_f18_yield_enabled=0, run one batch
 * and verify d_f18_yield_counters remain all-zero (branch was never taken). */
static int test_t29_f18_off_path(void) {
    if (test_t2_cuda_device() != 0) return 1;
    if (set_pattern_for_validate("KT19_P0") != 0) {
        fprintf(stderr, "T29 FAILED: set_pattern_for_validate\n"); return 1;
    }
    int saved_f18 = g_f18_yield_enabled;
    int saved_target_bits  = g_target_bits;
    int saved_use_prefix   = g_use_prefix;
    int saved_prefix_bits  = g_prefix_bits;
    unsigned __int128 saved_prefix_val = g_prefix_value_u128;
    double saved_max_time  = g_max_time_sec;
    int saved_max_batches  = g_max_batches;
    u64 saved_batch_size   = g_gpu_batch_size;
    int saved_full_quiet   = g_full_quiet_mode;

    g_f18_yield_enabled = 0;   /* explicitly OFF */
    g_target_bits       = 100;
    g_use_prefix        = 1;
    g_prefix_bits       = 100;
    g_prefix_value_u128 = ((unsigned __int128)1) << 99;
    g_max_time_sec      = 10.0;
    g_max_batches       = 1;
    g_gpu_batch_size    = (u64)1 << 19;
    g_full_quiet_mode   = 1;

    /* Zero device counters before run (guards against prior test state). */
    {
        static unsigned long long z[KT_LINE_COUNT][KT_F18_MAX_RES];
        memset(z, 0, sizeof(z));
        cudaMemcpyToSymbol(d_f18_yield_counters, z, sizeof(z));
        int off = 0;
        cudaMemcpyToSymbol(d_f18_yield_enabled, &off, sizeof(int));
    }

    int rc = run_search_loop();

    g_f18_yield_enabled  = saved_f18;
    g_target_bits        = saved_target_bits;
    g_use_prefix         = saved_use_prefix;
    g_prefix_bits        = saved_prefix_bits;
    g_prefix_value_u128  = saved_prefix_val;
    g_max_time_sec       = saved_max_time;
    g_max_batches        = saved_max_batches;
    g_gpu_batch_size     = saved_batch_size;
    g_full_quiet_mode    = saved_full_quiet;

    if (rc != 0) {
        fprintf(stderr, "T29 FAILED: run_search_loop rc=%d\n", rc); return 1;
    }
    /* Copy counters back and verify all zero. */
    static unsigned long long buf29[KT_LINE_COUNT][KT_F18_MAX_RES];
    cudaError_t ce = cudaMemcpyFromSymbol(buf29, d_f18_yield_counters, sizeof(buf29));
    if (ce != cudaSuccess) {
        fprintf(stderr, "T29 FAILED: cudaMemcpyFromSymbol: %s\n",
                cudaGetErrorString(ce)); return 1;
    }
    for (int ls = 0; ls < KT_LINE_COUNT; ls++) {
        for (int r = 0; r < KT_F18_MAX_RES; r++) {
            if (buf29[ls][r] != 0) {
                fprintf(stderr, "T29 FAILED: counter[%d][%d]=%llu non-zero with F18 OFF\n",
                        ls, r, buf29[ls][r]);
                return 1;
            }
        }
    }
    printf("T29 F18 OFF-path: counters all-zero after 1 batch (F18 disabled correctly)\n");
    return 0;
}

